// GENERATED by scripts/build-demo-backend.mjs from apps-script/*.gs — do not edit.
/* eslint-disable */
// @ts-nocheck
export function createGasBackend(SpreadsheetApp, CacheService, LockService, PropertiesService, ContentService, DriveApp, Utilities, Logger, console) {
// ---- Activities.gs ----
// Activities.gs — every call / WhatsApp / visit / note on a Medpass or
// Pharmacy record, in the SaleActivities tab (created on first use).
//
// Contact attempts are never typed in — they're counted from this log.
// Logging an outcome also moves the record along:
//   Interested                         → temperature Hot
//   Not interested / Wrong number      → Cancelled with that lost reason
//   customer got back (Incoming, or a
//   reopen request) on a Cancelled one → reopened as a Hot lead

var ACTIVITY_HEADERS = ['ID', 'SaleID', 'SaleType', 'Date', 'ByEmail', 'ByName', 'Type', 'Direction', 'Outcome', 'Notes', 'NextFollowUp'];
// Contact types that count as "reaching out" — blocked when a customer is marked Do Not Call.
var DND_BLOCKED_TYPES = ['Call', 'WhatsApp', 'SMS'];

function getActivitiesSheet() { return getOrCreateSheet('SaleActivities', ACTIVITY_HEADERS); }

function activityForClient(a) {
  return {
    ID: String(a.ID),
    SaleID: String(a.SaleID),
    Date: isoString(a.Date),
    ByEmail: String(a.ByEmail || ''),
    ByName: String(a.ByName || ''),
    Type: String(a.Type || 'Note'),
    Direction: String(a.Direction || ''),
    Outcome: String(a.Outcome || ''),
    Notes: String(a.Notes || ''),
    NextFollowUp: dateKey(a.NextFollowUp)
  };
}

function activitiesBySale() {
  var map = {};
  sheetToObjects(getActivitiesSheet()).forEach(function (a) {
    var k = String(a.SaleID);
    (map[k] = map[k] || []).push(a);
  });
  return map;
}

// Newest first; rows logged in the same millisecond keep sheet order.
function activitiesForSale(saleId) {
  var acts = sheetToObjects(getActivitiesSheet())
    .map(function (a, i) { a._row = i; return a; })
    .filter(function (a) { return String(a.SaleID) === String(saleId); });
  acts.sort(function (a, b) { return (new Date(b.Date) - new Date(a.Date)) || (b._row - a._row); });
  return acts;
}

function addActivity(session, type, saleId, fields) {
  var row = {
    ID: newId(), SaleID: saleId, SaleType: type, Date: nowIso(),
    ByEmail: session.email, ByName: session.name,
    Type: 'Note', Direction: '', Outcome: '', Notes: '', NextFollowUp: ''
  };
  Object.keys(fields || {}).forEach(function (k) { row[k] = fields[k]; });
  appendObject(getActivitiesSheet(), row);
  return row;
}

function svc_logSaleActivity(session, type, saleId, data) {
  var sheet = getSaleSheet(type);
  var sale = requireSale(session, type, saleId);

  var actType = String(data.type || '');
  requireOneOf(actType, ACTIVITY_TYPES, 'Type');
  var direction = '';
  var outcome = '';
  if (actType !== 'Note') {
    direction = String(data.direction || 'Outgoing');
    outcome = String(data.outcome || 'Connected');
    requireOneOf(direction, ACTIVITY_DIRECTIONS, 'Direction');
    requireOneOf(outcome, ACTIVITY_OUTCOMES, 'Outcome');
  }
  var notes = cleanText(data.notes, MAX_LONG_TEXT);
  if (actType === 'Note' && !notes) throw new Error('A note needs some text.');
  if (asBool(sale.DoNotCall) && direction === 'Outgoing' && DND_BLOCKED_TYPES.indexOf(actType) !== -1) {
    throw new ForbiddenError('This customer is marked Do Not Call. Only record contact they started (Incoming), or remove the flag if they have agreed to be contacted.');
  }
  var nextFollowUp = optionalDateKey(data.nextFollowUp, 'Next follow-up');
  var statusUpdate = String(data.statusUpdate || '');

  // Agents can log calls on their Completed sales (after-sales follow-up),
  // but those never change the sale itself.
  var patch = {};
  var auditAction = null;
  var auditSummary = '';
  var label = (direction ? direction + ' ' : '') + actType + (outcome ? ' — ' + outcome : '');

  if (sale.Status === 'Cancelled' && (direction === 'Incoming' || outcome === 'Interested' || statusUpdate === 'reopen_pending')) {
    var world = loadPatientWorld();
    var own = reopenOwnership(session, world, type, sale);
    patch = { Status: 'Pending', LostReason: '', Temperature: 'Hot' };
    Object.keys(own).forEach(function (k) { patch[k] = own[k]; });
    savePatientChanges(world);
    auditAction = 'reopen';
    auditSummary = 'Customer got back in touch (' + label + '). Reopened as a Hot lead.' +
      (own.AgentName ? ' Moved to ' + own.AgentName + ', who handles this patient now.' : '');
  } else if (sale.Status === 'Pending') {
    if (outcome === 'Not interested' || outcome === 'Wrong number' || statusUpdate === 'cancel') {
      var lists = getLists();
      var reason = lists.lostReasons.indexOf(outcome) !== -1 ? outcome :
        (lists.lostReasons.indexOf('Other') !== -1 ? 'Other' : lists.lostReasons[0]);
      patch = { Status: 'Cancelled', LostReason: reason, NextFollowUp: '' };
      auditAction = 'cancel';
      auditSummary = 'Lost during ' + label + '. Moved to Cancelled.';
    } else if (outcome === 'Interested' && sale.Temperature !== 'Hot') {
      patch = { Temperature: 'Hot' };
      auditAction = 'update';
      auditSummary = 'Customer showed strong interest (' + label + '). Temperature set to Hot.';
    }
  }
  var finalStatus = patch.Status || sale.Status;
  if (nextFollowUp && finalStatus === 'Pending') patch.NextFollowUp = nextFollowUp;

  addActivity(session, type, sale.ID, {
    Type: actType, Direction: direction, Outcome: outcome, Notes: notes, NextFollowUp: nextFollowUp
  });

  if (Object.keys(patch).length) {
    patch.UpdatedAt = nowIso();
    var updated = updateObjectById(sheet, sale.ID, patch);
    afterSaleSaved(type, updated);
    if (auditAction) audit(session, auditAction, saleEntity(type), sale.ID, saleChanges(sale, patch), auditSummary);
    sale = updated;
  }
  return saleDetail(session, type, sale);
}


// ---- Attachments.gs ----
// Attachments.gs — stores bill/payment screenshots in Google Drive.
//
// Files are PRIVATE to the account the script runs as — they are never
// shared by link. The app shows a screenshot by asking the backend for it
// (action "getAttachment"), which checks the viewer's session and that they
// are allowed to see that sale before returning the image. So a copied or
// leaked Drive link is useless to anyone outside the sheet owner's account.
//
// Screenshots uploaded before this change were shared "anyone with the
// link". Run lockDownExistingAttachments() once from the Apps Script editor
// (see Setup.gs) to make those private too.

var ATTACHMENTS_FOLDER_NAME = 'MedUnited Sales CRM Attachments';
var ATTACHMENT_MAX_BYTES = 5 * 1024 * 1024; // 5MB
var ALLOWED_IMAGE_TYPES = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp', 'image/gif'];

function getAttachmentsFolder() {
  var folders = DriveApp.getFoldersByName(ATTACHMENTS_FOLDER_NAME);
  if (folders.hasNext()) return folders.next();
  return DriveApp.createFolder(ATTACHMENTS_FOLDER_NAME);
}

// dataUrl looks like "data:image/png;base64,AAAA..."; filenamePrefix should
// not include an extension (one is added based on the image's mime type).
function saveAttachmentFromDataUrl(dataUrl, filenamePrefix) {
  if (!dataUrl) return null;

  var match = /^data:([^;]+);base64,(.*)$/.exec(dataUrl);
  if (!match) throw new Error('Invalid image data.');

  var mimeType = match[1];
  if (ALLOWED_IMAGE_TYPES.indexOf(mimeType) === -1) {
    throw new Error('Only image files (PNG, JPG, WEBP, GIF) are allowed for screenshots.');
  }

  if (match[2].length > Math.ceil(ATTACHMENT_MAX_BYTES * 4 / 3) + 8) {
    throw new Error('Image is too large (max 5MB). Please compress or crop the screenshot.');
  }
  var bytes = Utilities.base64Decode(match[2]);
  if (bytes.length > ATTACHMENT_MAX_BYTES) {
    throw new Error('Image is too large (max 5MB). Please compress or crop the screenshot.');
  }
  // Check the file really is the image type it claims to be, so nothing
  // else (HTML, scripts, documents) can be smuggled into Drive.
  if (!looksLikeImage(bytes, mimeType)) throw new Error('That file is not a valid image.');

  var ext = mimeType === 'image/jpg' ? 'jpeg' : mimeType.split('/')[1];
  var blob = Utilities.newBlob(bytes, mimeType, filenamePrefix + '.' + ext);
  var file = getAttachmentsFolder().createFile(blob);
  file.setSharing(DriveApp.Access.PRIVATE, DriveApp.Permission.NONE);
  return file.getUrl();
}

function looksLikeImage(bytes, mimeType) {
  function b(i) { return bytes[i] & 0xFF; }
  if (bytes.length < 12) return false;
  if (mimeType === 'image/png') return b(0) === 0x89 && b(1) === 0x50 && b(2) === 0x4E && b(3) === 0x47;
  if (mimeType === 'image/jpeg' || mimeType === 'image/jpg') return b(0) === 0xFF && b(1) === 0xD8 && b(2) === 0xFF;
  if (mimeType === 'image/gif') return b(0) === 0x47 && b(1) === 0x49 && b(2) === 0x46;
  if (mimeType === 'image/webp') return b(0) === 0x52 && b(1) === 0x49 && b(2) === 0x46 && b(3) === 0x46 && b(8) === 0x57 && b(9) === 0x45 && b(10) === 0x42 && b(11) === 0x50;
  return false;
}

// Pulls the Drive file ID out of the URL stored in the sheet
// (https://drive.google.com/file/d/<id>/view... or ...?id=<id>).
function driveFileIdFromUrl(url) {
  var m = /\/d\/([a-zA-Z0-9_-]+)/.exec(String(url)) || /[?&]id=([a-zA-Z0-9_-]+)/.exec(String(url));
  return m ? m[1] : null;
}

// Returns the image as a data URL. Caller must already have checked that
// the viewer is allowed to see the sale this file belongs to.
function readAttachmentAsDataUrl(url) {
  var fileId = driveFileIdFromUrl(url);
  if (!fileId) throw new Error('Attachment link is not a Drive file.');

  var file = DriveApp.getFileById(fileId);
  var parents = file.getParents();
  var inFolder = false;
  while (parents.hasNext()) {
    if (parents.next().getName() === ATTACHMENTS_FOLDER_NAME) { inFolder = true; break; }
  }
  if (!inFolder) throw new Error('Attachment is not in the CRM attachments folder.');

  var blob = file.getBlob();
  if (ALLOWED_IMAGE_TYPES.indexOf(blob.getContentType()) === -1) throw new Error('Attachment is not an image.');
  return {
    name: file.getName(),
    dataUrl: 'data:' + blob.getContentType() + ';base64,' + Utilities.base64Encode(blob.getBytes())
  };
}


// ---- Audit.gs ----
// Audit.gs — append-only change log.
//
// Every write through the app (sales, users, incentive rates, reminders,
// account lockouts) adds one row to the AuditLog tab: who did it, when,
// and which fields changed from what to what. The tab is created on first
// use and protected so only the sheet owner (the account the script runs
// as) can edit it — other people with edit access to the spreadsheet can
// read it but can't quietly rewrite history.

var AUDIT_SHEET_NAME = 'AuditLog';
var AUDIT_HEADERS = ['Timestamp', 'UserEmail', 'UserName', 'Role', 'Action', 'Entity', 'EntityID', 'Changes', 'Summary', 'ID'];

// Never copy these into the log, even as "changed".
var AUDIT_SKIP_FIELDS = ['PasswordHash', 'Salt'];

function getAuditSheet() {
  var ss = getSpreadsheet();
  var sheet = ss.getSheetByName(AUDIT_SHEET_NAME);
  if (sheet) { ensureHeaders(sheet, AUDIT_HEADERS); return sheet; }

  sheet = ss.insertSheet(AUDIT_SHEET_NAME);
  sheet.getRange(1, 1, 1, AUDIT_HEADERS.length).setValues([AUDIT_HEADERS]);
  sheet.setFrozenRows(1);
  protectAuditSheet(sheet);
  return sheet;
}

function protectAuditSheet(sheet) {
  try {
    var protection = sheet.protect().setDescription('Audit log — written by the CRM only');
    protection.removeEditors(protection.getEditors());
    if (protection.canDomainEdit()) protection.setDomainEdit(false);
  } catch (e) {
    console.warn('Could not protect AuditLog sheet: ' + e.message);
  }
}

function auditValue(v) {
  if (Object.prototype.toString.call(v) === '[object Date]') return v.toISOString();
  return v === undefined || v === null ? '' : v;
}

// Returns { Field: { from, to } } for every field in `after` whose value
// differs from `before`. Pass before = null for a create, after = null for
// a delete (the whole record is logged either way).
function auditDiff(before, after) {
  var out = {};
  var keys = {};
  Object.keys(before || {}).forEach(function (k) { keys[k] = true; });
  Object.keys(after || {}).forEach(function (k) { keys[k] = true; });

  Object.keys(keys).forEach(function (k) {
    if (AUDIT_SKIP_FIELDS.indexOf(k) !== -1) return;
    var from = before ? auditValue(before[k]) : '';
    var to = after ? auditValue(after[k]) : '';
    if (before && after && after[k] === undefined) return; // field not part of this change
    if (String(from) !== String(to)) out[k] = { from: from, to: to };
  });
  return out;
}

// Never throws: a failed audit write is logged to the Apps Script console
// rather than failing a save the user already made.
//
// changes: either { Field: { from, to } } (from auditDiff) or an array of
// { field, from, to } (human-readable lines for the sale history panel).
// summary: optional one-line description shown in the app.
function audit(session, action, entity, entityId, changes, summary) {
  try {
    var hasChanges = Array.isArray(changes) ? changes.length > 0 : (changes && Object.keys(changes).length > 0);
    appendObject(getAuditSheet(), {
      ID: newId(),
      Timestamp: nowIso(),
      UserEmail: session ? session.email : '',
      UserName: session ? session.name : '',
      Role: session ? session.role : '',
      Action: action,
      Entity: entity,
      EntityID: entityId || '',
      Changes: hasChanges ? JSON.stringify(changes) : '',
      Summary: summary ? String(summary).slice(0, 500) : ''
    });
  } catch (e) {
    console.error('Audit write failed (' + action + ' ' + entity + ' ' + entityId + '): ' + e.message);
  }
}

// Batch version of audit() for bulk operations (one sheet write).
// entries: [{ action, entity, entityId, changes, summary }]
function auditMany(session, entries) {
  if (!entries.length) return;
  try {
    var sheet = getAuditSheet();
    var headers = sheetHeaders(sheet);
    var now = nowIso();
    var values = entries.map(function (e) {
      var row = {
        ID: newId(), Timestamp: now,
        UserEmail: session.email, UserName: session.name, Role: session.role,
        Action: e.action, Entity: e.entity, EntityID: e.entityId || '',
        Changes: e.changes && (Array.isArray(e.changes) ? e.changes.length : Object.keys(e.changes).length) ? JSON.stringify(e.changes) : '',
        Summary: e.summary ? String(e.summary).slice(0, 500) : ''
      };
      return headers.map(function (h) { return safeCellValue(row[h] !== undefined ? row[h] : ''); });
    });
    sheet.getRange(sheet.getLastRow() + 1, 1, values.length, headers.length).setValues(values);
  } catch (err) {
    console.error('Bulk audit write failed: ' + err.message);
  }
}

// Normalizes stored Changes JSON (either shape) to [{ field, from, to }].
function auditChangesForClient(raw) {
  if (!raw) return [];
  var parsed;
  try { parsed = JSON.parse(raw); } catch (e) { return []; }
  if (Array.isArray(parsed)) {
    return parsed.map(function (c) { return { field: String(c.field), from: String(c.from === undefined ? '' : c.from), to: String(c.to === undefined ? '' : c.to) }; });
  }
  return Object.keys(parsed || {}).filter(function (k) {
    return ['Products', 'BillScreenshotUrl', 'PaymentScreenshotUrl', 'ContactKey', 'CreatedAt', 'UpdatedAt'].indexOf(k) === -1;
  }).map(function (k) {
    var v = parsed[k] || {};
    return { field: k, from: String(v.from === undefined || v.from === '' ? '—' : v.from), to: String(v.to === undefined || v.to === '' ? '—' : v.to) };
  });
}

// Actions the sale history panel knows how to label.
var CLIENT_AUDIT_ACTIONS = ['create', 'update', 'reassign', 'reopen', 'status_change', 'complete', 'cancel', 'callback', 'delete'];

function auditRowForClient(row, i) {
  var action = String(row.Action || 'update');
  return {
    ID: String(row.ID || ('audit_row_' + i)),
    SaleID: String(row.EntityID || ''),
    RecordID: String(row.EntityID || ''),
    RecordType: String(row.Entity || ''),
    Date: isoString(row.Timestamp),
    ByEmail: String(row.UserEmail || ''),
    ByName: String(row.UserName || ''),
    ByRole: String(row.Role || ''),
    Action: CLIENT_AUDIT_ACTIONS.indexOf(action) !== -1 ? action : 'update',
    Summary: String(row.Summary || defaultAuditSummary(row)),
    Changes: auditChangesForClient(row.Changes)
  };
}

function defaultAuditSummary(row) {
  var labels = {
    create: 'Created', update: 'Updated', delete: 'Deleted', reassign: 'Reassigned',
    sync_from_lead: 'Updated from lead', create_from_lead: 'Created from lead'
  };
  return (labels[row.Action] || String(row.Action || 'Changed')) + ' ' + String(row.Entity || 'record');
}

// History for a set of record IDs, newest first.
function auditHistoryFor(entityIds, limit) {
  var wanted = {};
  entityIds.forEach(function (id) { wanted[String(id)] = true; });
  var out = [];
  sheetToObjects(getAuditSheet()).forEach(function (row, i) {
    if (wanted[String(row.EntityID)]) out.push(auditRowForClient(row, i));
  });
  out.sort(function (a, b) { return new Date(b.Date) - new Date(a.Date); });
  return limit ? out.slice(0, limit) : out;
}

// ===== Audit log viewer (Settings → Audit log) =====
// Admins and senior managers only: summaries name patients and amounts.
// Filters: q (text in summary, entity id or user), user (email), action,
// from / to ('yyyy-MM-dd', India time). Newest first, in pages.
function svc_listAuditLog(session, data) {
  requireRole(session, SENIOR_ROLES);
  data = data || {};
  var q = cleanText(data.q, 100).toLowerCase();
  var userEmail = cleanEmail(data.user);
  var action = cleanText(data.action, 40);
  var from = optionalDateKey(data.from, 'From');
  var to = optionalDateKey(data.to, 'To');
  var limit = Math.min(200, Math.max(1, Number(data.limit) || 50));
  var offset = Math.max(0, Number(data.offset) || 0);
  var rows = sheetToObjects(getAuditSheet()).map(function (r, i) { r._i = i; return r; }).filter(function (r) {
    if (userEmail && lowerEmail(r.UserEmail) !== userEmail) return false;
    if (action && String(r.Action) !== action) return false;
    var day = r.Timestamp ? Utilities.formatDate(new Date(r.Timestamp), APP_TIMEZONE, 'yyyy-MM-dd') : '';
    if (from && day < from) return false;
    if (to && day > to) return false;
    if (q && (String(r.Summary) + ' ' + r.EntityID + ' ' + r.UserName + ' ' + r.UserEmail + ' ' + r.Entity).toLowerCase().indexOf(q) === -1) return false;
    return true;
  });
  rows.sort(function (a, b) { return (new Date(b.Timestamp) - new Date(a.Timestamp)) || (b._i - a._i); });
  var actions = {};
  sheetToObjects(getAuditSheet()).forEach(function (r) { if (r.Action) actions[String(r.Action)] = true; });
  return {
    total: rows.length,
    offset: offset,
    actions: Object.keys(actions).sort(),
    rows: rows.slice(offset, offset + limit).map(function (r) {
      return {
        id: String(r.ID || ''), date: isoString(r.Timestamp), userName: String(r.UserName || ''), userEmail: String(r.UserEmail || ''),
        role: String(r.Role || ''), action: String(r.Action || ''), entity: String(r.Entity || ''), entityId: String(r.EntityID || ''),
        summary: String(r.Summary || defaultAuditSummary(r)), changes: auditChangesForClient(r.Changes)
      };
    })
  };
}


// ---- Auth.gs ----
// Auth.gs — login/logout and session handling
//
// Sessions are opaque tokens kept server-side in CacheService (never in the
// sheet). Every request re-checks the user's row in the Users sheet, so
// deactivating someone, changing their role, or resetting their password
// takes effect on their very next request — not when the session expires.
//
// Passwords are hashed with PBKDF2-HMAC-SHA256 (many rounds, per-user salt).
// Accounts created before this change have a single-round SHA-256 hash; those
// still work and are upgraded to PBKDF2 automatically the next time that
// person logs in successfully.

var SESSION_TTL_SECONDS = 2 * 60 * 60; // idle timeout: 2 hours without any request ends the session
var SESSION_MAX_AGE_MS = 12 * 60 * 60 * 1000; // absolute limit, however active
var SESSION_CACHE_PREFIX = 'sess_';

var PBKDF2_ITERATIONS = 1500; // ~0.75s per login on Apps Script (5000 measured at ~2.5s); each login costs this many HMACs
var HASH_PREFIX = 'pbkdf2$';  // stored as pbkdf2$<iterations>$<hex>

var LOGIN_MAX_FAILURES = 5;
var LOGIN_LOCKOUT_SECONDS = 15 * 60;
var LOGIN_FAIL_PREFIX = 'loginfail_';

// Session is missing/expired/revoked — the frontend logs the user out.
function AuthError(message) {
  this.name = 'AuthError';
  this.message = message;
}
AuthError.prototype = Object.create(Error.prototype);

// Logged in, but not allowed to do this — the frontend just shows the message.
function ForbiddenError(message) {
  this.name = 'ForbiddenError';
  this.message = message;
}
ForbiddenError.prototype = Object.create(Error.prototype);

function generateSalt() {
  return Utilities.getUuid();
}

function bytesToHex(bytes) {
  return bytes.map(function (b) { return ('0' + (b & 0xFF).toString(16)).slice(-2); }).join('');
}

function stringToBytes(str) {
  return Utilities.newBlob(String(str)).getBytes();
}

// PBKDF2-HMAC-SHA256, one 32-byte output block.
function pbkdf2Hex(password, salt, iterations) {
  var key = stringToBytes(password);
  var u = Utilities.computeHmacSha256Signature(stringToBytes(salt).concat([0, 0, 0, 1]), key);
  var out = u.slice();
  for (var i = 1; i < iterations; i++) {
    u = Utilities.computeHmacSha256Signature(u, key);
    for (var j = 0; j < out.length; j++) out[j] ^= u[j];
  }
  return bytesToHex(out);
}

function hashPassword(password, salt) {
  return HASH_PREFIX + PBKDF2_ITERATIONS + '$' + pbkdf2Hex(password, salt, PBKDF2_ITERATIONS);
}

// The original scheme: single SHA-256 over "password:salt". Only used to
// verify (and then upgrade) accounts created before PBKDF2.
function legacyHashPassword(password, salt) {
  return bytesToHex(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, password + ':' + salt));
}

function isLegacyHash(stored) {
  return String(stored).indexOf(HASH_PREFIX) !== 0;
}

// Compares every character regardless of where the first mismatch is, so
// response time doesn't leak how much of a hash was right.
function constantTimeEquals(a, b) {
  a = String(a); b = String(b);
  var diff = a.length ^ b.length;
  var len = Math.max(a.length, b.length);
  for (var i = 0; i < len; i++) {
    diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  }
  return diff === 0;
}

function verifyPassword(password, user) {
  var stored = String(user.PasswordHash || '');
  if (isLegacyHash(stored)) {
    return constantTimeEquals(legacyHashPassword(password, user.Salt), stored);
  }
  var parts = stored.split('$'); // ['pbkdf2', iterations, hex]
  var iterations = Number(parts[1]) || PBKDF2_ITERATIONS;
  return constantTimeEquals(pbkdf2Hex(password, user.Salt, iterations), parts[2]);
}

function isActive(value) {
  return asBool(value);
}

function loginFailureCount(email) {
  return Number(CacheService.getScriptCache().get(LOGIN_FAIL_PREFIX + email)) || 0;
}

function recordLoginFailure(email) {
  var count = loginFailureCount(email) + 1;
  CacheService.getScriptCache().put(LOGIN_FAIL_PREFIX + email, String(count), LOGIN_LOCKOUT_SECONDS);
  if (count === LOGIN_MAX_FAILURES) {
    audit({ email: email, name: '', role: '' }, 'login_locked', 'User', email,
      { failedAttempts: { from: '', to: count } });
  }
}

function login(email, password) {
  email = cleanEmail(email);
  password = String(password || '').slice(0, 128);
  if (!email || !password) return { error: true, message: 'Email and password are required.' };

  if (loginFailureCount(email) >= LOGIN_MAX_FAILURES) {
    return { error: true, message: 'Too many failed attempts. Try again in 15 minutes, or ask an admin to reset your password.' };
  }

  var users = sheetToObjects(getSheetByName('Users'));
  var user = users.find(function (u) { return String(u.Email).toLowerCase() === email; });

  // Hash even when the email doesn't exist, so response time doesn't reveal
  // which emails have accounts.
  if (!user) pbkdf2Hex(password, 'no-such-user', PBKDF2_ITERATIONS);

  if (!user || !verifyPassword(password, user)) {
    recordLoginFailure(email);
    return { error: true, message: 'Invalid email or password.' };
  }
  if (!isActive(user.Active)) return { error: true, message: 'This account has been deactivated. Contact your admin.' };

  CacheService.getScriptCache().remove(LOGIN_FAIL_PREFIX + email);

  // Upgrade an old single-round hash now that we know the password. The salt
  // stays the same, so this doesn't invalidate the person's other sessions.
  if (isLegacyHash(user.PasswordHash)) {
    withScriptLock(function () {
      updateObjectById(getSheetByName('Users'), user.ID, { PasswordHash: hashPassword(password, user.Salt) });
    });
  }

  var session = startSession(user);
  audit(session, 'login', 'User', user.ID, null);
  return { error: false, token: session.token, user: publicSession(session) };
}

// Issues a fresh opaque token for this user. Tokens are two UUIDs (244 bits
// of randomness) and live only in CacheService, never in the sheet.
function startSession(user) {
  var token = Utilities.getUuid() + Utilities.getUuid().replace(/-/g, '');
  var session = {
    token: token,
    id: user.ID, email: user.Email, name: user.Name, role: user.Role, salt: user.Salt,
    mustChangePassword: asBool(user.MustChangePassword),
    startedAt: Date.now()
  };
  CacheService.getScriptCache().put(SESSION_CACHE_PREFIX + token, JSON.stringify(session), SESSION_TTL_SECONDS);
  return session;
}

// What the browser gets to see (no salt, no token).
function publicSession(session) {
  return {
    id: session.id, email: session.email, name: session.name, role: session.role,
    mustChangePassword: !!session.mustChangePassword
  };
}

// ===== Password policy =====
var PASSWORD_MIN_LENGTH = 10;

function validatePasswordStrength(password, email) {
  var pw = String(password || '');
  if (pw.length < PASSWORD_MIN_LENGTH) throw new Error('Password must be at least ' + PASSWORD_MIN_LENGTH + ' characters.');
  if (pw.length > 128) throw new Error('Password must be 128 characters or fewer.');
  if (!/[A-Za-z]/.test(pw) || !/[0-9]/.test(pw)) throw new Error('Password must contain both letters and numbers.');
  var local = String(email || '').split('@')[0].toLowerCase();
  if (local.length >= 4 && pw.toLowerCase().indexOf(local) !== -1) throw new Error('Password must not contain your email name.');
  if (/^(password|medunited|welcome|qwerty|admin)/i.test(pw)) throw new Error('That password is too easy to guess.');
}

// Self-service password change. Verifies the current password, stores a new
// hash with a new salt (which ends every other session for this user), and
// hands back a fresh token so the person who changed it stays logged in.
function svc_changePassword(session, currentPassword, newPassword) {
  var sheet = getSheetByName('Users');
  var user = sheetToObjects(sheet).find(function (u) { return String(u.ID) === String(session.id); });
  if (!user) throw new AuthError('Your session has ended. Please log in again.');
  if (!verifyPassword(String(currentPassword || ''), user)) {
    recordLoginFailure(String(user.Email).toLowerCase());
    throw new Error('Current password is incorrect.');
  }
  if (String(currentPassword) === String(newPassword)) throw new Error('New password must be different from the current one.');
  validatePasswordStrength(newPassword, user.Email);

  var salt = generateSalt();
  ensureHeaders(sheet, ['MustChangePassword']);
  var updated = updateObjectById(sheet, user.ID, {
    Salt: salt, PasswordHash: hashPassword(String(newPassword), salt), MustChangePassword: false
  });
  CacheService.getScriptCache().remove(SESSION_CACHE_PREFIX + session.token);
  audit(session, 'change_password', 'User', user.ID, { Password: { from: '', to: '(changed)' } });
  var fresh = startSession(updated);
  return { token: fresh.token, user: publicSession(fresh) };
}

function logout(token) {
  if (token) CacheService.getScriptCache().remove(SESSION_CACHE_PREFIX + token);
  return { error: false };
}

function getSession(token) {
  if (!token) return null;
  var raw = CacheService.getScriptCache().get(SESSION_CACHE_PREFIX + token);
  return raw ? JSON.parse(raw) : null;
}

function requireSession(token) {
  var session = getSession(token);
  if (!session) throw new AuthError('Your session has expired. Please log in again.');

  // Re-check the live user row: deactivated, deleted, or password reset
  // (new salt) all end the session immediately.
  var user = sheetToObjects(getSheetByName('Users')).find(function (u) { return String(u.ID) === String(session.id); });
  if (!user || !isActive(user.Active) || String(user.Salt) !== String(session.salt)) {
    CacheService.getScriptCache().remove(SESSION_CACHE_PREFIX + token);
    throw new AuthError('Your session has ended. Please log in again.');
  }

  // Hard cap: even an active session must log in again after 12 hours.
  if (session.startedAt && Date.now() - session.startedAt > SESSION_MAX_AGE_MS) {
    CacheService.getScriptCache().remove(SESSION_CACHE_PREFIX + token);
    throw new AuthError('Your session has expired. Please log in again.');
  }

  // Role/name changes apply right away.
  session.token = token;
  session.role = user.Role;
  session.name = user.Name;
  session.email = user.Email;
  session.mustChangePassword = asBool(user.MustChangePassword);

  // Sliding expiration: any activity extends the idle timeout.
  CacheService.getScriptCache().put(SESSION_CACHE_PREFIX + token, JSON.stringify(session), SESSION_TTL_SECONDS);
  return session;
}

// Role groups. A senior manager can do everything an admin can except
// manage admin accounts and hard deletes (records and user accounts).
var TEAM_ROLES = ['admin', 'senior_manager', 'manager']; // see the whole team, reassign, incentives
var SENIOR_ROLES = ['admin', 'senior_manager'];          // approvals, users, lists, owner decisions
var ADMIN_ROLES = ['admin'];                             // admin accounts, hard deletes

function requireRole(session, allowedRoles) {
  if (allowedRoles.indexOf(session.role) === -1) {
    throw new ForbiddenError('You do not have permission to perform this action.');
  }
}


// ---- BulkReassign.gs ----
// BulkReassign.gs — moving many patients at once (managers and above).
//
//   bulkReassign          records ticked on a module page → one agent
//   importReassignments   an exported sheet with the Assigned Agent Email
//                         column edited → each row's patient to that agent
//   handoverAgent         everything one agent handles → another agent,
//                         without deactivating anyone
//
// Every tool works on patients, like a single reassign (Patients.gs): the
// patient — by default everyone on their phone number (scope 'household'),
// or only that person (scope 'person') — moves with all their open records in
// every module and their active reminders. Completed and cancelled records
// keep their agent, so incentives stay with whoever closed the sale.
//
// Each tool has a dry run that says what would move and saves nothing. The
// real run checks everything again first.

var BULK_MAX_ROWS = 500;

// One line of the plan, as the browser shows it.
function bulkResult(rowNo, rec, errors, warnings, fromName, toName, openRecords) {
  return {
    row: rowNo, id: rec ? String(rec.row.ID) : '', customerName: rec ? String(rec.row.CustomerName) : '',
    ok: errors.length === 0, errors: errors, warnings: warnings,
    fromAgent: fromName || '', toAgent: toName || '', openRecords: openRecords || 0
  };
}

// Works out who goes where. requests: [{ row, type, id, agentEmail }].
// Returns { results, groups } — groups are the moves that would be made.
function planBulkReassign(world, requests, scope) {
  var groups = {};
  var order = [];
  var results = [];

  requests.forEach(function (q) {
    var errors = [];
    var warnings = [];
    var rec = null;
    var target = null;
    var patient = null;
    if (!MODULES.hasOwnProperty(q.type)) errors.push('Unknown module.');
    else {
      rec = world.records.filter(function (x) { return x.type === q.type && String(x.row.ID) === String(q.id); })[0] || null;
      if (!rec) errors.push('No ' + SALE_TYPES[q.type] + ' record with ID "' + cleanText(q.id, 60) + '".');
    }
    if (!cleanText(q.agentEmail)) errors.push('Agent email is empty.');
    else {
      try { target = requireOwnerCandidate(world, q.agentEmail); } catch (e) { errors.push('"' + cleanText(q.agentEmail, 80) + '" is not an active agent or manager.'); }
    }
    if (rec) {
      ensureHousehold(world, recordContactKey(rec.row));
      patient = recordPatient(world, rec.row);
      if (!patient) errors.push('This record has no valid phone number, so its patient can\'t be found.');
    }
    if (errors.length) { results.push({ q: q, rec: rec, errors: errors, warnings: warnings }); return; }

    var key = scope === 'person' ? 'p:' + patient.ID : 'h:' + patient.ContactKey;
    var g = groups[key];
    if (!g) {
      g = groups[key] = {
        key: key, target: target, rows: [],
        patients: scope === 'person' ? [patient] : householdOf(world, patient.ContactKey).slice()
      };
      order.push(key);
    } else if (lowerEmail(g.target.email) !== lowerEmail(target.email)) {
      g.conflict = true;
    }
    if (rec.row.Status !== 'Pending') warnings.push('This record is ' + rec.row.Status + ' and keeps its agent; the patient and their open records move.');
    var r = { q: q, rec: rec, errors: errors, warnings: warnings, group: g };
    g.rows.push(r);
    results.push(r);
  });

  // Rows that give the same patient (or household) different agents.
  order.forEach(function (key) {
    var g = groups[key];
    if (!g.conflict) return;
    var nums = g.rows.map(function (r) { return r.q.row; }).join(', ');
    g.rows.forEach(function (r) {
      r.errors.push('Rows ' + nums + ' give this ' + (scope === 'person' ? 'patient' : 'household') + ' different agents. Use one agent for all of them.');
    });
  });

  // What each move would do.
  order.forEach(function (key) {
    var g = groups[key];
    var ids = {};
    g.patients.forEach(function (p) { ids[String(p.ID)] = true; });
    var open = 0;
    var already = g.patients.every(function (p) { return p.OwnerStatus === PATIENT_OWNED && lowerEmail(p.OwnerEmail) === lowerEmail(g.target.email); });
    householdRecords(world, g.patients[0].ContactKey).forEach(function (x) {
      var p = recordPatient(world, x.row);
      if (p && ids[String(p.ID)] && x.row.Status === 'Pending' && lowerEmail(x.row.AgentEmail) !== lowerEmail(g.target.email)) open++;
    });
    g.openRecords = open;
    g.noChange = already && open === 0;
    if (g.noChange) g.rows.forEach(function (r) { if (!r.errors.length) r.warnings.push('Already with ' + g.target.name + ' — nothing to move.'); });
  });

  return {
    groups: order.map(function (k) { return groups[k]; }),
    results: results.map(function (r) {
      var from = r.rec ? String(r.rec.row.AgentName) : '';
      return bulkResult(r.q.row, r.rec, r.errors, r.warnings, from, r.group ? r.group.target.name : '', r.group ? r.group.openRecords : 0);
    })
  };
}

// Carries out the moves of a plan that have no errors. Returns totals.
function applyBulkPlan(session, world, plan, why) {
  var totals = { patients: 0, records: 0, reminders: 0 };
  plan.groups.forEach(function (g) {
    if (g.conflict || g.noChange) return;
    if (g.rows.some(function (r) { return r.errors.length; })) return;
    var res = movePatients(session, world, g.patients, g.target, why);
    totals.patients += g.patients.length;
    totals.records += res.records.length;
    totals.reminders += res.reminders;
  });
  savePatientChanges(world);
  return totals;
}

function bulkSummary(plan, dryRun, totals) {
  var ok = plan.results.filter(function (r) { return r.ok; }).length;
  return {
    dryRun: dryRun,
    total: plan.results.length,
    valid: ok,
    invalid: plan.results.length - ok,
    results: plan.results,
    moved: totals || null,
    toMove: plan.groups.filter(function (g) { return !g.conflict && !g.noChange; }).reduce(function (t, g) { return t + g.openRecords; }, 0)
  };
}

// Records ticked on a module page → one agent.
function svc_bulkReassign(session, data) {
  requireRole(session, TEAM_ROLES);
  data = data || {};
  getModule(data.type);
  var ids = Array.isArray(data.ids) ? data.ids : [];
  if (!ids.length) throw new Error('Select at least one record.');
  if (ids.length > BULK_MAX_ROWS) throw new Error('You can reassign at most ' + BULK_MAX_ROWS + ' records at a time.');
  var scope = data.scope === 'person' ? 'person' : 'household';
  var world = loadPatientWorld();
  var plan = planBulkReassign(world, ids.map(function (id, i) {
    return { row: i + 1, type: data.type, id: id, agentEmail: data.agentEmail };
  }), scope);
  var dryRun = data.dryRun !== false;
  if (dryRun) return bulkSummary(plan, true);
  var why = cleanText(data.reason, 300) || 'Bulk reassign';
  var totals = applyBulkPlan(session, world, plan, why);
  audit(session, 'bulk_reassign', saleEntity(data.type), '', { Patients: { from: '', to: totals.patients }, Records: { from: '', to: totals.records } },
    'Bulk reassigned ' + totals.patients + ' patient(s) (' + totals.records + ' open records) to ' + (plan.groups[0] ? plan.groups[0].target.name : '—') + '. ' + why);
  return bulkSummary(plan, false, totals);
}

// An exported sheet with the Assigned Agent Email column edited.
// rows: [{ _row, id, agentEmail }] for one module.
function svc_importReassignments(session, data) {
  requireRole(session, TEAM_ROLES);
  data = data || {};
  getModule(data.type);
  var rows = Array.isArray(data.rows) ? data.rows : [];
  if (!rows.length) throw new Error('The file has no rows.');
  if (rows.length > BULK_MAX_ROWS) throw new Error('You can import at most ' + BULK_MAX_ROWS + ' rows at a time. Split the file and import it in parts.');
  var scope = data.scope === 'person' ? 'person' : 'household';
  var world = loadPatientWorld();

  // Rows whose agent didn't change are left out of the plan (most of an export).
  var requests = [];
  var unchanged = [];
  rows.forEach(function (raw, i) {
    var r = raw && typeof raw === 'object' ? raw : {};
    var rowNo = Number(r._row) || (i + 2);
    var id = cleanText(r.id, 60);
    var email = cleanEmail(r.agentEmail);
    var rec = world.records.filter(function (x) { return x.type === data.type && String(x.row.ID) === id; })[0];
    if (rec && email && lowerEmail(rec.row.AgentEmail) === email) {
      var p = recordPatient(world, rec.row);
      if (!p || lowerEmail(p.OwnerEmail) === email) { unchanged.push(rowNo); return; }
    }
    requests.push({ row: rowNo, type: data.type, id: id, agentEmail: email });
  });
  var plan = planBulkReassign(world, requests, scope);
  var summary;
  var dryRun = data.dryRun !== false;
  var file = cleanText(data.fileName, 80);
  if (dryRun) summary = bulkSummary(plan, true);
  else {
    var why = 'Reassigned from file' + (file ? ' ' + file : '');
    var totals = applyBulkPlan(session, world, plan, why);
    audit(session, 'import_reassign', saleEntity(data.type), '', { Patients: { from: '', to: totals.patients }, Records: { from: '', to: totals.records } },
      why + ': ' + totals.patients + ' patient(s), ' + totals.records + ' open record(s) moved; ' + countSkipped(plan) + ' row(s) skipped.');
    summary = bulkSummary(plan, false, totals);
  }
  summary.unchanged = unchanged.length;
  return summary;
}

function countSkipped(plan) { return plan.results.filter(function (r) { return !r.ok; }).length; }

// Everything one agent handles → another agent (no deactivation).
function svc_handoverAgent(session, data) {
  requireRole(session, TEAM_ROLES);
  data = data || {};
  var fromEmail = cleanEmail(data.fromEmail);
  var user = sheetToObjects(getUsersSheet()).filter(function (u) { return lowerEmail(u.Email) === fromEmail; })[0];
  if (!user) throw new Error('Choose whose patients to hand over.');
  var world = loadPatientWorld();
  var successor = requireOwnerCandidate(world, data.toEmail);
  if (lowerEmail(successor.email) === fromEmail) throw new Error('Choose someone else to take over.');
  var work = openWorkOf(world, user.Email);
  var preview = { from: user.Name, to: successor.name, patients: work.patients.length, records: work.records.length, reminders: work.reminders.length };
  if (data.dryRun !== false) return { dryRun: true, preview: preview };
  var why = cleanText(data.reason, 300);
  if (why.length < 3) throw new Error('Give a reason (at least 3 characters), e.g. "On leave until 30 Nov".');
  if (!hasOpenWork(work)) throw new Error(user.Name + ' has nothing to hand over.');
  var moved = handOverWork(session, world, user, successor, why);
  audit(session, 'handover', 'User', user.ID, { Successor: { from: '', to: successor.email } },
    'Handed ' + moved.patients + ' patient(s), ' + moved.records + ' open record(s) and ' + moved.reminders + ' reminder(s) from ' +
    user.Name + ' to ' + successor.name + '. Reason: ' + why);
  return { dryRun: false, preview: preview, moved: moved };
}


// ---- Code.gs ----
// Code.gs — HTTP entry point / action router.
//
// Every request is a POST (form-encoded, so browsers send it without a CORS
// preflight) carrying:
//   action   which handler to run
//   token    the session token (all actions except login)
//   payload  a JSON object with that action's arguments
//
// Authorization happens inside the svc_* functions; this router only checks
// that a session exists, applies rate limits, refuses everything except a
// password change while a password change is required, and serializes every
// write behind the script lock so two people saving at once can't overwrite
// each other's rows.

var API_VERSION = '2.0.0';
var MAX_REQUEST_BYTES = 12 * 1024 * 1024; // two 5MB screenshots as base64 + form data

// GET is not used by the app. Rejecting it keeps passwords and tokens out of
// URLs (and therefore out of browser history and server logs).
function doGet() {
  return jsonResponse({ error: true, message: 'This endpoint only accepts POST requests from the CRM app.' });
}

function doPost(e) { return handleRequest(e); }

// Actions that change data. Each runs entirely inside the script lock.
var WRITE_ACTIONS = [
  'changePassword',
  'createSale', 'importSales', 'updateSale', 'deleteSale', 'reopenSale', 'reassignSale', 'logSaleActivity',
  'saveDashboardLayout', 'resetDashboardLayout', 'saveRoleDefaultLayout',
  'saveTargets', 'copyTargets', 'setTargetMeasure', 'updateHomekareCatalogue',
  'reassignPatient', 'bulkReassign', 'importReassignments', 'handoverAgent', 'migratePatients', 'resolvePatientConflict', 'decideMedpassDiscount', 'updateMedpassSettings',
  'createUser', 'updateUser', 'deleteUser', 'updateIncentives', 'requestDeactivation', 'decideUserRequest',
  'markContacted', 'reassignReminder',
  'updateLists', 'updateMonthlyTarget'
];

// Allowed while the user still has to replace an admin-set password.
var PASSWORD_CHANGE_ALLOWED = ['me', 'logout', 'changePassword'];

function handleRequest(e) {
  var params = (e && e.parameter) || {};
  var action = String(params.action || '');
  var result;

  try {
    var size = e && e.postData && e.postData.length;
    if (size && size > MAX_REQUEST_BYTES) throw new Error('Request is too large. Attach smaller screenshots (max 5MB each).');

    var payload = {};
    if (params.payload) {
      try { payload = JSON.parse(params.payload); } catch (err) { throw new Error('Malformed request.'); }
      if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('Malformed request.');
    }

    if (WRITE_ACTIONS.indexOf(action) !== -1) {
      result = withScriptLock(function () { return dispatch(action, params.token, payload); });
      if (result && !result.error) bumpDataVersion(); // invalidate cached dashboards
    } else {
      // Read-only: each tab is read once for the whole request (Utils.gs).
      result = withReadCache(function () { return dispatch(action, params.token, payload); });
    }
  } catch (err) {
    result = errorResult(err, action);
  }

  return jsonResponse(result);
}

// Messages we throw ourselves are written for the user. Anything else
// (an Apps Script "Exception: …", a bug) is logged and replaced with a
// generic message, so internals never reach the browser.
function errorResult(err, action) {
  var name = err && err.name;
  var msg = String((err && err.message) || err || '');
  var internal = !msg || /^Exception:|is not defined|Cannot read prop|undefined|null is not|TypeError|ReferenceError|Service invoked too many times|Sheet not found/i.test(msg);
  if (internal) {
    console.error('Action ' + action + ' failed: ' + msg + (err && err.stack ? '\n' + err.stack : ''));
    msg = 'Something went wrong on the server. Please try again; if it keeps happening, tell your admin.';
  }
  return { error: true, message: msg, authError: name === 'AuthError', forbidden: name === 'ForbiddenError' };
}

function dispatch(action, token, p) {
  if (action === 'login') {
    checkRateLimit('login_' + cleanEmail(p.email));
    return login(p.email, p.password);
  }
  if (action === 'ping') return { error: false, version: API_VERSION };

  var session = requireSession(token);
  checkRateLimit('u_' + session.id);
  if (session.mustChangePassword && PASSWORD_CHANGE_ALLOWED.indexOf(action) === -1) {
    return { error: true, mustChangePassword: true, message: 'Please set a new password before continuing.' };
  }

  switch (action) {
    // ----- Session -----
    case 'logout':
      return logout(token);
    case 'me':
      return { error: false, user: publicSession(session) };
    case 'changePassword':
      return Object.assign({ error: false }, svc_changePassword(session, p.currentPassword, p.newPassword));

    // ----- Module records (Medpass, Pharmacy, …) -----
    case 'getModules':
      return { error: false, modules: svc_getModules(session) };
    case 'listSales':
      return { error: false, sales: svc_listSales(session, p.type) };
    case 'getSale':
      return Object.assign({ error: false }, svc_getSale(session, p.type, p.id));
    case 'createSale':
      return Object.assign({ error: false }, svc_createSale(session, p.type, p.data || {}));
    case 'importSales':
      return Object.assign({ error: false }, svc_importSales(session, p.type, p.rows, { dryRun: p.dryRun === true, agentEmail: p.agentEmail, fileName: p.fileName }));
    case 'updateSale':
      return Object.assign({ error: false }, svc_updateSale(session, p.type, p.id, p.data || {}));
    case 'deleteSale':
      return Object.assign({ error: false }, svc_deleteSale(session, p.type, p.id, p.reason));
    case 'reopenSale':
      return { error: false, sale: svc_reopenSale(session, p.type, p.id, p.reason) };
    case 'reassignSale':
      return Object.assign({ error: false }, svc_reassignSale(session, p.type, p.id, p.agentEmail, p.scope, p.reason));
    case 'reassignPatient':
      return Object.assign({ error: false }, svc_reassignPatient(session, p));
    case 'bulkReassign':
      return Object.assign({ error: false }, svc_bulkReassign(session, p));
    case 'importReassignments':
      return Object.assign({ error: false }, svc_importReassignments(session, p));
    case 'handoverAgent':
      return Object.assign({ error: false }, svc_handoverAgent(session, p));

    // ----- Medpass (price, discounts) -----
    case 'getMedpassSettings':
      return { error: false, settings: svc_getMedpassSettings(session) };
    case 'updateMedpassSettings':
      return { error: false, settings: svc_updateMedpassSettings(session, p.data || {}) };
    case 'listPendingDiscounts':
      return { error: false, discounts: svc_listPendingDiscounts(session) };
    case 'decideMedpassDiscount':
      return { error: false, sale: svc_decideMedpassDiscount(session, p) };

    // ----- Patients (owners, migration, conflicts) -----
    case 'migratePatients':
      return { error: false, migration: svc_migratePatients(session, p.dryRun) };
    case 'listPatientConflicts':
      return { error: false, conflicts: svc_listPatientConflicts(session) };
    case 'resolvePatientConflict':
      return Object.assign({ error: false }, svc_resolvePatientConflict(session, p));
    case 'logSaleActivity':
      return Object.assign({ error: false }, svc_logSaleActivity(session, p.type, p.id, p.data || {}));
    case 'getAuditHistory':
      return { error: false, auditHistory: svc_getAuditHistory(session, p.type, p.id) };
    case 'checkContact':
      return Object.assign({ error: false }, svc_checkContact(session, p.contact, p.exceptId));
    case 'getAttachment':
      return { error: false, attachment: svc_getAttachment(session, p.type, p.id, p.kind) };

    // ----- Targets, incentives, audit log -----
    case 'getTargets':
      return Object.assign({ error: false }, svc_getTargets(session, p.month));
    case 'saveTargets':
      return Object.assign({ error: false }, svc_saveTargets(session, p));
    case 'copyTargets':
      return Object.assign({ error: false }, svc_copyTargets(session, p));
    case 'setTargetMeasure':
      return { error: false, measures: svc_setTargetMeasure(session, p) };
    case 'performance':
      return { error: false, performance: svc_performance(session, p) };
    case 'incentiveReport':
      return { error: false, report: svc_incentiveReport(session, p.month) };
    case 'listAuditLog':
      return Object.assign({ error: false }, svc_listAuditLog(session, p));
    case 'updateHomekareCatalogue':
      return { error: false, services: svc_updateHomekareCatalogue(session, p) };

    // ----- Dashboard -----
    case 'getDashboardLayout':
      return Object.assign({ error: false }, svc_getDashboardLayout(session));
    case 'saveDashboardLayout':
      return Object.assign({ error: false }, svc_saveDashboardLayout(session, p.layout));
    case 'resetDashboardLayout':
      return Object.assign({ error: false }, svc_resetDashboardLayout(session));
    case 'saveRoleDefaultLayout':
      return { error: false, layout: svc_saveRoleDefaultLayout(session, p.group, p.layout) };
    case 'dashboardSummary':
      return { error: false, summary: svc_dashboardSummary(session) };

    // ----- Users & incentives -----
    case 'listUsers':
      return { error: false, users: svc_listUsers(session) };
    case 'createUser':
      return { error: false, user: svc_createUser(session, p.data || {}) };
    case 'updateUser':
      return { error: false, user: svc_updateUser(session, p.id, p.data || {}) };
    case 'deleteUser':
      return Object.assign({ error: false }, svc_deleteUser(session, p.id, p.reason));
    case 'requestDeactivation':
      return { error: false, request: svc_requestDeactivation(session, p) };
    case 'listUserRequests':
      return { error: false, requests: svc_listUserRequests(session, p.includeDecided === true) };
    case 'decideUserRequest':
      return Object.assign({ error: false }, svc_decideUserRequest(session, p));
    case 'updateIncentives':
      return { error: false, user: svc_updateIncentives(session, p.id, p.data || {}) };

    // ----- Refill reminders -----
    case 'listReminders':
      return { error: false, reminders: svc_listReminders(session, p.includeResolved === true) };
    case 'markContacted':
      return { error: false, reminder: svc_markContacted(session, p.id, p.outcome) };
    case 'reassignReminder':
      return { error: false, reminder: svc_reassignReminder(session, p.id, p.agentEmail) };

    // ----- Settings -----
    case 'getLists':
      return { error: false, lists: svc_getLists(session) };
    case 'updateLists':
      return { error: false, lists: svc_updateLists(session, p.data || {}) };
    case 'getMonthlyTarget':
      return { error: false, target: svc_getMonthlyTarget(session) };
    case 'updateMonthlyTarget':
      return { error: false, target: svc_updateMonthlyTarget(session, p.amount) };

    default:
      return { error: true, message: 'Unknown action.' };
  }
}


// ---- DashboardLayouts.gs ----
// DashboardLayouts.gs — which widgets each person's dashboard shows, where,
// and how big.
//
// A layout is a list of { id, span }: a widget from the catalogue below and
// its width on a 12-column grid (4, 6, 8 or 12). Each person can save their
// own layout (UserLayouts tab); without one they get their role's default.
// Admins and senior managers can change the role defaults (Settings tab:
// dashboardDefault_agent, dashboardDefault_team).
//
// A layout only decides what is drawn. The numbers in every widget come from
// dashboardSummary, which the server always filters by role — moving or
// adding a widget never changes what someone can see. Team-only widgets
// (discount approvals, team performance) can't be added by agents at all.

var LAYOUT_SPANS = [4, 6, 8, 12];
var MAX_WIDGETS = 20;
var USER_LAYOUT_HEADERS = ['Email', 'Layout', 'UpdatedAt'];

function getUserLayoutsSheet() { return getOrCreateSheet('UserLayouts', USER_LAYOUT_HEADERS); }

// Built when called (not at load), so it can use the role lists from Auth.gs.
function dashboardWidgets() {
  var all = ['admin', 'senior_manager', 'manager', 'agent'];
  return {
    target: { title: 'This month vs target', roles: all },
    comparison: { title: 'This month vs last month', roles: all },
    followups: { title: 'Follow-ups due', roles: all },
    reminders: { title: 'Reminders due', roles: all },
    temperature: { title: 'Open leads by temperature', roles: all },
    modules: { title: 'Completed sales by module', roles: all },
    pipeline: { title: 'Pipeline', roles: all },
    activity: { title: 'Recent activity', roles: all },
    discounts: { title: 'Discounts waiting for approval', roles: TEAM_ROLES },
    team: { title: 'Team performance', roles: TEAM_ROLES }
  };
}

// 'agent' for agents; 'team' for everyone who sees the whole team.
function layoutGroup(role) { return role === 'agent' ? 'agent' : 'team'; }

var BUILT_IN_LAYOUTS = {
  agent: [{ id: 'target', span: 4 }, { id: 'comparison', span: 4 }, { id: 'temperature', span: 4 }, { id: 'followups', span: 8 }, { id: 'reminders', span: 4 },
    { id: 'modules', span: 4 }],
  team: [{ id: 'target', span: 4 }, { id: 'comparison', span: 4 }, { id: 'discounts', span: 4 }, { id: 'team', span: 8 }, { id: 'temperature', span: 4 },
    { id: 'followups', span: 8 }, { id: 'reminders', span: 4 }, { id: 'modules', span: 4 }]
};

// Checks a layout for a role; drops nothing silently on save (throws), but
// `lenient` drops widgets the role can't have (a stored layout after a role change).
function cleanLayout(raw, role, lenient) {
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw || '[]'); } catch (e) { if (lenient) return null; throw new Error('The layout is not valid.'); }
  }
  if (!Array.isArray(raw)) { if (lenient) return null; throw new Error('The layout is not valid.'); }
  if (raw.length > MAX_WIDGETS) { if (lenient) raw = raw.slice(0, MAX_WIDGETS); else throw new Error('A dashboard can have at most ' + MAX_WIDGETS + ' widgets.'); }
  var widgets = dashboardWidgets();
  var seen = {};
  var out = [];
  raw.forEach(function (w) {
    w = w && typeof w === 'object' ? w : {};
    var id = String(w.id || '');
    var def = widgets.hasOwnProperty(id) ? widgets[id] : null;
    var span = Number(w.span);
    var problem = !def ? 'Unknown widget "' + cleanText(id, 40) + '".'
      : def.roles.indexOf(role) === -1 ? '"' + def.title + '" is not available for your role.'
      : seen[id] ? '"' + def.title + '" is on the dashboard twice.'
      : LAYOUT_SPANS.indexOf(span) === -1 ? 'Widget sizes are 4, 6, 8 or 12 columns.' : '';
    if (problem) { if (lenient) return; throw new Error(problem); }
    seen[id] = true;
    out.push({ id: id, span: span });
  });
  return out;
}

function roleDefaultLayout(role) {
  var group = layoutGroup(role);
  var stored = getSetting('dashboardDefault_' + group, '');
  var layout = stored ? cleanLayout(stored, role, true) : null;
  return layout && layout.length ? layout : cleanLayout(BUILT_IN_LAYOUTS[group], role, true);
}

function findUserLayoutRow(sheet, email) {
  var rows = sheetToObjects(sheet);
  for (var i = 0; i < rows.length; i++) {
    if (lowerEmail(rows[i].Email) === lowerEmail(email)) return { index: i + 2, row: rows[i] };
  }
  return null;
}

function widgetChoices(role) {
  var widgets = dashboardWidgets();
  return Object.keys(widgets).filter(function (id) { return widgets[id].roles.indexOf(role) !== -1; })
    .map(function (id) { return { id: id, title: widgets[id].title }; });
}

function svc_getDashboardLayout(session) {
  var hit = findUserLayoutRow(getUserLayoutsSheet(), session.email);
  var mine = hit && hit.row.Layout ? cleanLayout(hit.row.Layout, session.role, true) : null;
  return {
    layout: mine && mine.length ? mine : roleDefaultLayout(session.role),
    source: mine && mine.length ? 'user' : 'role',
    widgets: widgetChoices(session.role),
    spans: LAYOUT_SPANS
  };
}

function svc_saveDashboardLayout(session, layout) {
  var clean = cleanLayout(layout, session.role, false);
  if (!clean.length) throw new Error('Keep at least one widget on the dashboard.');
  var sheet = getUserLayoutsSheet();
  var hit = findUserLayoutRow(sheet, session.email);
  var value = JSON.stringify(clean);
  if (hit) sheet.getRange(hit.index, 1, 1, 3).setValues([[safeCellValue(String(session.email)), value, nowIso()]]);
  else appendObject(sheet, { Email: session.email, Layout: value, UpdatedAt: nowIso() });
  audit(session, 'update_layout', 'DashboardLayout', session.email, { Widgets: { from: '', to: clean.length } }, 'Saved own dashboard layout');
  return svc_getDashboardLayout(session);
}

// Back to the role's default (the saved layout is cleared, not deleted).
function svc_resetDashboardLayout(session) {
  var sheet = getUserLayoutsSheet();
  var hit = findUserLayoutRow(sheet, session.email);
  if (hit && hit.row.Layout) {
    sheet.getRange(hit.index, 1, 1, 3).setValues([[safeCellValue(String(session.email)), '', nowIso()]]);
    audit(session, 'update_layout', 'DashboardLayout', session.email, null, 'Reset own dashboard layout to the role default');
  }
  return svc_getDashboardLayout(session);
}

// Admin or senior manager: the default for agents ('agent') or for everyone
// who sees the team ('team').
function svc_saveRoleDefaultLayout(session, group, layout) {
  requireRole(session, SENIOR_ROLES);
  if (group !== 'agent' && group !== 'team') throw new Error('Choose the agent or the team default.');
  var clean = cleanLayout(layout, group === 'agent' ? 'agent' : 'manager', false);
  if (!clean.length) throw new Error('Keep at least one widget on the dashboard.');
  setSetting(session, 'dashboardDefault_' + group, JSON.stringify(clean));
  audit(session, 'update_settings', 'Settings', 'dashboardDefault_' + group, { Widgets: { from: '', to: clean.length } },
    'Changed the default dashboard for ' + (group === 'agent' ? 'agents' : 'managers and admins'));
  return clean;
}


// ---- Handover.gs ----
// Handover.gs — deactivating an agent without leaving patients behind.
//
// A manager asks for an agent to be deactivated and says who takes over
// their patients (the successor). An admin or senior manager approves or rejects. Approving
// moves everything the agent still handles to the successor in one locked,
// audited step, then deactivates the account:
//   - every patient they own (with all of those patients' open records in
//     every module and their active refill reminders);
//   - any other open record or active reminder still in their name.
// Completed and cancelled records stay in their name, so their incentives
// and history are kept.
//
// The server never deactivates someone who still handles patients without a
// successor (see svc_updateUser).

var USER_REQUEST_HEADERS = ['ID', 'Type', 'UserEmail', 'UserName', 'SuccessorEmail', 'SuccessorName', 'Reason',
  'RequestedByEmail', 'RequestedByName', 'Status', 'DecidedByEmail', 'DecidedByName', 'DecisionNote', 'CreatedAt', 'DecidedAt'];

function getUserRequestsSheet() { return getOrCreateSheet('UserRequests', USER_REQUEST_HEADERS); }

function userRequestForClient(r) {
  return {
    ID: String(r.ID), Type: String(r.Type), UserEmail: String(r.UserEmail), UserName: String(r.UserName),
    SuccessorEmail: String(r.SuccessorEmail), SuccessorName: String(r.SuccessorName), Reason: String(r.Reason || ''),
    RequestedByName: String(r.RequestedByName), Status: String(r.Status), DecidedByName: String(r.DecidedByName || ''),
    DecisionNote: String(r.DecisionNote || ''), CreatedAt: isoString(r.CreatedAt), DecidedAt: isoString(r.DecidedAt)
  };
}

// What this person still handles: patients they own, open records and
// active reminders in their name.
function openWorkOf(world, email) {
  var e = lowerEmail(email);
  world.records.forEach(function (x) { if (lowerEmail(x.row.AgentEmail) === e) ensureHousehold(world, recordContactKey(x.row)); });
  var patients = world.patients.filter(function (p) { return p.OwnerStatus === PATIENT_OWNED && lowerEmail(p.OwnerEmail) === e; });
  var records = world.records.filter(function (x) { return x.row.Status === 'Pending' && lowerEmail(x.row.AgentEmail) === e; });
  var reminders = sheetToObjects(getRemindersSheet()).filter(function (r) {
    return r.Status === 'Active' && lowerEmail(r.AgentEmail) === e;
  });
  return { patients: patients, records: records, reminders: reminders };
}

function hasOpenWork(work) { return work.patients.length > 0 || work.records.length > 0 || work.reminders.length > 0; }

// Moves all of `user`'s work to `successor`. Call inside the script lock.
function handOverWork(session, world, user, successor, why) {
  var work = openWorkOf(world, user.Email);
  var res = movePatients(session, world, work.patients, successor, why);
  var records = res.records.length;
  var e = lowerEmail(user.Email);

  // Open records whose patient isn't owned by them (e.g. an owner conflict
  // still waiting for an admin): move the records, leave the patient as is.
  world.records.forEach(function (x) {
    if (x.row.Status !== 'Pending' || lowerEmail(x.row.AgentEmail) !== e) return;
    var before = x.row;
    var patch = { AgentEmail: successor.email, AgentName: successor.name, UpdatedAt: nowIso() };
    x.row = updateObjectById(getSaleSheet(x.type), before.ID, patch);
    addActivity(session, x.type, before.ID, { Type: 'Note', Notes: 'Reassigned from ' + before.AgentName + ' to ' + successor.name + '. Reason: ' + why });
    audit(session, 'reassign', saleEntity(x.type), before.ID, saleChanges(before, patch), 'Reassigned from ' + before.AgentName + ' to ' + successor.name + '. Reason: ' + why);
    records++;
  });

  var reminders = res.reminders;
  var remSheet = getRemindersSheet();
  sheetToObjects(remSheet).forEach(function (r) {
    if (r.Status !== 'Active' || lowerEmail(r.AgentEmail) !== e) return;
    var patch = { AgentEmail: successor.email, AgentName: successor.name, Reassigned: true, UpdatedAt: nowIso() };
    updateObjectById(remSheet, r.ID, patch);
    audit(session, 'reassign', 'Reminder', r.ID, auditDiff(r, patch), 'Refill reminder handed over to ' + successor.name + '. Reason: ' + why);
    reminders++;
  });
  savePatientChanges(world);
  return { patients: work.patients.length, records: records, reminders: reminders };
}

function findUserById(id) {
  return sheetToObjects(getUsersSheet()).find(function (u) { return String(u.ID) === String(id); }) || null;
}

// Manager (or admin): ask for an agent to be deactivated, naming who takes over.
function svc_requestDeactivation(session, data) {
  requireRole(session, TEAM_ROLES);
  data = data || {};
  var user = findUserById(data.userId);
  if (!user || !isActive(user.Active)) throw new Error('User not found or already inactive.');
  if (String(user.ID) === String(session.id)) throw new Error('You cannot request your own deactivation.');
  if (user.Role === 'admin') throw new ForbiddenError('Admin accounts can only be deactivated by an admin on the Users page.');
  var why = cleanText(data.reason, 300);
  if (why.length < 3) throw new Error('Give a reason (at least 3 characters).');
  var world = loadPatientWorld();
  var successor = requireOwnerCandidate(world, data.successorEmail);
  if (lowerEmail(successor.email) === lowerEmail(user.Email)) throw new Error('Choose someone else to take over.');

  var sheet = getUserRequestsSheet();
  var pending = sheetToObjects(sheet).some(function (r) {
    return r.Status === 'Pending' && lowerEmail(r.UserEmail) === lowerEmail(user.Email);
  });
  if (pending) throw new Error('There is already a pending deactivation request for ' + user.Name + '.');

  var row = {
    ID: newId(), Type: 'deactivate', UserEmail: user.Email, UserName: user.Name,
    SuccessorEmail: successor.email, SuccessorName: successor.name, Reason: why,
    RequestedByEmail: session.email, RequestedByName: session.name, Status: 'Pending',
    DecidedByEmail: '', DecidedByName: '', DecisionNote: '', CreatedAt: nowIso(), DecidedAt: ''
  };
  appendObject(sheet, row);
  var work = openWorkOf(world, user.Email);
  audit(session, 'request_deactivation', 'User', user.ID, { Successor: { from: '', to: successor.email } },
    'Asked to deactivate ' + user.Email + ' (' + work.patients.length + ' patients, ' + work.records.length +
    ' open records) and hand over to ' + successor.name + '. Reason: ' + why);
  return userRequestForClient(row);
}

function svc_listUserRequests(session, includeDecided) {
  requireRole(session, TEAM_ROLES);
  return sheetToObjects(getUserRequestsSheet())
    .filter(function (r) { return r.ID && (includeDecided || r.Status === 'Pending'); })
    .map(userRequestForClient)
    .sort(function (a, b) { return new Date(b.CreatedAt) - new Date(a.CreatedAt); });
}

// Admin or senior manager: approve (hand over, then deactivate) or reject.
function svc_decideUserRequest(session, data) {
  requireRole(session, SENIOR_ROLES);
  data = data || {};
  var sheet = getUserRequestsSheet();
  var req = sheetToObjects(sheet).find(function (r) { return String(r.ID) === String(data.id); });
  if (!req) throw new Error('Request not found.');
  if (req.Status !== 'Pending') throw new Error('This request was already decided.');
  if (lowerEmail(req.UserEmail) === lowerEmail(session.email)) throw new ForbiddenError('You cannot decide a request about your own account.');
  var note = cleanText(data.note, 300);
  var approve = data.approve === true;
  var handover = null;

  if (approve) {
    var user = sheetToObjects(getUsersSheet()).find(function (u) { return lowerEmail(u.Email) === lowerEmail(req.UserEmail); });
    if (!user || !isActive(user.Active)) throw new Error('This account is already inactive. Reject the request instead.');
    var world = loadPatientWorld();
    var successor = requireOwnerCandidate(world, req.SuccessorEmail);
    handover = handOverWork(session, world, user, successor, 'Deactivation of ' + user.Name + ' approved.' + (note ? ' ' + note : ''));
    updateObjectById(getUsersSheet(), user.ID, { Active: false });
    audit(session, 'update', 'User', user.ID, { Active: { from: true, to: false } },
      'Deactivated ' + user.Email + '; ' + handover.patients + ' patients, ' + handover.records + ' open records and ' +
      handover.reminders + ' reminders handed to ' + successor.name);
  }
  var patch = {
    Status: approve ? 'Approved' : 'Rejected', DecidedByEmail: session.email, DecidedByName: session.name,
    DecisionNote: note, DecidedAt: nowIso()
  };
  var updated = updateObjectById(sheet, req.ID, patch);
  audit(session, approve ? 'approve_request' : 'reject_request', 'UserRequest', req.ID, auditDiff(req, patch),
    (approve ? 'Approved' : 'Rejected') + ' deactivation of ' + req.UserEmail + (note ? '. Note: ' + note : ''));
  return { request: userRequestForClient(updated), handover: handover };
}


// ---- Homekare.gs ----
// Homekare.gs — home nursing / caretaker / procedure services.
//
// A Homekare record lists one or more services from the catalogue below,
// each with the price agreed for this patient (prices vary per patient, so
// they are typed, not looked up). The amount is the sum of the lines,
// worked out on the server. Service names are kept exactly as MedUnited's
// billing system has them.
//
// Monthly packages: when a record with a monthly service is Completed, a
// renewal reminder is created on the Reminders page, due a few days before
// the month ends (the package runs from the record date for one month).
// A newer completed monthly order for the same patient resolves the old
// reminder as Renewed.
//
// Visit dates, number of days and the staff sent are not tracked yet (to be
// decided); they can be added later as extra columns.

var HOMEKARE_RENEWAL_DAYS_BEFORE = 5;
var MAX_SERVICE_LINES = 30;

// name | how it is usually charged | monthly package?
var HOMEKARE_SERVICES = [
  ['HOMEKARE - BED RETURN TRANSPORT CHARGES', 'Per trip', false],
  ['HOMEKARE - BLOOD TRANSFUSION CHARGES', 'Per visit', false],
  ['HOMEKARE - CARE TAKER SERVICE 1HR', 'Per hour', false],
  ['HOMEKARE - CARE TAKER SERVICE 24HRs', 'Per 24-hour shift', false],
  ['HOMEKARE - CARE TAKER SERVICE WITH TRAVEL CHARGES MONTHLY PACKAGE', 'Per month (package)', true],
  ['HOMEKARE - CARETAKER PER DAY', 'Per day', false],
  ['HOMEKARE - CARETAKER SERVICE MONTHY', 'Per month', true],
  ['HOMEKARE - ECG', 'Per visit', false],
  ['HOMEKARE - INJECTION', 'Per visit', false],
  ['HOMEKARE - MAJOR DRESSING', 'Per visit', false],
  ['HOMEKARE - MAJOR DRESSING MOTHLY', 'Per month (package)', true],
  ['HOMEKARE - MINOR DRESSING', 'Per visit', false],
  ['HOMEKARE - NURSING 12Hrs', 'Per 12-hour shift', false],
  ['HOMEKARE - NURSING 4HRS', 'Per 4-hour shift', false],
  ['HOMEKARE - PATIENT CARE 12 Hrs', 'Per 12-hour shift', false],
  ['HOMEKARE - RYLES TUBE FEEDING', 'Per visit', false],
  ['HOMEKARE - SUCTION OPERATOR PORTABLE (per day)', 'Per day', false],
  ['HOMEKARE - SUCTION OPERATOR PORTABLE (per month)', 'Per month', true],
  ['HOMEKARE 2 FUNCTIONAL BED RENT PER DAY', 'Per day (rental)', false],
  ['HOMEKARE CONSULTATION', 'Per visit', false],
  ['HOMEKARE ELETROTHERAPY SINGLE MODALITY', 'Per session', false],
  ['HOMEKARE EXERCISE THERAPY', 'Per session', false],
  ['HOMEKARE FOLEYS CATHERIZATION', 'Per visit', false],
  ['HOMEKARE FOLEYS REMOVAL', 'Per visit', false],
  ['HOMEKARE GENERAL MEDICINE CONSULTATAION', 'Per visit', false],
  ['HOMEKARE GENERAL PRACTIONER CONSULTATION', 'Per visit', false],
  ['HOMEKARE IM INJECTION', 'Per visit', false],
  ['HOMEKARE IV CANNULATION', 'Per visit', false],
  ['HOMEKARE IV CANNULATION  INJECTIONS', 'Per visit', false],
  ['HOMEKARE IV INJECTION', 'Per visit', false],
  ['HOMEKARE LIMB ELIVATION', 'Per visit', false],
  ['HOMEKARE MAJOR SUTURING', 'Per visit', false],
  ['HOMEKARE MINOR SUTURING', 'Per visit', false],
  ['HOMEKARE NEBULISATION', 'Per visit', false],
  ['HOMEKARE NURSING CHARGES (6Hrs)', 'Per 6-hour shift', false],
  ['HOMEKARE RYLES TUBE INSERTION', 'Per visit', false],
  ['HOMEKARE TRAVEL CHARGES', 'Per visit (add-on)', false],
  ['HOMEKARE VITALS AND GRBS', 'Per visit', false]
];

// The list in use: the built-in services above, plus any added in Settings
// (homekareServicesExtra), with some hidden from the picker
// (homekareServicesHidden). Hidden services stay valid, so older records
// that use them still save. Nothing is ever deleted.
var homekareListCache_ = null; // one read per request; cleared when the list changes

function serviceKey(name) { return cleanText(name, 200).toLowerCase().replace(/\s+/g, ' '); }

function readSettingList(key) {
  try {
    var v = JSON.parse(getSetting(key, '[]') || '[]');
    return Array.isArray(v) ? v : [];
  } catch (e) {
    return [];
  }
}

function homekareServiceList() {
  if (homekareListCache_) return homekareListCache_;
  var hidden = {};
  readSettingList('homekareServicesHidden').forEach(function (n) { hidden[serviceKey(n)] = true; });
  var list = HOMEKARE_SERVICES.map(function (s) { return { name: s[0], unit: s[1], monthly: s[2], builtIn: true }; });
  readSettingList('homekareServicesExtra').forEach(function (x) {
    if (x && x.name) list.push({ name: String(x.name), unit: String(x.unit || ''), monthly: x.monthly === true, builtIn: false });
  });
  list.forEach(function (x) { x.hidden = !!hidden[serviceKey(x.name)]; });
  homekareListCache_ = list;
  return list;
}

function homekareCatalogue() {
  return homekareServiceList().map(function (s) {
    return { name: s.name, unit: s.unit, monthly: s.monthly, hidden: s.hidden, builtIn: s.builtIn };
  });
}

// Matching ignores case and repeated spaces, then returns [name, unit, monthly].
function findHomekareService(name) {
  var key = serviceKey(name);
  var list = homekareServiceList();
  for (var i = 0; i < list.length; i++) {
    if (serviceKey(list[i].name) === key) return [list[i].name, list[i].unit, list[i].monthly];
  }
  return null;
}

// Admin or senior manager: { add: { name, unit, monthly } } | { hide: name } | { show: name }.
function svc_updateHomekareCatalogue(session, data) {
  requireRole(session, SENIOR_ROLES);
  data = data || {};
  var summary;
  if (data.add) {
    var name = cleanText(data.add.name, 120);
    if (name.length < 3) throw new Error('Give the service a name (at least 3 characters).');
    if (findHomekareService(name)) throw new Error('"' + name + '" is already in the list.');
    var extra = readSettingList('homekareServicesExtra');
    extra.push({ name: name, unit: cleanText(data.add.unit, 40), monthly: data.add.monthly === true });
    setSetting(session, 'homekareServicesExtra', JSON.stringify(extra));
    summary = 'Added Homekare service ' + name + (data.add.monthly === true ? ' (monthly package)' : '');
  } else if (data.hide || data.show) {
    var s = findHomekareService(data.hide || data.show);
    if (!s) throw new Error('That service is not in the list.');
    var hidden = readSettingList('homekareServicesHidden').filter(function (n) { return serviceKey(n) !== serviceKey(s[0]); });
    if (data.hide) hidden.push(s[0]);
    setSetting(session, 'homekareServicesHidden', JSON.stringify(hidden));
    summary = (data.hide ? 'Hid' : 'Showed again') + ' Homekare service ' + s[0];
  } else {
    throw new Error('Nothing to change.');
  }
  homekareListCache_ = null;
  audit(session, 'update_settings', 'Settings', 'homekareServices', null, summary);
  return homekareCatalogue();
}

function parseLines(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  try { var v = JSON.parse(value); return Array.isArray(v) ? v : []; } catch (e) { return []; }
}

function linePrice(value, label) {
  var n = Number(value);
  if (value === '' || value === undefined || value === null || !isFinite(n) || n < 0 || n > 10000000 || Math.round(n * 100) / 100 !== n) {
    throw new Error('Enter a price between ₹0 and ₹1,00,00,000 for ' + label + '.');
  }
  return n;
}

function validateHomekareServices(raw) {
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw || '[]'); } catch (e) { throw new Error('The services list is not valid.'); }
  }
  if (raw === undefined || raw === null) raw = [];
  if (!Array.isArray(raw)) throw new Error('The services list is not valid.');
  if (raw.length > MAX_SERVICE_LINES) throw new Error('A record can list at most ' + MAX_SERVICE_LINES + ' services.');
  return raw.map(function (l) {
    l = l && typeof l === 'object' ? l : {};
    var s = findHomekareService(l.service);
    if (!s) throw new Error('"' + cleanText(l.service, 80) + '" is not a Homekare service. Pick one from the list.');
    return { service: s[0], price: linePrice(l.price, s[0]) };
  });
}

function sumLines(lines) {
  return Math.round(lines.reduce(function (t, l) { return t + l.price; }, 0) * 100) / 100;
}

function summarizeServices(lines) {
  return lines.map(function (l) { return l.service.replace(/^HOMEKARE\s*-?\s*/i, '') + ' (₹' + l.price + ')'; }).join(', ');
}

function monthlyServices(lines) {
  return lines.filter(function (l) { var s = findHomekareService(l.service); return s && s[2]; });
}

// Last day of a one-month package that starts on `key`: the day before the
// same date next month (1 Oct → 31 Oct, 15 Oct → 14 Nov). When next month
// has no such date, the package runs to the end of next month (31 Jan → 28 Feb).
function monthEnd(key) {
  var p = String(key).split('-').map(Number);
  var y = p[0] + (p[1] === 12 ? 1 : 0);
  var m = p[1] === 12 ? 1 : p[1] + 1; // 1-based next month
  var lastOfNext = new Date(Date.UTC(y, m, 0)).getUTCDate();
  if (p[2] > lastOfNext) return dayNumberToKey(Date.UTC(y, m - 1, lastOfNext) / DAY_MS);
  return dayNumberToKey(Date.UTC(y, m - 1, p[2]) / DAY_MS - 1);
}

// ===== Hooks (see Modules.gs) =====
function homekarePrepareSave(session, ctx) {
  var data = ctx.data || {};
  var lines = validateHomekareServices(data.services !== undefined ? data.services : (ctx.existing ? ctx.existing.Services : []));
  return { fields: { Services: JSON.stringify(lines), Amount: sumLines(lines), Detail: summarizeServices(lines) }, warnings: [] };
}

function homekareValidateCompletion(next) {
  if (!parseLines(next.Services).length) throw new Error('Add the services before marking this Homekare record as Completed.');
}

function homekareClientFields(row) {
  var lines = parseLines(row.Services);
  return { Services: lines, MonthlyPackage: monthlyServices(lines).length > 0 };
}

function homekarePrepareImport(r, errors) {
  return { Amount: 0, Services: '[]' };
}

// Create, refresh or remove the renewal reminder for one Homekare record.
function homekareAfterSave(sale) {
  var sheet = getRemindersSheet();
  var rows = sheetToObjects(sheet);
  var existing = rows.filter(function (r) { return r.SaleType === 'homekare' && String(r.SaleID) === String(sale.ID); })[0];
  var monthly = monthlyServices(parseLines(sale.Services));
  if (sale.Status !== 'Completed' || !monthly.length) {
    if (existing) {
      var idx = findRowIndexById(sheet, existing.ID);
      if (idx !== -1) sheet.deleteRow(idx);
    }
    return;
  }
  var start = dateKey(sale.Date);
  var end = monthEnd(start);
  var mirror = {
    CustomerName: sale.CustomerName, Contact: sale.Contact, SaleDate: start, EndDate: end,
    DueDate: dayNumberToKey(keyToDayNumber(end) - HOMEKARE_RENEWAL_DAYS_BEFORE),
    Detail: monthly.map(function (l) { return l.service; }).join(', '), PatientID: sale.PatientID || '', UpdatedAt: nowIso()
  };
  if (existing) {
    if (!isActive(existing.Reassigned)) { mirror.AgentEmail = sale.AgentEmail; mirror.AgentName = sale.AgentName; }
    updateObjectById(sheet, existing.ID, mirror);
    return;
  }
  // A new monthly package for this patient renews the previous one.
  rows.forEach(function (r) {
    if (r.Kind !== 'renewal' || r.Status !== 'Active' || String(r.SaleID) === String(sale.ID)) return;
    var samePatient = sale.PatientID ? String(r.PatientID) === String(sale.PatientID)
      : recordContactKey(r) === recordContactKey(sale) && nameKey(r.CustomerName) === nameKey(sale.CustomerName);
    if (samePatient) updateObjectById(sheet, r.ID, { Status: 'Resolved', ResolutionReason: 'Renewed', UpdatedAt: nowIso() });
  });
  appendObject(sheet, Object.assign({
    ID: newId(), Kind: 'renewal', SaleType: 'homekare', SaleID: sale.ID, PharmacySaleID: '',
    AgentEmail: sale.AgentEmail, AgentName: sale.AgentName, Reassigned: false, Products: '',
    Status: 'Active', ResolutionReason: '', AttemptCount: 0, LastAttemptDate: '', CreatedAt: nowIso()
  }, mirror));
}

function homekareAfterDelete(saleId) {
  var sheet = getRemindersSheet();
  var existing = sheetToObjects(sheet).filter(function (r) { return r.SaleType === 'homekare' && String(r.SaleID) === String(saleId); })[0];
  if (!existing) return;
  var idx = findRowIndexById(sheet, existing.ID);
  if (idx !== -1) sheet.deleteRow(idx);
}


// ---- Import.gs ----
// Import.gs — bulk-add leads from a spreadsheet (Excel / CSV is parsed in the
// browser; this receives plain rows).
//
// Two steps, same function:
//   dryRun: true   validate every row and report problems, save nothing
//   dryRun: false  validate again (data may have changed since the preview)
//                  and save only the rows that pass, in one batch
//
// Imported rows are always new Pending leads. The same rules as one-by-one
// entry apply: a valid phone number, one open record per patient (phone +
// name) per module (checked against the sheet AND within the file), values
// from the admin's dropdown lists, agents can only import leads for
// themselves, and a row for a patient someone already handles goes to them
// (shown as a warning in the preview).

var IMPORT_MAX_ROWS = 500;

// Lenient matching for values typed by hand in Excel: case/spacing-insensitive.
function matchOption(value, options) {
  var v = cleanText(value, 60).toLowerCase().replace(/\s+/g, ' ');
  if (!v) return '';
  for (var i = 0; i < options.length; i++) {
    if (String(options[i]).toLowerCase() === v) return options[i];
  }
  return null;
}

// Accepts 2026-10-15, 15-10-2026, 15/10/2026, 15.10.2026 (day first, as written in India).
function parseImportDate(value) {
  var s = cleanText(value, 20);
  if (!s) return '';
  var m;
  if ((m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(s))) s = m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2);
  else if ((m = /^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/.exec(s))) s = m[3] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2);
  return isDateKey(s) ? s : null;
}

function parseYesNo(value, fallback) {
  var v = cleanText(value, 10).toLowerCase();
  if (!v) return fallback;
  if (['yes', 'y', 'true', '1'].indexOf(v) !== -1) return true;
  if (['no', 'n', 'false', '0'].indexOf(v) !== -1) return false;
  return null;
}

function svc_importSales(session, type, rows, options) {
  var mod = getModule(type);
  options = options || {};
  if (!Array.isArray(rows) || rows.length === 0) throw new Error('The file has no rows to import.');
  if (rows.length > IMPORT_MAX_ROWS) throw new Error('You can import at most ' + IMPORT_MAX_ROWS + ' rows at a time. Split the file and import it in parts.');

  var lists = getLists();
  var users = sheetToObjects(getSheetByName('Users'));
  var activeByEmail = {};
  users.forEach(function (u) { if (isActive(u.Active)) activeByEmail[String(u.Email).toLowerCase()] = u; });

  // Patients and their owners, so each row goes to the agent who already
  // handles that person (or that household).
  var world = loadPatientWorld();
  var seenInFile = {};
  var results = [];
  var toSave = [];
  var defaultOwner = resolveAssignee(session, options.agentEmail);

  rows.forEach(function (raw, i) {
    var r = raw && typeof raw === 'object' ? raw : {};
    var errors = [];
    var warnings = [];
    var rowNo = Number(r._row) || (i + 2); // spreadsheet row number (row 1 = headers)

    var name = cleanText(r.customerName, 120);
    if (!name) errors.push('Customer name is missing.');
    var contact = cleanText(r.contact, 30);
    var key = phoneKey(contact);
    var person = key + '|' + nameKey(name);
    if (!key) errors.push('Phone number is missing or invalid.');
    else if (name && seenInFile[person]) errors.push('Same person (phone number and name) as row ' + seenInFile[person] + ' in this file.');
    else if (name) {
      ensureHousehold(world, key);
      var dup = findOpenRecordForPatient(world, type, findPerson(world, key, name));
      if (dup) errors.push('Already has an open ' + SALE_TYPES[type] + ' record (managed by ' + dup.row.AgentName + ').');
    }
    if (key && name && !seenInFile[person]) seenInFile[person] = rowNo;

    var temperature = 'Warm';
    if (cleanText(r.temperature)) {
      temperature = matchOption(r.temperature, LEAD_TEMPERATURES);
      if (!temperature) errors.push('Temperature must be Hot, Warm or Cold.');
    }
    var direction = 'Inbound';
    if (cleanText(r.direction)) {
      direction = matchOption(r.direction, LEAD_DIRECTIONS);
      if (!direction) errors.push('Direction must be Inbound or Outbound.');
    }
    var channel = lists.channels.indexOf('Other') !== -1 ? 'Other' : lists.channels[0];
    if (cleanText(r.channel)) {
      var ch = matchOption(r.channel, lists.channels);
      if (ch) channel = ch;
      else warnings.push('Unknown channel "' + cleanText(r.channel, 40) + '" — saved as ' + channel + '.');
    }
    var heardFrom = '';
    if (cleanText(r.heardFrom) && direction !== 'Outbound') {
      var hf = matchOption(r.heardFrom, lists.heardFrom);
      if (hf) heardFrom = hf;
      else warnings.push('Unknown "heard from" value "' + cleanText(r.heardFrom, 40) + '" — left blank.');
    }
    var nextFollowUp = parseImportDate(r.nextFollowUp);
    if (nextFollowUp === null) { errors.push('Follow-up date is not a valid date (use YYYY-MM-DD or DD/MM/YYYY).'); nextFollowUp = ''; }
    var date = parseImportDate(r.date);
    if (date === null) { errors.push('Date is not a valid date (use YYYY-MM-DD or DD/MM/YYYY).'); date = ''; }
    var consent = parseYesNo(r.consent, true);
    if (consent === null) { errors.push('Consent must be Yes or No.'); consent = true; }
    var dnd = parseYesNo(r.doNotCall, false);
    if (dnd === null) { errors.push('Do Not Call must be Yes or No.'); dnd = false; }

    var priceType = '';
    if (mod.priceTypes) {
      priceType = 'Full Price';
      if (cleanText(r.priceType)) {
        priceType = matchOption(r.priceType, PRICE_TYPES);
        if (!priceType) errors.push('Price type must be Full Price, Discounted or Converted From OP.');
      }
    }
    var amount = 0;
    if (cleanText(r.amount)) {
      var n = Number(String(r.amount).replace(/[₹,\s]/g, ''));
      if (isNaN(n) || n < 0 || n > 1e8) errors.push('Amount is not a valid number.');
      else amount = Math.round(n * 100) / 100;
    }
    // Module rules for imported leads (e.g. Medpass sets its own price).
    var importHook = moduleHook(type, 'prepareImport');
    var importFields = importHook ? (importHook({ priceType: priceType, amount: amount }, errors) || {}) : {};
    if (importFields.Amount !== undefined) amount = importFields.Amount;

    var owner = defaultOwner;
    if (cleanText(r.agentEmail)) {
      if (session.role === 'agent') {
        if (cleanEmail(r.agentEmail) !== String(session.email).toLowerCase()) warnings.push('Agents can only import their own leads — assigned to you.');
      } else {
        var u = activeByEmail[cleanEmail(r.agentEmail)];
        if (!u) errors.push('Agent "' + cleanText(r.agentEmail, 80) + '" is not an active user.');
        else owner = { email: u.Email, name: u.Name };
      }
    }

    var notes = cleanText(r.notes, MAX_LONG_TEXT);
    var detail = cleanText(r.detail, MAX_LONG_TEXT);
    if ((mod.products || mod.lineItems) && detail) {
      notes = (notes ? notes + '\n' : '') + (mod.products ? 'Medicines mentioned: ' : 'Mentioned: ') + detail;
      detail = '';
    }

    // Only rows that pass get a patient, so a bad row never adds anyone.
    var link = null;
    if (!errors.length) {
      link = resolvePatientOwner(world, { contactKey: key, contact: contact, name: name, requested: owner });
      if (link.notice) warnings.push(link.notice);
      owner = link.owner;
    }

    results.push({
      row: rowNo, customerName: name, contact: contact, ok: errors.length === 0,
      errors: errors, warnings: warnings, agentName: owner.name
    });
    if (errors.length) return;

    var now = nowIso();
    toSave.push(Object.assign({
      ID: newId(),
      Date: date || todayKey(),
      AgentEmail: owner.email,
      AgentName: owner.name,
      CustomerName: name,
      Contact: contact,
      ContactKey: key,
      Detail: detail,
      Products: mod.products ? '[]' : '',
      Amount: amount,
      Status: 'Pending',
      PriceType: priceType,
      PaymentMethod: '',
      UTR: '',
      BillScreenshotUrl: '',
      PaymentScreenshotUrl: '',
      Notes: notes,
      Temperature: temperature,
      Direction: direction,
      Channel: channel,
      HeardFrom: heardFrom,
      Consent: consent,
      DoNotCall: dnd,
      LostReason: '',
      NextFollowUp: nextFollowUp,
      CreatedAt: now,
      UpdatedAt: now,
      PatientID: link.patient.ID
    }, importFields));
  });

  var summary = {
    total: rows.length,
    valid: toSave.length,
    invalid: rows.length - toSave.length,
    imported: 0,
    dryRun: !!options.dryRun,
    results: results
  };
  if (options.dryRun || toSave.length === 0) return summary;

  savePatientChanges(world);
  // One write for all rows instead of hundreds of appendRow calls.
  var sheet = getSaleSheet(type);
  var headers = sheetHeaders(sheet);
  var values = toSave.map(function (obj) {
    return headers.map(function (h) { return safeCellValue(obj[h] !== undefined ? obj[h] : ''); });
  });
  sheet.getRange(sheet.getLastRow() + 1, 1, values.length, headers.length).setValues(values);

  auditMany(session, toSave.map(function (s) {
    return {
      action: 'create', entity: saleEntity(type), entityId: s.ID, changes: saleChanges(null, s),
      summary: 'Imported ' + SALE_TYPES[type] + ' lead for ' + s.CustomerName + (options.fileName ? ' from ' + cleanText(options.fileName, 80) : '')
    };
  }));
  audit(session, 'import', saleEntity(type), '', { Rows: { from: '', to: toSave.length } },
    'Imported ' + toSave.length + ' ' + SALE_TYPES[type] + ' leads' + (options.fileName ? ' from ' + cleanText(options.fileName, 80) : '') +
    (summary.invalid ? ' (' + summary.invalid + ' rows skipped)' : ''));
  summary.imported = toSave.length;
  return summary;
}


// ---- Incentives.gs ----
// Incentives.gs — monthly targets per agent and module, and the incentive
// report behind payouts.
//
// Targets (Targets tab): one row per month + agent + module. Each module's
// target is measured either as revenue (₹ of completed sales, the default)
// or as a number of completed sales — a setting per module
// (Settings: targetMeasure_<module>). Managers and above set targets and can
// copy last month's; agents only ever see their own targets and progress.
// Hitting a target does not change incentives (to be decided later).
//
// Incentive report: completed sales in a month, per agent and module, with
// the incentive each earned under the agent's rates (Users tab) and the
// module's rule (Modules.gs). Managers and above only — agents never see
// incentive amounts. Rates are the current ones: a rate change also changes
// what earlier months show.

var TARGET_HEADERS = ['ID', 'Month', 'AgentEmail', 'Module', 'Target', 'UpdatedAt', 'UpdatedBy'];
var TARGET_MEASURES = ['revenue', 'count'];

function getTargetsSheet() { return getOrCreateSheet('Targets', TARGET_HEADERS); }

// 'yyyy-MM'; blank means this month (India time).
function cleanMonth(value) {
  var m = cleanText(value, 7);
  if (!m) return todayKey().slice(0, 7);
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(m)) throw new Error('Month must look like 2026-10.');
  return m;
}

// A Month cell back as 'yyyy-MM' (even if Sheets turned it into a date).
function monthOf(value) {
  return Object.prototype.toString.call(value) === '[object Date]' ? dateKey(value).slice(0, 7) : String(value || '').slice(0, 7);
}

function previousMonth(month) {
  var p = month.split('-').map(Number);
  return p[1] === 1 ? (p[0] - 1) + '-12' : p[0] + '-' + ('0' + (p[1] - 1)).slice(-2);
}

function targetMeasure(type) {
  var v = String(getSetting('targetMeasure_' + type, 'revenue'));
  return TARGET_MEASURES.indexOf(v) !== -1 ? v : 'revenue';
}

function targetMeasures() {
  var out = {};
  moduleIds().forEach(function (t) { out[t] = targetMeasure(t); });
  return out;
}

// Completed sales of a month: { agentEmail: { module: { count, amount, sales: [...] } } }.
function completedInMonth(month, onlyEmail) {
  var out = {};
  moduleIds().forEach(function (type) {
    sheetToObjects(getSaleSheet(type)).forEach(function (r) {
      if (!r.ID || r.Status !== 'Completed' || dateKey(r.Date).slice(0, 7) !== month) return;
      var e = lowerEmail(r.AgentEmail);
      if (onlyEmail && e !== lowerEmail(onlyEmail)) return;
      var a = out[e] = out[e] || { name: String(r.AgentName) };
      var m = a[type] = a[type] || { count: 0, amount: 0, rows: [] };
      m.count++;
      m.amount += Number(r.Amount) || 0;
      m.rows.push(r);
    });
  });
  return out;
}

// People who can have targets: active agents and managers.
function targetPeople() {
  return sheetToObjects(getUsersSheet()).filter(function (u) {
    return u.ID && isActive(u.Active) && (u.Role === 'agent' || u.Role === 'manager');
  });
}

function svc_getTargets(session, month) {
  month = cleanMonth(month);
  var isAgent = session.role === 'agent';
  var measures = targetMeasures();
  var stored = {};
  sheetToObjects(getTargetsSheet()).forEach(function (t) {
    if (monthOf(t.Month) !== month || t.Target === '' || t.Target === null) return;
    stored[lowerEmail(t.AgentEmail) + '|' + t.Module] = Number(t.Target) || 0;
  });
  var done = completedInMonth(month, isAgent ? session.email : null);
  var people = isAgent ? [{ Email: session.email, Name: session.name }] : targetPeople();
  var rows = [];
  people.forEach(function (u) {
    var e = lowerEmail(u.Email);
    moduleIds().forEach(function (type) {
      var target = stored.hasOwnProperty(e + '|' + type) ? stored[e + '|' + type] : null;
      var got = (done[e] && done[e][type]) || { count: 0, amount: 0 };
      var achieved = measures[type] === 'count' ? got.count : Math.round(got.amount * 100) / 100;
      rows.push({
        agentEmail: String(u.Email), agentName: String(u.Name), module: type, moduleLabel: SALE_TYPES[type],
        measure: measures[type], target: target, achieved: achieved,
        percent: target ? Math.round((achieved / target) * 100) : null
      });
    });
  });
  return { month: month, measures: measures, rows: rows, canEdit: !isAgent };
}

// entries: [{ agentEmail, module, target }] — a blank target clears it.
function svc_saveTargets(session, data) {
  requireRole(session, TEAM_ROLES);
  data = data || {};
  var month = cleanMonth(data.month);
  var entries = Array.isArray(data.entries) ? data.entries : [];
  if (!entries.length) throw new Error('Nothing to save.');
  if (entries.length > 2000) throw new Error('Too many targets at once.');
  var people = {};
  targetPeople().forEach(function (u) { people[lowerEmail(u.Email)] = u; });

  var clean = entries.map(function (x) {
    x = x && typeof x === 'object' ? x : {};
    var u = people[cleanEmail(x.agentEmail)];
    if (!u) throw new Error('"' + cleanText(x.agentEmail, 80) + '" is not an active agent or manager.');
    getModule(x.module);
    var raw = x.target;
    var value = '';
    if (raw !== '' && raw !== null && raw !== undefined) {
      value = Number(raw);
      if (!isFinite(value) || value < 0 || value > 1e9) throw new Error('Targets must be numbers between 0 and 1,00,00,00,000.');
      if (targetMeasure(x.module) === 'count' && Math.round(value) !== value) throw new Error(SALE_TYPES[x.module] + ' targets are a number of sales — use whole numbers.');
      value = Math.round(value * 100) / 100;
    }
    return { email: u.Email, module: x.module, target: value };
  });

  var sheet = getTargetsSheet();
  var rows = sheetToObjects(sheet);
  var index = {};
  rows.forEach(function (r, i) { if (monthOf(r.Month) === month) index[lowerEmail(r.AgentEmail) + '|' + r.Module] = { at: i + 2, row: r }; });
  var changed = 0;
  clean.forEach(function (c) {
    var key = lowerEmail(c.email) + '|' + c.module;
    var hit = index[key];
    if (hit) {
      var before = hit.row.Target === '' ? '' : Number(hit.row.Target);
      if (before === c.target) return;
      updateObjectById(sheet, hit.row.ID, { Target: c.target, UpdatedAt: nowIso(), UpdatedBy: session.email });
      changed++;
    } else if (c.target !== '') {
      appendObject(sheet, { ID: newId(), Month: month, AgentEmail: c.email, Module: c.module, Target: c.target, UpdatedAt: nowIso(), UpdatedBy: session.email });
      changed++;
    }
  });
  if (changed) audit(session, 'update_targets', 'Targets', month, { Changed: { from: '', to: changed } }, 'Updated ' + changed + ' monthly target(s) for ' + month);
  var out = svc_getTargets(session, month);
  out.changed = changed;
  return out;
}

// Copies one month's targets into another; existing ones are kept unless overwrite.
function svc_copyTargets(session, data) {
  requireRole(session, TEAM_ROLES);
  data = data || {};
  var to = cleanMonth(data.toMonth);
  var from = data.fromMonth ? cleanMonth(data.fromMonth) : previousMonth(to);
  if (from === to) throw new Error('Choose a different month to copy from.');
  var people = {};
  targetPeople().forEach(function (u) { people[lowerEmail(u.Email)] = true; });
  var entries = [];
  var existing = {};
  sheetToObjects(getTargetsSheet()).forEach(function (t) {
    if (monthOf(t.Month) === to && t.Target !== '') existing[lowerEmail(t.AgentEmail) + '|' + t.Module] = true;
  });
  var skipped = 0;
  sheetToObjects(getTargetsSheet()).forEach(function (t) {
    if (monthOf(t.Month) !== from || t.Target === '' || !people[lowerEmail(t.AgentEmail)] || !MODULES.hasOwnProperty(t.Module)) return;
    if (existing[lowerEmail(t.AgentEmail) + '|' + t.Module] && data.overwrite !== true) { skipped++; return; }
    entries.push({ agentEmail: t.AgentEmail, module: t.Module, target: t.Target });
  });
  if (!entries.length) {
    var none = svc_getTargets(session, to);
    none.copied = 0;
    none.skipped = skipped;
    return none;
  }
  var out = svc_saveTargets(session, { month: to, entries: entries });
  out.copied = entries.length;
  out.skipped = skipped;
  return out;
}

function svc_setTargetMeasure(session, data) {
  requireRole(session, SENIOR_ROLES);
  data = data || {};
  getModule(data.module);
  requireOneOf(String(data.measure), TARGET_MEASURES, 'Target measure');
  var before = targetMeasure(data.module);
  if (before !== data.measure) {
    setSetting(session, 'targetMeasure_' + data.module, data.measure);
    audit(session, 'update_settings', 'Settings', 'targetMeasure_' + data.module, { Measure: { from: before, to: data.measure } },
      SALE_TYPES[data.module] + ' targets are now measured as ' + (data.measure === 'count' ? 'number of sales' : 'revenue'));
  }
  return targetMeasures();
}

// ===== Incentive report =====
function svc_incentiveReport(session, month) {
  requireRole(session, TEAM_ROLES);
  month = cleanMonth(month);
  var rates = {};
  sheetToObjects(getUsersSheet()).forEach(function (u) { rates[lowerEmail(u.Email)] = u; });
  var done = completedInMonth(month, null);
  var round = function (n) { return Math.round(n * 100) / 100; };
  var totals = { count: 0, amount: 0, incentive: 0, modules: {} };
  moduleIds().forEach(function (t) { totals.modules[t] = { count: 0, amount: 0, incentive: 0 }; });

  var agents = Object.keys(done).map(function (e) {
    var a = { agentEmail: e, agentName: done[e].name, modules: {}, count: 0, amount: 0, incentive: 0, sales: [] };
    moduleIds().forEach(function (type) {
      var m = done[e][type];
      var slot = a.modules[type] = { count: 0, amount: 0, incentive: 0 };
      if (!m) return;
      var mod = getModule(type);
      m.rows.forEach(function (r) {
        var inc = round(incentiveForSale(mod, r, rates[e]));
        slot.count++;
        slot.amount += Number(r.Amount) || 0;
        slot.incentive += inc;
        a.sales.push({
          id: String(r.ID), module: type, moduleLabel: SALE_TYPES[type], date: dateKey(r.Date), customerName: String(r.CustomerName),
          amount: Number(r.Amount) || 0, priceType: String(r.PriceType || ''), detail: String(r.Detail || '').slice(0, 200), incentive: inc
        });
      });
      slot.amount = round(slot.amount);
      slot.incentive = round(slot.incentive);
      a.count += slot.count;
      a.amount += slot.amount;
      a.incentive += slot.incentive;
      totals.modules[type].count += slot.count;
      totals.modules[type].amount += slot.amount;
      totals.modules[type].incentive += slot.incentive;
    });
    a.amount = round(a.amount);
    a.incentive = round(a.incentive);
    a.sales.sort(function (x, y) { return x.date < y.date ? -1 : x.date > y.date ? 1 : 0; });
    totals.count += a.count;
    totals.amount += a.amount;
    totals.incentive += a.incentive;
    return a;
  }).sort(function (x, y) { return y.incentive - x.incentive || y.amount - x.amount; });
  totals.amount = round(totals.amount);
  totals.incentive = round(totals.incentive);
  moduleIds().forEach(function (t) { totals.modules[t].amount = round(totals.modules[t].amount); totals.modules[t].incentive = round(totals.modules[t].incentive); });

  return {
    month: month,
    modules: moduleIds().map(function (t) { return { id: t, label: SALE_TYPES[t], incentive: (MODULES[t].incentive || {}).kind || 'none' }; }),
    agents: agents,
    totals: totals
  };
}


// ---- Lab.gs ----
// Lab.gs — Lab & Radiology tests and packages.
//
// There is no test catalogue yet: the agent types each test or package with
// whether it is Lab or Radiology and its price. The amount is the sum of the
// lines, worked out on the server. A catalogue can be added later without
// changing existing records.
//
// Optional tracking on each record:
//   HomeCollection (yes/no) + CollectionDate    home sample collection
//   AppointmentDate                             visit / scan appointment
//   ReportDeliveredOn + ReportDeliveredVia      when and how the report went out
// Agents can still update these after the sale is Completed (reports come
// later), but not the tests or prices.

var LAB_TEST_KINDS = ['Lab', 'Radiology'];
var LAB_REPORT_VIA = ['WhatsApp', 'Email', 'Collected', 'Other'];
var LAB_TRACKING_FIELDS = ['HomeCollection', 'CollectionDate', 'AppointmentDate', 'ReportDeliveredOn', 'ReportDeliveredVia'];

function validateLabTests(raw) {
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw || '[]'); } catch (e) { throw new Error('The tests list is not valid.'); }
  }
  if (raw === undefined || raw === null) raw = [];
  if (!Array.isArray(raw)) throw new Error('The tests list is not valid.');
  if (raw.length > MAX_SERVICE_LINES) throw new Error('A record can list at most ' + MAX_SERVICE_LINES + ' tests.');
  return raw.map(function (l) {
    l = l && typeof l === 'object' ? l : {};
    var name = cleanText(l.name, 120);
    if (!name) throw new Error('Every test needs a name.');
    var kind = cleanText(l.kind, 20) || 'Lab';
    requireOneOf(kind, LAB_TEST_KINDS, 'Type of ' + name);
    return { name: name, kind: kind, price: linePrice(l.price, name) };
  });
}

function summarizeTests(lines) {
  return lines.map(function (l) { return l.name + ' (₹' + l.price + ')'; }).join(', ');
}

// The tracking fields as they should be after this save.
function labTracking(data, existing) {
  var pick = function (key, field) { return data[key] !== undefined ? data[key] : (existing ? existing[field] : ''); };
  var home = asBool(pick('homeCollection', 'HomeCollection'));
  var collection = optionalDateKey(pick('collectionDate', 'CollectionDate'), 'Collection date');
  var appointment = optionalDateKey(pick('appointmentDate', 'AppointmentDate'), 'Appointment date');
  var delivered = optionalDateKey(pick('reportDeliveredOn', 'ReportDeliveredOn'), 'Report delivered on');
  var via = cleanText(pick('reportDeliveredVia', 'ReportDeliveredVia'), 20);
  if (via) requireOneOf(via, LAB_REPORT_VIA, 'Report delivered by');
  if (via && !delivered) throw new Error('Enter the date the report was delivered.');
  if (delivered && !via) throw new Error('Say how the report was delivered (WhatsApp, Email, Collected or Other).');
  return {
    HomeCollection: home,
    CollectionDate: home ? collection : '',
    AppointmentDate: appointment,
    ReportDeliveredOn: delivered,
    ReportDeliveredVia: via
  };
}

// ===== Hooks (see Modules.gs) =====
function labPrepareSave(session, ctx) {
  var data = ctx.data || {};
  var lines = validateLabTests(data.tests !== undefined ? data.tests : (ctx.existing ? ctx.existing.Tests : []));
  var fields = labTracking(data, ctx.existing);
  fields.Tests = JSON.stringify(lines);
  fields.Amount = sumLines(lines);
  fields.Detail = summarizeTests(lines);
  return { fields: fields, warnings: [] };
}

function labValidateCompletion(next) {
  if (!parseLines(next.Tests).length) throw new Error('Add the tests before marking this Lab & Radiology record as Completed.');
}

function labClientFields(row) {
  return {
    Tests: parseLines(row.Tests),
    HomeCollection: asBool(row.HomeCollection),
    CollectionDate: dateKey(row.CollectionDate),
    AppointmentDate: dateKey(row.AppointmentDate),
    ReportDeliveredOn: dateKey(row.ReportDeliveredOn),
    ReportDeliveredVia: String(row.ReportDeliveredVia || '')
  };
}

function labPrepareImport(r, errors) {
  return { Amount: 0, Tests: '[]', HomeCollection: false };
}


// ---- Lists.gs ----
// Lists.gs — admin-editable dropdown options and app settings.
//
//   Lists     Key | Values (JSON array)   — channels, heard-from, lost reasons
//   Settings  Key | Value                 — monthly revenue target, etc.
//
// Both tabs are created automatically on first use.

var LEAD_TEMPERATURES = ['Hot', 'Warm', 'Cold'];
var LEAD_DIRECTIONS = ['Inbound', 'Outbound'];
var ACTIVITY_TYPES = ['Call', 'WhatsApp', 'Visit', 'SMS', 'Email', 'Note'];
var ACTIVITY_DIRECTIONS = ['Outgoing', 'Incoming'];
var ACTIVITY_OUTCOMES = ['Connected', 'No answer', 'Call back later', 'Interested', 'Not interested', 'Wrong number'];

var DEFAULT_LISTS = {
  channels: ['Phone call', 'Walk-in', 'WhatsApp', 'Website form', 'Health camp', 'OPD/IPD referral', 'Other'],
  heardFrom: ['Google search', 'Facebook / Instagram', 'Newspaper', 'Hoarding / banner', 'Existing patient',
    'Doctor referral', 'Health camp', 'Friend or family', 'Other'],
  lostReasons: ['Price too high', 'Already has a provider', 'Not reachable', 'Wrong number', 'Not interested', 'Other']
};

function getListsSheet() { return getOrCreateSheet('Lists', ['Key', 'Values']); }
function getSettingsSheet() { return getOrCreateSheet('Settings', ['Key', 'Value', 'UpdatedAt', 'UpdatedBy']); }

function getLists() {
  var lists = JSON.parse(JSON.stringify(DEFAULT_LISTS));
  sheetToObjects(getListsSheet()).forEach(function (row) {
    if (!lists.hasOwnProperty(row.Key)) return;
    try {
      var v = JSON.parse(row.Values);
      if (Array.isArray(v) && v.length) lists[row.Key] = v.map(String);
    } catch (e) { /* keep default */ }
  });
  return lists;
}

function svc_getLists(session) {
  var lists = getLists();
  // Fixed options are sent too, so the browser never hard-codes them.
  lists.temperatures = LEAD_TEMPERATURES;
  lists.directions = LEAD_DIRECTIONS;
  lists.activityTypes = ACTIVITY_TYPES;
  lists.activityDirections = ACTIVITY_DIRECTIONS;
  lists.outcomes = ACTIVITY_OUTCOMES;
  return lists;
}

function svc_updateLists(session, data) {
  requireRole(session, SENIOR_ROLES);
  var sheet = getListsSheet();
  var before = getLists();
  Object.keys(DEFAULT_LISTS).forEach(function (key) {
    if (data[key] === undefined) return;
    if (!Array.isArray(data[key])) throw new Error('List "' + key + '" must be a list of options.');
    var seen = {};
    var clean = data[key].map(function (v) { return cleanText(v, 50); }).filter(function (v) {
      if (!v || seen[v.toLowerCase()]) return false;
      seen[v.toLowerCase()] = true;
      return true;
    });
    if (clean.length === 0) throw new Error('List "' + key + '" needs at least one option.');
    if (clean.length > 40) throw new Error('List "' + key + '" can have at most 40 options.');

    var rows = sheetToObjects(sheet);
    var at = rows.findIndex(function (r) { return r.Key === key; });
    if (at !== -1) {
      sheet.getRange(at + 2, 1, 1, 2).setValues([[key, JSON.stringify(clean)]]);
    } else {
      appendObject(sheet, { Key: key, Values: JSON.stringify(clean) });
    }
  });
  var after = getLists();
  audit(session, 'update_lists', 'Lists', '', auditDiff(
    { channels: before.channels.join(', '), heardFrom: before.heardFrom.join(', '), lostReasons: before.lostReasons.join(', ') },
    { channels: after.channels.join(', '), heardFrom: after.heardFrom.join(', '), lostReasons: after.lostReasons.join(', ') }));
  return svc_getLists(session);
}

// ===== Settings =====
var DEFAULT_MONTHLY_TARGET = 500000;

function getSetting(key, fallback) {
  var row = sheetToObjects(getSettingsSheet()).find(function (r) { return r.Key === key; });
  return row && row.Value !== '' ? row.Value : fallback;
}

function setSetting(session, key, value) {
  var sheet = getSettingsSheet();
  var rows = sheetToObjects(sheet);
  var at = rows.findIndex(function (r) { return r.Key === key; });
  var record = [key, value, nowIso(), session.email];
  if (at !== -1) sheet.getRange(at + 2, 1, 1, 4).setValues([record.map(safeCellValue)]);
  else appendObject(sheet, { Key: key, Value: value, UpdatedAt: record[2], UpdatedBy: record[3] });
}

function getMonthlyTarget() {
  var v = Number(getSetting('monthlyTarget', DEFAULT_MONTHLY_TARGET));
  return v > 0 ? v : DEFAULT_MONTHLY_TARGET;
}

function svc_getMonthlyTarget(session) {
  return getMonthlyTarget();
}

function svc_updateMonthlyTarget(session, amount) {
  requireRole(session, TEAM_ROLES);
  var value = Math.round(Number(amount));
  if (!isFinite(value) || value <= 0 || value > 1e10) throw new Error('Target must be a number greater than 0.');
  var before = getMonthlyTarget();
  setSetting(session, 'monthlyTarget', value);
  audit(session, 'update_target', 'Settings', 'monthlyTarget', { MonthlyTarget: { from: before, to: value } });
  return value;
}


// ---- Medpass.gs ----
// Medpass.gs — the Medpass family pass: price, members, discounts, validity.
//
// A Medpass is a one-year pass for a family: father, mother and their
// children under 21 (on the sale date). Two children are included; a third
// and a fourth can be added for an extra fee each (also for a single parent).
// Older children and other relatives (e.g.
// grandparents on the same phone number) take their own pass.
//
// Prices and limits live in the Settings tab (admins / senior managers):
//   medpassPrice 1499 · medpassMaxDiscount 200 · medpassExtraChildFee 375 ·
//   medpassIncludedChildren 2 · medpassMaxExtraChildren 2 ·
//   medpassChildMaxAge 21 · medpassSingleParent TRUE
//
// The server works out the amount; the browser can't type one in:
//   Full Price         price (+ extra-child fees)
//   Discounted         price − discount (₹1…max) (+ fees). Needs approval by
//                      an admin or senior manager before it can be Completed.
//   Converted From OP  the total stays the full price — that is the revenue,
//                      and what incentives use. The OP consultation fee the
//                      patient already paid is credited (shown on the bill as
//                      a discount), so they pay the rest now. No discount.
// PayableNow is what the customer pays today.
//
// Completing a pass sets ValidFrom (sale date) and ValidUntil (one year,
// inclusive). Someone already covered by an active pass gets a warning, not a
// block — renewal rules are still to be decided.
//
// Rows saved before these rules (no ListPrice) keep the amount they had once
// Completed; open ones follow the rules on their next save.

var MEDPASS_RELATIONS = ['Father', 'Mother', 'Child'];
var DISCOUNT_STATUSES = ['Requested', 'Approved', 'Rejected'];
var MEDPASS_SETTING_KEYS = {
  price: { key: 'medpassPrice', def: 1499, min: 1, max: 1000000, label: 'Medpass price' },
  maxDiscount: { key: 'medpassMaxDiscount', def: 200, min: 0, max: 1000000, label: 'Maximum discount' },
  extraChildFee: { key: 'medpassExtraChildFee', def: 375, min: 0, max: 1000000, label: 'Extra child fee' },
  includedChildren: { key: 'medpassIncludedChildren', def: 2, min: 0, max: 10, label: 'Children included' },
  maxExtraChildren: { key: 'medpassMaxExtraChildren', def: 2, min: 0, max: 10, label: 'Extra children allowed' },
  childMaxAge: { key: 'medpassChildMaxAge', def: 21, min: 1, max: 100, label: 'Children must be younger than' }
};

function getMedpassSettings() {
  var stored = {};
  sheetToObjects(getSettingsSheet()).forEach(function (r) { stored[String(r.Key)] = r.Value; });
  var out = {};
  Object.keys(MEDPASS_SETTING_KEYS).forEach(function (k) {
    var d = MEDPASS_SETTING_KEYS[k];
    var v = stored[d.key];
    var n = v === undefined || v === '' ? d.def : Number(v);
    out[k] = isFinite(n) && n >= d.min && n <= d.max ? n : d.def;
  });
  var sp = stored.medpassSingleParent;
  out.singleParent = sp === undefined || sp === '' ? true : asBool(sp);
  return out;
}

function svc_getMedpassSettings(session) { return getMedpassSettings(); }

function svc_updateMedpassSettings(session, data) {
  requireRole(session, SENIOR_ROLES);
  data = data || {};
  var before = getMedpassSettings();
  var next = JSON.parse(JSON.stringify(before));
  Object.keys(MEDPASS_SETTING_KEYS).forEach(function (k) {
    if (data[k] === undefined || data[k] === '') return;
    var d = MEDPASS_SETTING_KEYS[k];
    var n = Number(data[k]);
    if (!isFinite(n) || n < d.min || n > d.max || Math.round(n * 100) / 100 !== n) {
      throw new Error(d.label + ' must be a number between ' + d.min + ' and ' + d.max + '.');
    }
    next[k] = n;
  });
  if (data.singleParent !== undefined) next.singleParent = data.singleParent === true || data.singleParent === 'true';
  if (next.maxDiscount >= next.price) throw new Error('The maximum discount must be less than the price.');
  ['includedChildren', 'maxExtraChildren', 'childMaxAge'].forEach(function (k) {
    if (Math.round(next[k]) !== next[k]) throw new Error(MEDPASS_SETTING_KEYS[k].label + ' must be a whole number.');
  });

  var changes = {};
  Object.keys(MEDPASS_SETTING_KEYS).forEach(function (k) {
    if (next[k] !== before[k]) { setSetting(session, MEDPASS_SETTING_KEYS[k].key, next[k]); changes[MEDPASS_SETTING_KEYS[k].label] = { from: before[k], to: next[k] }; }
  });
  if (next.singleParent !== before.singleParent) {
    setSetting(session, 'medpassSingleParent', next.singleParent);
    changes['Single parent allowed'] = { from: before.singleParent, to: next.singleParent };
  }
  if (Object.keys(changes).length) audit(session, 'update_settings', 'Settings', 'medpass', changes, 'Updated Medpass prices and family rules');
  return next;
}

// ===== Members =====
// Whole years between two 'yyyy-MM-dd' days.
function ageOn(dobKey, onKey) {
  var b = String(dobKey).split('-').map(Number);
  var o = String(onKey).split('-').map(Number);
  var age = o[0] - b[0];
  if (o[1] < b[1] || (o[1] === b[1] && o[2] < b[2])) age--;
  return age;
}

function parseMembers(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  try { var v = JSON.parse(value); return Array.isArray(v) ? v : []; } catch (e) { return []; }
}

// The people a pass covers, checked against the family rules for the sale date.
function validateMembers(raw, saleDate, settings) {
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw || '[]'); } catch (e) { throw new Error('The family members list is not valid.'); }
  }
  if (raw === undefined || raw === null) raw = [];
  if (!Array.isArray(raw)) throw new Error('The family members list is not valid.');
  if (raw.length > 10) throw new Error('A Medpass covers at most 10 people.');
  var on = isDateKey(saleDate) ? saleDate : todayKey();
  var seen = {};
  var members = raw.map(function (m) {
    m = m && typeof m === 'object' ? m : {};
    var name = cleanText(m.name, 120);
    if (!name) throw new Error('Every family member needs a name.');
    if (seen[nameKey(name)]) throw new Error(name + ' is listed twice.');
    seen[nameKey(name)] = true;
    var relation = cleanText(m.relation, 20);
    requireOneOf(relation, MEDPASS_RELATIONS, 'Relation of ' + name);
    var dob = optionalDateKey(m.dob, 'Date of birth of ' + name);
    if (dob && dob > on) throw new Error('The date of birth of ' + name + ' is after the sale date.');
    if (relation === 'Child') {
      if (!dob) throw new Error('Enter the date of birth of ' + name + ' (children must be under ' + settings.childMaxAge + ').');
      var age = ageOn(dob, on);
      if (age >= settings.childMaxAge) {
        throw new Error(name + ' is ' + age + '. Children must be under ' + settings.childMaxAge + ' to be on the family pass; they need their own Medpass.');
      }
    }
    return { name: name, relation: relation, dob: dob };
  });
  var count = function (r) { return members.filter(function (m) { return m.relation === r; }).length; };
  if (count('Father') > 1 || count('Mother') > 1) throw new Error('A family pass covers one father and one mother. Other relatives need their own Medpass.');
  var maxChildren = settings.includedChildren + settings.maxExtraChildren;
  if (count('Child') > maxChildren) {
    throw new Error('A family pass covers up to ' + maxChildren + ' children (' + settings.includedChildren + ' included' +
      (settings.maxExtraChildren ? ', ' + settings.maxExtraChildren + ' extra for a fee' : '') + ').');
  }
  var parents = count('Father') + count('Mother');
  if (members.length && parents === 0) throw new Error('Add at least one parent to the family pass.');
  if (members.length && !settings.singleParent && parents < 2) throw new Error('A family pass needs both parents.');
  return members;
}

// ===== Price =====
function round2(n) { return Math.round(n * 100) / 100; }

// The price fields for a pass. Pending records may leave the discount reason
// and the OP fee for later; completing needs them (medpassValidateCompletion).
function medpassPricing(priceType, members, discountAmount, opCredit, settings) {
  var children = members.filter(function (m) { return m.relation === 'Child'; }).length;
  var extraFee = Math.max(0, children - settings.includedChildren) * settings.extraChildFee;
  var total = settings.price + extraFee;
  var out = { ListPrice: settings.price, ExtraChildFee: extraFee, DiscountAmount: 0, OPCredit: 0, Amount: total, PayableNow: total };
  if (priceType === 'Discounted') {
    var d = Number(discountAmount);
    if (discountAmount === '' || discountAmount === undefined || discountAmount === null || !(d > 0) || d > settings.maxDiscount || round2(d) !== d) {
      throw new Error('Enter a discount between ₹1 and ₹' + settings.maxDiscount + '.');
    }
    out.DiscountAmount = d;
    out.Amount = round2(total - d);
    out.PayableNow = out.Amount;
  } else if (priceType === 'Converted From OP') {
    var op = opCredit === '' || opCredit === undefined || opCredit === null ? 0 : Number(opCredit);
    if (!isFinite(op) || op < 0 || op > total || round2(op) !== op) throw new Error('The OP consultation fee must be between ₹0 and ₹' + total + '.');
    out.OPCredit = op;
    out.PayableNow = round2(total - op);
  }
  return out;
}

function addOneYear(key) {
  var p = String(key).split('-').map(Number);
  var next = Date.UTC(p[0] + 1, p[1] - 1, p[2]) / DAY_MS; // 29 Feb → 1 Mar
  return dayNumberToKey(next - 1);
}

function isApprover(session) { return SENIOR_ROLES.indexOf(session.role) !== -1; }

// Members of this pass already covered by another active pass on this number.
function coverageWarnings(contactKey, members, exceptId) {
  if (!members.length) return [];
  var today = todayKey();
  var covered = {};
  sheetToObjects(getSaleSheet('medpass')).forEach(function (r) {
    if (r.Status !== 'Completed' || String(r.ID) === String(exceptId || '')) return;
    if (recordContactKey(r) !== String(contactKey)) return;
    var until = dateKey(r.ValidUntil);
    if (!until || until < today) return;
    parseMembers(r.Members).forEach(function (m) { covered[nameKey(m.name)] = until; });
  });
  return members.filter(function (m) { return covered[nameKey(m.name)]; }).map(function (m) {
    return m.name + ' is already covered by a Medpass valid until ' + covered[nameKey(m.name)] + '.';
  });
}

// ===== Hooks (see Modules.gs) =====
function medpassPrepareSave(session, ctx) {
  var data = ctx.data || {};
  var existing = ctx.existing;
  var next = ctx.next;
  var settings = getMedpassSettings();

  var membersIn = data.members !== undefined ? data.members : (existing ? existing.Members : []);
  var discountIn = data.discountAmount !== undefined ? data.discountAmount : (existing ? existing.DiscountAmount : '');
  var opIn = data.opCredit !== undefined ? data.opCredit : (existing ? existing.OPCredit : '');
  var reasonIn = data.discountReason !== undefined ? cleanText(data.discountReason, 300) : String((existing && existing.DiscountReason) || '');

  // A Completed pass keeps its price unless what it is priced on changes
  // (and passes from before these rules keep theirs entirely).
  if (existing && existing.Status === 'Completed') {
    if (existing.ListPrice === '' || existing.ListPrice === undefined) return { fields: {}, warnings: [] };
    var membersNow = JSON.stringify(validateMembers(membersIn, dateKey(next.Date), settings));
    var unchanged = membersNow === JSON.stringify(parseMembers(existing.Members)) &&
      String(next.PriceType) === String(existing.PriceType) &&
      Number(discountIn || 0) === Number(existing.DiscountAmount || 0) &&
      Number(opIn || 0) === Number(existing.OPCredit || 0) &&
      dateKey(next.Date) === dateKey(existing.Date);
    if (unchanged) return { fields: {}, warnings: [] };
  }

  var members = validateMembers(membersIn, dateKey(next.Date), settings);
  var priceType = String(next.PriceType || 'Full Price');
  var fields = medpassPricing(priceType, members, discountIn, opIn, settings);
  fields.Members = JSON.stringify(members);

  if (priceType === 'Discounted') {
    var changed = !existing || existing.PriceType !== 'Discounted' || Number(existing.DiscountAmount || 0) !== fields.DiscountAmount;
    fields.DiscountReason = reasonIn;
    if (changed) {
      if (reasonIn.length < 3) throw new Error('Give a reason for the discount (at least 3 characters).');
      // An approver's own discount needs no second approval.
      fields.DiscountStatus = isApprover(session) ? 'Approved' : 'Requested';
      fields.DiscountRequestedBy = session.name;
      fields.DiscountDecidedBy = isApprover(session) ? session.name : '';
    } else {
      fields.DiscountStatus = String(existing.DiscountStatus || 'Requested');
      fields.DiscountRequestedBy = String(existing.DiscountRequestedBy || '');
      fields.DiscountDecidedBy = String(existing.DiscountDecidedBy || '');
    }
  } else {
    fields.DiscountReason = '';
    fields.DiscountStatus = '';
    fields.DiscountRequestedBy = '';
    fields.DiscountDecidedBy = '';
  }

  if (next.Status === 'Completed') {
    fields.ValidFrom = dateKey(next.Date);
    fields.ValidUntil = addOneYear(fields.ValidFrom);
  } else {
    fields.ValidFrom = '';
    fields.ValidUntil = '';
  }

  var warnings = coverageWarnings(next.ContactKey || (existing && recordContactKey(existing)), members, existing && existing.ID);
  if (fields.DiscountStatus === 'Requested' && (!existing || existing.DiscountStatus !== 'Requested' || data.discountAmount !== undefined && Number(existing.DiscountAmount || 0) !== fields.DiscountAmount)) {
    warnings.push('The ₹' + fields.DiscountAmount + ' discount is waiting for approval by an admin or senior manager.');
  }
  return { fields: fields, warnings: warnings };
}

function medpassValidateCompletion(next) {
  if (next.ListPrice === '' || next.ListPrice === undefined) return; // from before these rules
  var members = parseMembers(next.Members);
  if (!members.length) throw new Error('Add the family members this Medpass covers before marking it Completed.');
  if (next.PriceType === 'Discounted' && next.DiscountStatus !== 'Approved') {
    throw new Error(next.DiscountStatus === 'Rejected'
      ? 'The discount was rejected. Change the price type or ask for a different discount.'
      : 'The discount is waiting for approval by an admin or senior manager.');
  }
  if (next.PriceType === 'Converted From OP' && !(Number(next.OPCredit) > 0)) {
    throw new Error('Enter the OP consultation fee the patient already paid.');
  }
}

function medpassClientFields(row) {
  var until = dateKey(row.ValidUntil);
  return {
    Members: parseMembers(row.Members),
    ListPrice: row.ListPrice === '' || row.ListPrice === undefined ? null : Number(row.ListPrice),
    ExtraChildFee: Number(row.ExtraChildFee) || 0,
    DiscountAmount: Number(row.DiscountAmount) || 0,
    DiscountReason: String(row.DiscountReason || ''),
    DiscountStatus: DISCOUNT_STATUSES.indexOf(row.DiscountStatus) !== -1 ? row.DiscountStatus : '',
    DiscountRequestedBy: String(row.DiscountRequestedBy || ''),
    DiscountDecidedBy: String(row.DiscountDecidedBy || ''),
    OPCredit: Number(row.OPCredit) || 0,
    PayableNow: row.PayableNow === '' || row.PayableNow === undefined ? Number(row.Amount) || 0 : Number(row.PayableNow),
    ValidFrom: dateKey(row.ValidFrom),
    ValidUntil: until,
    PassStatus: row.Status !== 'Completed' || !until ? '' : until >= todayKey() ? 'active' : 'expired'
  };
}

// Imported leads get the standard price. Discounts need a reason and an
// approval, so they're set in the app, not from a spreadsheet.
function medpassPrepareImport(r, errors) {
  if (r.priceType === 'Discounted') {
    errors.push('Discounts can\'t be imported — import as Full Price and add the discount in the app.');
    return {};
  }
  var s = getMedpassSettings();
  return { Amount: s.price, ListPrice: s.price, ExtraChildFee: 0, DiscountAmount: 0, OPCredit: 0, PayableNow: s.price, Members: '[]' };
}

// ===== Discount approval =====
function svc_listPendingDiscounts(session) {
  requireRole(session, TEAM_ROLES);
  return sheetToObjects(getSaleSheet('medpass'))
    .filter(function (r) { return r.ID && r.Status === 'Pending' && r.PriceType === 'Discounted' && r.DiscountStatus === 'Requested'; })
    .map(function (r) {
      return {
        ID: String(r.ID), CustomerName: String(r.CustomerName), AgentName: String(r.AgentName),
        DiscountAmount: Number(r.DiscountAmount) || 0, DiscountReason: String(r.DiscountReason || ''),
        DiscountRequestedBy: String(r.DiscountRequestedBy || ''), Amount: Number(r.Amount) || 0, UpdatedAt: isoString(r.UpdatedAt)
      };
    });
}

// Admin or senior manager approves or rejects a requested discount.
function svc_decideMedpassDiscount(session, data) {
  requireRole(session, SENIOR_ROLES);
  data = data || {};
  var sheet = getSaleSheet('medpass');
  var existing = findSaleRow('medpass', data.id);
  if (!existing) throw new Error('Record not found.');
  if (existing.PriceType !== 'Discounted' || existing.DiscountStatus !== 'Requested') throw new Error('This record has no discount waiting for approval.');
  var approve = data.approve === true;
  var note = cleanText(data.note, 300);
  if (!approve && note.length < 3) throw new Error('Say why the discount is rejected (at least 3 characters).');
  var patch = { DiscountStatus: approve ? 'Approved' : 'Rejected', DiscountDecidedBy: session.name, UpdatedAt: nowIso() };
  var updated = updateObjectById(sheet, existing.ID, patch);
  var summary = (approve ? 'Approved' : 'Rejected') + ' the ₹' + existing.DiscountAmount + ' discount' + (note ? '. Note: ' + note : '');
  addActivity(session, 'medpass', existing.ID, { Type: 'Note', Notes: summary });
  audit(session, approve ? 'approve_discount' : 'reject_discount', saleEntity('medpass'), existing.ID,
    { DiscountStatus: { from: 'Requested', to: patch.DiscountStatus } }, summary + ' for ' + existing.CustomerName);
  return fullSaleForClient('medpass', updated);
}


// ---- Modules.gs ----
// Modules.gs — the sales modules (Medpass, Pharmacy, …) as configuration.
//
// Every module is a tab with the same columns (SALE_HEADERS) and runs on
// the same engine (SalesService.gs, Import.gs, the dashboard). What differs
// between modules is described here, so adding a module means adding an
// entry, not copying code:
//
//   id            value of the `type` parameter in the API
//   label         shown to people, also the tab name
//   priceTypes    true → PriceType is required (Full Price / Discounted / …)
//   products      true → medicines list (Products JSON); Detail is a summary of it
//   needsProducts true → can't be Completed without at least one product
//   reminders     true → completed sales get refill reminders
//   incentive     { kind: 'perSale' } flat ₹ per sale by price type, or
//                 { kind: 'percent' } % of the amount — rates live on the Users tab, or
//                 { kind: 'none' } no incentive yet
//   lineItems     true → the record lists typed lines (services/tests); Detail summarises them
//   agentEditableWhenCompleted  extra columns agents may still change once Completed
//   extraHeaders  columns only this module's tab has (added after SALE_HEADERS)
//   hooks         optional module rules, called by the engine:
//     prepareSave(session, ctx)   → { fields, warnings } computed fields for a
//                                   create/update (ctx: isCreate, data, existing, next)
//     validateCompletion(next)    throws if the record can't be Completed yet
//     clientFields(row)           extra fields the browser gets
//     prepareImport(r, errors)    computed fields for an imported lead
//     afterSave(sale) / afterDelete(id)  side effects (e.g. reminders)
//     clientConfig()              extra settings the browser gets from getModules
// Hooks are written as function(…) { return name(…); } so they can live in
// another file (Apps Script doesn't guarantee the order files load in).

var MODULES = {
  medpass: {
    id: 'medpass', label: 'Medpass',
    priceTypes: true, products: false, needsProducts: false, reminders: false,
    incentive: { kind: 'perSale', fullRateField: 'MedpassFullRate', discountRateField: 'MedpassDiscountRate' },
    // See Medpass.gs.
    extraHeaders: ['Members', 'ListPrice', 'ExtraChildFee', 'DiscountAmount', 'DiscountReason', 'DiscountStatus',
      'DiscountRequestedBy', 'DiscountDecidedBy', 'OPCredit', 'PayableNow', 'ValidFrom', 'ValidUntil'],
    hooks: {
      prepareSave: function (session, ctx) { return medpassPrepareSave(session, ctx); },
      validateCompletion: function (next) { return medpassValidateCompletion(next); },
      clientFields: function (row) { return medpassClientFields(row); },
      prepareImport: function (r, errors) { return medpassPrepareImport(r, errors); }
    }
  },
  pharmacy: {
    id: 'pharmacy', label: 'Pharmacy',
    priceTypes: false, products: true, needsProducts: true, reminders: true,
    incentive: { kind: 'percent', percentField: 'PharmacyIncentivePercent' }
  },
  // See Homekare.gs. Prices are typed per patient; incentives to be decided.
  homekare: {
    id: 'homekare', label: 'Homekare',
    priceTypes: false, products: false, needsProducts: false, reminders: false, lineItems: true,
    incentive: { kind: 'none' },
    extraHeaders: ['Services'],
    hooks: {
      prepareSave: function (session, ctx) { return homekarePrepareSave(session, ctx); },
      validateCompletion: function (next) { return homekareValidateCompletion(next); },
      clientFields: function (row) { return homekareClientFields(row); },
      prepareImport: function (r, errors) { return homekarePrepareImport(r, errors); },
      afterSave: function (sale) { return homekareAfterSave(sale); },
      afterDelete: function (id) { return homekareAfterDelete(id); },
      clientConfig: function () { return { services: homekareCatalogue() }; }
    }
  },
  // See Lab.gs. Tests are typed by hand for now; incentives to be decided.
  lab: {
    id: 'lab', label: 'Lab & Radiology',
    priceTypes: false, products: false, needsProducts: false, reminders: false, lineItems: true,
    incentive: { kind: 'none' },
    extraHeaders: ['Tests', 'HomeCollection', 'CollectionDate', 'AppointmentDate', 'ReportDeliveredOn', 'ReportDeliveredVia'],
    agentEditableWhenCompleted: ['HomeCollection', 'CollectionDate', 'AppointmentDate', 'ReportDeliveredOn', 'ReportDeliveredVia'],
    hooks: {
      prepareSave: function (session, ctx) { return labPrepareSave(session, ctx); },
      validateCompletion: function (next) { return labValidateCompletion(next); },
      clientFields: function (row) { return labClientFields(row); },
      prepareImport: function (r, errors) { return labPrepareImport(r, errors); },
      clientConfig: function () { return { testKinds: LAB_TEST_KINDS, reportVia: LAB_REPORT_VIA }; }
    }
  }
};

// Module id → label. Kept under its old name because it is used everywhere.
var SALE_TYPES = {};
Object.keys(MODULES).forEach(function (id) { SALE_TYPES[id] = MODULES[id].label; });

function moduleIds() { return Object.keys(MODULES); }

// Every column of a module's tab: the shared ones, then its own.
function moduleHeaders(type) { return SALE_HEADERS.concat(getModule(type).extraHeaders || []); }

function moduleHook(type, name) {
  var hooks = getModule(type).hooks || {};
  return typeof hooks[name] === 'function' ? hooks[name] : null;
}

function getModule(type) {
  var mod = MODULES.hasOwnProperty(type) ? MODULES[type] : null;
  if (!mod) throw new Error('Invalid sale type.');
  return mod;
}

// Incentive earned on one Completed sale, given the agent's rates row.
function incentiveForSale(mod, row, rates) {
  if (!rates) return 0;
  var inc = mod.incentive || {};
  if (inc.kind === 'perSale') {
    var field = row.PriceType === 'Discounted' ? inc.discountRateField : inc.fullRateField;
    return Number(rates[field]) || 0;
  }
  if (inc.kind === 'percent') {
    return (Number(row.Amount) || 0) * ((Number(rates[inc.percentField]) || 0) / 100);
  }
  return 0;
}

// Module side effects after a record is saved or deleted.
function afterSaleSaved(type, sale) {
  if (getModule(type).reminders) syncReminderForSale(sale);
  var hook = moduleHook(type, 'afterSave');
  if (hook) hook(sale);
}

function afterSaleDeleted(type, saleId) {
  if (getModule(type).reminders) removeReminderForSale(saleId);
  var hook = moduleHook(type, 'afterDelete');
  if (hook) hook(saleId);
}

// What the browser needs to build its menus and forms.
function svc_getModules(session) {
  return moduleIds().map(function (id) {
    var m = MODULES[id];
    var config = moduleHook(id, 'clientConfig');
    return Object.assign({ id: m.id, label: m.label, priceTypes: m.priceTypes, products: m.products, reminders: m.reminders,
      lineItems: !!m.lineItems, incentive: (m.incentive || {}).kind || 'none' }, config ? config() : {});
  });
}


// ---- Patients.gs ----
// Patients.gs — one agent per patient, across every module.
//
// A patient is a person: a phone number + a name. Relatives often share one
// number (a Medpass holder's parents, children…), so everyone on a number is
// a "household". By default a household has one owner agent; a manager can
// split a person out to another agent.
//
//   Patients  ID | ContactKey | Contact | Name | NameKey | DOB | OwnerEmail |
//             OwnerName | OwnerStatus | ConflictAgents | SplitFromHousehold |
//             CreatedAt | UpdatedAt
//
// Module records point at their patient through the PatientID column. Rows
// saved before Patients existed have no PatientID; they are matched by phone
// number + name until migratePatients() (or any save touching that number)
// links them.
//
// OwnerStatus is 'Owned' or 'Conflict'. A household whose existing records
// were handled by more than one agent is never guessed: its people are marked
// Conflict, with the candidate agents in ConflictAgents, until an admin
// decides (keep together under one agent, or split).
//
// Rules enforced here and in SalesService.gs:
//  - a new record for a known patient goes to that patient's owner, whoever
//    enters it; a new person on a known number goes to the household owner;
//  - one open (Pending) record per patient per module;
//  - reassigning moves every open record of the patient (or household) in
//    every module, plus active refill reminders; closed records keep their
//    agent, so incentives stay with whoever closed the sale.

var PATIENT_HEADERS = ['ID', 'ContactKey', 'Contact', 'Name', 'NameKey', 'DOB', 'OwnerEmail', 'OwnerName', 'OwnerStatus',
  'ConflictAgents', 'SplitFromHousehold', 'CreatedAt', 'UpdatedAt'];
var PATIENT_OWNED = 'Owned';
var PATIENT_CONFLICT = 'Conflict';

function getPatientsSheet() { return getOrCreateSheet('Patients', PATIENT_HEADERS); }

// "Ravi  Kumar", "ravi kumar." and "RAVI KUMAR" are the same name. Letters in
// any script are kept, so Telugu / Hindi names compare too.
function nameKey(value) {
  return cleanText(value, 120).toLowerCase().replace(/[.,'"`_\-]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function recordContactKey(row) { return String(row.ContactKey || phoneKey(row.Contact)); }

function lowerEmail(v) { return String(v || '').toLowerCase(); }

// ===== The in-memory picture of patients and records =====
// Loaded once per request. Changes are collected here and written by
// savePatientChanges(), so a request that fails validation writes nothing.
function loadPatientWorld() {
  var world = {
    patients: [], byId: {}, byPerson: {}, byHousehold: {},
    records: [], users: {}, added: [], changed: {}
  };
  sheetToObjects(getPatientsSheet()).forEach(function (p) { if (p.ID) indexPatient(world, p); });
  moduleIds().forEach(function (type) {
    sheetToObjects(getSaleSheet(type)).forEach(function (r) { if (r.ID) world.records.push({ type: type, row: r }); });
  });
  sheetToObjects(getSheetByName('Users')).forEach(function (u) { world.users[lowerEmail(u.Email)] = u; });
  return world;
}

function indexPatient(world, p) {
  world.patients.push(p);
  world.byId[String(p.ID)] = p;
  world.byPerson[String(p.ContactKey) + '|' + String(p.NameKey)] = p;
  (world.byHousehold[String(p.ContactKey)] = world.byHousehold[String(p.ContactKey)] || []).push(p);
}

function householdOf(world, key) { return world.byHousehold[String(key)] || []; }

function findPerson(world, key, name) { return world.byPerson[String(key) + '|' + nameKey(name)] || null; }

// The patient a record belongs to (null if that number was never linked).
function recordPatient(world, row) {
  if (row.PatientID && world.byId[String(row.PatientID)]) return world.byId[String(row.PatientID)];
  return findPerson(world, recordContactKey(row), row.CustomerName);
}

function householdRecords(world, key) {
  return world.records.filter(function (x) { return recordContactKey(x.row) === String(key); });
}

function patientRecords(world, patient) {
  return householdRecords(world, patient.ContactKey).filter(function (x) {
    var p = recordPatient(world, x.row);
    return p && String(p.ID) === String(patient.ID);
  });
}

function activeUser(world, email) {
  var u = world.users[lowerEmail(email)];
  return u && isActive(u.Active) ? u : null;
}

// Who handles this patient now, or null (no owner yet, owner inactive, or
// waiting for an admin to resolve a conflict).
function ownerOfPatient(world, p) {
  if (!p || p.OwnerStatus === PATIENT_CONFLICT || !p.OwnerEmail) return null;
  var u = activeUser(world, p.OwnerEmail);
  return u ? { email: u.Email, name: u.Name } : null;
}

// Distinct active owners of a household's people.
function householdOwners(world, key) {
  var seen = {};
  var out = [];
  householdOf(world, key).forEach(function (p) {
    var o = ownerOfPatient(world, p);
    if (o && !seen[lowerEmail(o.email)]) { seen[lowerEmail(o.email)] = true; out.push(o); }
  });
  return out;
}

function newPatientRow(world, key, contact, name, owner) {
  var now = nowIso();
  var p = {
    ID: newId(), ContactKey: String(key), Contact: contact, Name: cleanText(name, 120), NameKey: nameKey(name), DOB: '',
    OwnerEmail: owner ? owner.email : '', OwnerName: owner ? owner.name : '', OwnerStatus: PATIENT_OWNED,
    ConflictAgents: '', SplitFromHousehold: false, CreatedAt: now, UpdatedAt: now
  };
  indexPatient(world, p);
  world.added.push(p);
  return p;
}

function changePatient(world, p, patch) {
  Object.keys(patch).forEach(function (k) { p[k] = patch[k]; });
  p.UpdatedAt = nowIso();
  if (world.added.indexOf(p) !== -1) return; // not saved yet — it'll be written whole
  var c = world.changed[String(p.ID)] || (world.changed[String(p.ID)] = {});
  Object.keys(patch).forEach(function (k) { c[k] = patch[k]; });
  c.UpdatedAt = p.UpdatedAt;
}

// Creates Patients for any records on this number that don't have one yet
// (rows from before Patients existed). Owner: the one agent who handled the
// household's records; more than one → Conflict for an admin to resolve.
function ensureHousehold(world, key) {
  var rows = householdRecords(world, key);
  var groups = {};
  var order = [];
  rows.forEach(function (x) {
    if (recordPatient(world, x.row)) return;
    var nk = nameKey(x.row.CustomerName);
    if (!groups[nk]) { groups[nk] = []; order.push(nk); }
    groups[nk].push(x);
  });
  if (!order.length) return;

  var stats = {};
  var statOrder = [];
  function stat(email, name) {
    var k = lowerEmail(email);
    if (!stats[k]) { stats[k] = { email: String(email), name: String(name || email), open: 0, closed: 0 }; statOrder.push(k); }
    return stats[k];
  }
  rows.forEach(function (x) {
    if (!x.row.AgentEmail) return;
    var s = stat(x.row.AgentEmail, x.row.AgentName);
    if (x.row.Status === 'Pending') s.open++; else s.closed++;
  });
  householdOf(world, key).forEach(function (p) { if (p.OwnerEmail && p.OwnerStatus === PATIENT_OWNED) stat(p.OwnerEmail, p.OwnerName); });

  order.forEach(function (nk) {
    var first = groups[nk][0].row;
    var p;
    if (statOrder.length === 1) {
      var only = stats[statOrder[0]];
      var u = activeUser(world, only.email);
      p = newPatientRow(world, key, String(first.Contact || ''), first.CustomerName, { email: u ? u.Email : only.email, name: u ? u.Name : only.name });
    } else {
      p = newPatientRow(world, key, String(first.Contact || ''), first.CustomerName, null);
      p.OwnerStatus = PATIENT_CONFLICT;
      p.ConflictAgents = JSON.stringify(statOrder.map(function (k) { return stats[k]; }));
    }
  });
}

// Decides which patient a new or edited record belongs to and who must handle
// it. `requested` is the agent the person entering chose (or themselves).
// Returns { patient, owner, notice, conflict }.
function resolvePatientOwner(world, opts) {
  var key = String(opts.contactKey);
  var requested = opts.requested;
  ensureHousehold(world, key);

  var patient = null;
  if (opts.patientId) {
    patient = world.byId[String(opts.patientId)] || null;
    if (!patient || String(patient.ContactKey) !== key) throw new Error('That person is not on this phone number. Pick them again or add them as someone new.');
  }
  if (!patient) patient = findPerson(world, key, opts.name);

  var owner;
  if (patient) {
    owner = ownerOfPatient(world, patient);
    if (!owner) {
      owner = requested;
      // No conflict, just no usable owner (e.g. deactivated before handovers
      // existed): the person entering takes the patient over.
      if (patient.OwnerStatus !== PATIENT_CONFLICT) changePatient(world, patient, { OwnerEmail: owner.email, OwnerName: owner.name });
    }
  } else {
    var owners = householdOwners(world, key);
    if (owners.length === 1) owner = owners[0];
    else if (owners.length > 1) {
      owner = owners.filter(function (o) { return lowerEmail(o.email) === lowerEmail(requested.email); })[0] || owners[0];
    } else owner = requested;
    patient = newPatientRow(world, key, opts.contact, opts.name, owner);
  }

  var conflict = patient.OwnerStatus === PATIENT_CONFLICT;
  var notice = '';
  if (conflict) notice = 'This patient is waiting for an admin to choose who handles them; the record was saved as entered.';
  else if (lowerEmail(owner.email) !== lowerEmail(requested.email)) notice = 'Already handled by ' + owner.name + ' — assigned to them.';
  return { patient: patient, owner: owner, notice: notice, conflict: conflict };
}

// The open record this patient already has in this module, if any.
function findOpenRecordForPatient(world, type, patient, exceptId) {
  if (!patient) return null;
  var hit = null;
  householdRecords(world, patient.ContactKey).forEach(function (x) {
    if (hit || x.type !== type || x.row.Status !== 'Pending' || String(x.row.ID) === String(exceptId || '')) return;
    var p = recordPatient(world, x.row);
    if (p && String(p.ID) === String(patient.ID)) hit = x;
  });
  return hit;
}

function openRecordMessage(session, type, dup, tail) {
  return 'This patient already has an open ' + SALE_TYPES[type] + ' record' +
    (canAccessSale(session, dup.row) ? ' (' + dup.row.CustomerName + ')' : '') +
    ', managed by ' + dup.row.AgentName + '. ' + tail;
}

// Before a closed record goes back to Pending: it must follow the patient's
// current owner, and the patient can't already have an open one in this module.
// Returns the AgentEmail/AgentName patch to apply (may be empty).
function reopenOwnership(session, world, type, row) {
  ensureHousehold(world, recordContactKey(row));
  var patient = recordPatient(world, row);
  var dup = findOpenRecordForPatient(world, type, patient, row.ID);
  if (dup) throw new Error(openRecordMessage(session, type, dup, 'Close that one first.'));
  var patch = {};
  if (patient && !row.PatientID) patch.PatientID = patient.ID;
  var owner = ownerOfPatient(world, patient);
  if (owner && lowerEmail(owner.email) !== lowerEmail(row.AgentEmail)) {
    if (session.role === 'agent') {
      throw new ForbiddenError('This patient is now handled by ' + owner.name + '. Ask them or a manager to reopen it.');
    }
    patch.AgentEmail = owner.email;
    patch.AgentName = owner.name;
  }
  return patch;
}

// Writes new and changed Patients rows (call inside the script lock, after
// validation has passed).
function savePatientChanges(world) {
  var sheet = getPatientsSheet();
  if (world.added.length) {
    var headers = sheetHeaders(sheet);
    var values = world.added.map(function (p) {
      return headers.map(function (h) { return safeCellValue(p[h] !== undefined ? p[h] : ''); });
    });
    sheet.getRange(sheet.getLastRow() + 1, 1, values.length, headers.length).setValues(values);
    world.added = [];
  }
  Object.keys(world.changed).forEach(function (id) { updateObjectById(sheet, id, world.changed[id]); });
  world.changed = {};
}

// ===== Per-record extras for the browser =====
// AlsoIn: the other modules where this patient has records.
// HouseholdSize: how many people share the number.
function recordExtras(world) {
  var modulesByPerson = {};
  var peopleByKey = {};
  world.records.forEach(function (x) {
    var p = recordPatient(world, x.row);
    var key = recordContactKey(x.row);
    var person = p ? 'p:' + p.ID : 'n:' + key + '|' + nameKey(x.row.CustomerName);
    (modulesByPerson[person] = modulesByPerson[person] || {})[x.type] = true;
    (peopleByKey[key] = peopleByKey[key] || {})[person] = true;
  });
  return function (type, row) {
    var p = recordPatient(world, row);
    var key = recordContactKey(row);
    var person = p ? 'p:' + p.ID : 'n:' + key + '|' + nameKey(row.CustomerName);
    var mods = modulesByPerson[person] || {};
    return {
      PatientID: p ? String(p.ID) : '',
      AlsoIn: moduleIds().filter(function (t) { return t !== type && mods[t]; }).map(function (t) { return SALE_TYPES[t]; }),
      HouseholdSize: Object.keys(peopleByKey[key] || {}).length || 1
    };
  };
}

// ===== Reassigning =====
// A patient can be handled by an active agent or manager.
function requireOwnerCandidate(world, email) {
  var u = activeUser(world, cleanEmail(email));
  if (!u || ['agent', 'manager'].indexOf(String(u.Role)) === -1) throw new Error('Target agent not found or inactive.');
  return { email: u.Email, name: u.Name };
}

// Gives `patients` to `target`: every open record of theirs in every module
// and their active refill reminders move too. Completed/Cancelled records
// keep their agent, so incentives stay with whoever closed the sale.
// Writes as it goes — call inside the script lock, after all checks.
function movePatients(session, world, patients, target, why) {
  var ids = {};
  var keys = {};
  patients.forEach(function (p) { ids[String(p.ID)] = true; keys[String(p.ContactKey)] = true; });
  var note = why ? ' Reason: ' + why : '';
  var moved = [];
  var reminderSales = {};

  world.records.forEach(function (x) {
    if (!keys[recordContactKey(x.row)]) return;
    var p = recordPatient(world, x.row);
    if (!p || !ids[String(p.ID)]) return;
    reminderSales[String(x.row.ID)] = true; // refill and renewal reminders follow the patient
    var patch = {};
    if (!x.row.PatientID) patch.PatientID = p.ID;
    var moving = x.row.Status === 'Pending' && lowerEmail(x.row.AgentEmail) !== lowerEmail(target.email);
    if (moving) { patch.AgentEmail = target.email; patch.AgentName = target.name; }
    if (!Object.keys(patch).length) return;
    patch.UpdatedAt = nowIso();
    var before = x.row;
    x.row = updateObjectById(getSaleSheet(x.type), before.ID, patch);
    if (!moving) return;
    addActivity(session, x.type, before.ID, { Type: 'Note', Notes: 'Reassigned from ' + before.AgentName + ' to ' + target.name + '.' + note });
    audit(session, 'reassign', saleEntity(x.type), before.ID, saleChanges(before, patch),
      'Reassigned from ' + before.AgentName + ' to ' + target.name + note);
    moved.push({ type: x.type, id: String(before.ID) });
  });

  var reminders = 0;
  var remSheet = getRemindersSheet();
  sheetToObjects(remSheet).forEach(function (r) {
    if (r.Status !== 'Active' || !reminderSales[reminderSaleId(r)] || lowerEmail(r.AgentEmail) === lowerEmail(target.email)) return;
    var patch = { AgentEmail: target.email, AgentName: target.name, Reassigned: true, UpdatedAt: nowIso() };
    updateObjectById(remSheet, r.ID, patch);
    audit(session, 'reassign', 'Reminder', r.ID, auditDiff(r, patch), 'Refill reminder moved with the patient to ' + target.name);
    reminders++;
  });

  patients.forEach(function (p) {
    var before = { OwnerEmail: p.OwnerEmail, OwnerName: p.OwnerName, OwnerStatus: p.OwnerStatus };
    var patch = { OwnerEmail: target.email, OwnerName: target.name, OwnerStatus: PATIENT_OWNED, ConflictAgents: '' };
    if (before.OwnerEmail === patch.OwnerEmail && before.OwnerStatus === PATIENT_OWNED) return;
    changePatient(world, p, patch);
    audit(session, 'reassign', 'Patient', p.ID, auditDiff(before, { OwnerEmail: patch.OwnerEmail, OwnerName: patch.OwnerName, OwnerStatus: patch.OwnerStatus }),
      p.Name + ' is now handled by ' + target.name + note);
  });

  // A household with more than one owner has been split on purpose.
  Object.keys(keys).forEach(function (key) {
    var split = householdOwners(world, key).length > 1;
    householdOf(world, key).forEach(function (p) {
      if (asBool(p.SplitFromHousehold) !== split) changePatient(world, p, { SplitFromHousehold: split });
    });
  });
  return { records: moved, reminders: reminders };
}

// Manager/admin: hand a patient — or by default their whole household — to
// another agent. Identify the patient by a record (type + id), a PatientID,
// or a phone number (always the whole household).
function svc_reassignPatient(session, data) {
  requireRole(session, TEAM_ROLES);
  data = data || {};
  var world = loadPatientWorld();
  var target = requireOwnerCandidate(world, data.agentEmail);
  var scope = data.scope === 'person' ? 'person' : 'household';
  var patient = null;
  if (data.type !== undefined && data.id !== undefined) {
    getModule(data.type);
    var rec = world.records.filter(function (x) { return x.type === data.type && String(x.row.ID) === String(data.id); })[0];
    if (!rec) throw new Error('Record not found.');
    ensureHousehold(world, recordContactKey(rec.row));
    patient = recordPatient(world, rec.row);
  } else if (data.patientId) {
    patient = world.byId[String(data.patientId)] || null;
  } else if (data.contact) {
    var key = phoneKey(data.contact);
    if (key) { ensureHousehold(world, key); patient = householdOf(world, key)[0] || null; }
    scope = 'household';
  }
  if (!patient) throw new Error('Patient not found.');
  var group = scope === 'person' ? [patient] : householdOf(world, patient.ContactKey).slice();
  var result = movePatients(session, world, group, target, cleanText(data.reason, 300));
  savePatientChanges(world);
  return { moved: result.records, reminders: result.reminders, patients: group.length, agentName: target.name };
}

// ===== Migration: build Patients from existing records =====
// Safe to run any number of times. It only ADDS Patients rows and fills the
// empty PatientID cell of records; it never changes who a record belongs to.
// A number whose records were handled by more than one agent becomes a
// Conflict for an admin to resolve (listPatientConflicts / resolvePatientConflict).
function migratePatientsCore(session, dryRun) {
  var world = loadPatientWorld();
  var keys = {};
  world.records.forEach(function (x) { var k = recordContactKey(x.row); if (k) keys[k] = true; });
  Object.keys(keys).forEach(function (k) { ensureHousehold(world, k); });

  var links = {};
  var linked = 0;
  world.records.forEach(function (x) {
    if (x.row.PatientID) return;
    var p = recordPatient(world, x.row);
    if (!p) return;
    (links[x.type] = links[x.type] || {})[String(x.row.ID)] = String(p.ID);
    linked++;
  });
  var created = world.added.length;
  var conflictKeys = {};
  world.added.forEach(function (p) { if (p.OwnerStatus === PATIENT_CONFLICT) conflictKeys[String(p.ContactKey)] = true; });
  var summary = {
    dryRun: !!dryRun,
    households: Object.keys(keys).length,
    patientsCreated: created,
    recordsLinked: linked,
    newConflicts: Object.keys(conflictKeys).length,
    conflicts: conflictList(world, Object.keys(conflictKeys)).slice(0, 50)
  };
  if (dryRun) return summary;

  savePatientChanges(world);
  Object.keys(links).forEach(function (type) {
    var sheet = getSaleSheet(type);
    var headers = sheetHeaders(sheet);
    var idCol = headers.indexOf('ID');
    var pidCol = headers.indexOf('PatientID');
    var last = sheet.getLastRow();
    if (idCol === -1 || pidCol === -1 || last < 2) return;
    var ids = sheet.getRange(2, idCol + 1, last - 1, 1).getValues();
    var pids = sheet.getRange(2, pidCol + 1, last - 1, 1).getValues();
    var changed = false;
    for (var i = 0; i < ids.length; i++) {
      var want = links[type][String(ids[i][0])];
      if (want && !pids[i][0]) { pids[i][0] = safeCellValue(want); changed = true; }
    }
    if (changed) sheet.getRange(2, pidCol + 1, last - 1, 1).setValues(pids);
  });
  audit(session, 'migrate', 'Patients', '', {
    PatientsCreated: { from: '', to: created }, RecordsLinked: { from: '', to: linked }, Conflicts: { from: '', to: summary.newConflicts }
  }, 'Patients migration: ' + created + ' patients created, ' + linked + ' records linked, ' +
    summary.newConflicts + ' households need an owner decision.');
  return summary;
}

// Admin, from the app: a dry run unless dryRun is explicitly false.
function svc_migratePatients(session, dryRun) {
  requireRole(session, SENIOR_ROLES);
  return migratePatientsCore(session, dryRun !== false);
}

// From the Apps Script editor: back up the Sheet (File → Make a copy), run
// migratePatientsDryRun and read the log, then run migratePatients.
var MIGRATION_SESSION = { id: 'migration', email: 'migration', name: 'Migration script', role: 'system' };

function migratePatientsDryRun() {
  var s = migratePatientsCore(MIGRATION_SESSION, true);
  Logger.log(JSON.stringify(s, null, 2));
  return s;
}

function migratePatients() {
  var s = withScriptLock(function () { return migratePatientsCore(MIGRATION_SESSION, false); });
  bumpDataVersion();
  Logger.log(JSON.stringify(s, null, 2));
  return s;
}

// ===== Conflicts =====
// Households where an admin has to decide who handles whom.
function conflictList(world, keys) {
  return keys.map(function (key) {
    var people = householdOf(world, key);
    var agents = {};
    people.forEach(function (p) {
      if (p.OwnerStatus !== PATIENT_CONFLICT) return;
      var list = [];
      try { list = JSON.parse(p.ConflictAgents || '[]'); } catch (e) { list = []; }
      list.forEach(function (a) { agents[lowerEmail(a.email)] = a; });
    });
    return {
      contactKey: String(key),
      contact: String((people[0] && people[0].Contact) || key),
      agents: Object.keys(agents).map(function (k) { return agents[k]; }),
      people: people.map(function (p) {
        var o = ownerOfPatient(world, p);
        return {
          ID: world.added.indexOf(p) === -1 ? String(p.ID) : '',
          Name: String(p.Name),
          Conflict: p.OwnerStatus === PATIENT_CONFLICT,
          OwnerName: o ? o.name : '',
          records: patientRecords(world, p).map(function (x) {
            return { module: SALE_TYPES[x.type], status: String(x.row.Status), agentName: String(x.row.AgentName), date: dateKey(x.row.Date) };
          })
        };
      })
    };
  });
}

function svc_listPatientConflicts(session) {
  requireRole(session, TEAM_ROLES);
  var world = loadPatientWorld();
  var keys = {};
  world.records.forEach(function (x) { var k = recordContactKey(x.row); if (k) keys[k] = true; });
  // In memory only, so numbers not migrated yet show up too.
  Object.keys(keys).forEach(function (k) { ensureHousehold(world, k); });
  var conflictKeys = {};
  world.patients.forEach(function (p) { if (p.OwnerStatus === PATIENT_CONFLICT) conflictKeys[String(p.ContactKey)] = true; });
  return conflictList(world, Object.keys(conflictKeys));
}

// Admin decides. Either the whole household to one agent:
//   { contact, agentEmail }
// or person by person (a split):
//   { contact, assignments: [{ patientId | name, agentEmail }] }
// Open records move to the chosen agent; closed ones keep theirs.
function svc_resolvePatientConflict(session, data) {
  requireRole(session, SENIOR_ROLES);
  data = data || {};
  var key = phoneKey(data.contact);
  if (!key) throw new Error('A valid phone number is required.');
  var world = loadPatientWorld();
  ensureHousehold(world, key);
  var household = householdOf(world, key);
  if (!household.some(function (p) { return p.OwnerStatus === PATIENT_CONFLICT; })) {
    throw new Error('This number has no owner conflict. Use Reassign to move patients.');
  }
  var groups = [];
  if (data.agentEmail) {
    groups.push({ target: requireOwnerCandidate(world, data.agentEmail), people: household.slice() });
  } else if (Array.isArray(data.assignments) && data.assignments.length) {
    var byTarget = {};
    data.assignments.forEach(function (a) {
      a = a && typeof a === 'object' ? a : {};
      var p = a.patientId ? world.byId[String(a.patientId)] : findPerson(world, key, a.name);
      if (!p || String(p.ContactKey) !== key) throw new Error('A person in the list is not on this phone number.');
      var t = requireOwnerCandidate(world, a.agentEmail);
      var k = lowerEmail(t.email);
      if (!byTarget[k]) { byTarget[k] = { target: t, people: [] }; groups.push(byTarget[k]); }
      if (byTarget[k].people.indexOf(p) === -1) byTarget[k].people.push(p);
    });
  } else {
    throw new Error('Choose an agent for the household, or one for each person.');
  }
  var moved = [];
  var reminders = 0;
  groups.forEach(function (g) {
    var r = movePatients(session, world, g.people, g.target, 'Owner conflict resolved by admin.');
    moved = moved.concat(r.records);
    reminders += r.reminders;
  });
  savePatientChanges(world);
  return {
    moved: moved,
    reminders: reminders,
    remainingConflicts: householdOf(world, key).filter(function (p) { return p.OwnerStatus === PATIENT_CONFLICT; }).length
  };
}


// ---- Performance.gs ----
// Performance.gs — monthly performance and comparisons (no incentives).
//
// For a chosen month: this month vs last month, vs the same month last year,
// and year-to-date vs the same span last year; a 24-month series for the
// trend chart; a per-module breakdown; and, for managers and above, every
// agent side by side with their change and rank.
//
// Who sees what (server-side): agents only ever get their own figures;
// managers and above get the team or any one agent. Incentive amounts are
// never part of this — they stay on the Incentives page.
//
// Measures: completed sales and revenue by the record's sale date (the same
// rule as the dashboard and targets), new enquiries by the day the record
// was created (India time), average sale value = revenue ÷ sales.

function monthAdd(month, delta) {
  var p = month.split('-').map(Number);
  var n = p[0] * 12 + (p[1] - 1) + delta;
  return Math.floor(n / 12) + '-' + ('0' + ((n % 12) + 1)).slice(-2);
}

function emptyStats() { return { count: 0, amount: 0, leads: 0 }; }

function addStats(into, s) {
  into.count += s.count;
  into.amount += s.amount;
  into.leads += s.leads;
}

function finishStats(s) {
  var amount = Math.round(s.amount * 100) / 100;
  return { count: s.count, amount: amount, leads: s.leads, avg: s.count ? Math.round(amount / s.count) : 0 };
}

function createdMonthOf(row) {
  var c = row.CreatedAt;
  if (!c) return dateKey(row.Date).slice(0, 7);
  var d = Object.prototype.toString.call(c) === '[object Date]' ? c : new Date(c);
  if (isNaN(d.getTime())) return dateKey(row.Date).slice(0, 7);
  return Utilities.formatDate(d, APP_TIMEZONE, 'yyyy-MM-dd').slice(0, 7);
}

function svc_performance(session, data) {
  data = data || {};
  var month = cleanMonth(data.month);
  var isAgent = session.role === 'agent';
  var users = {};
  sheetToObjects(getUsersSheet()).forEach(function (u) { users[lowerEmail(u.Email)] = u; });
  var who = isAgent ? lowerEmail(session.email) : cleanEmail(data.agentEmail || '');
  if (who && !users[who]) throw new Error('That person is not a user of the CRM.');

  // byMonth[month] for the chosen scope; perAgent[email][month] for the team table;
  // perModule[month][type] for the module breakdown.
  var byMonth = {};
  var perAgent = {};
  var perModule = {};
  var bucket = function (map, key) { return map[key] = map[key] || emptyStats(); };

  moduleIds().forEach(function (type) {
    sheetToObjects(getSaleSheet(type)).forEach(function (r) {
      if (!r.ID) return;
      var agent = lowerEmail(r.AgentEmail);
      var inScope = !who || agent === who;
      var lead = createdMonthOf(r);
      var sale = r.Status === 'Completed' ? dateKey(r.Date).slice(0, 7) : null;
      var amount = Number(r.Amount) || 0;
      if (inScope) {
        bucket(byMonth, lead).leads++;
        var pm = perModule[lead] = perModule[lead] || {};
        bucket(pm, type).leads++;
        if (sale) {
          var b = bucket(byMonth, sale);
          b.count++;
          b.amount += amount;
          var pms = perModule[sale] = perModule[sale] || {};
          var m = bucket(pms, type);
          m.count++;
          m.amount += amount;
        }
      }
      if (!isAgent && !who) {
        var pa = perAgent[agent] = perAgent[agent] || { name: String(r.AgentName || agent), months: {} };
        bucket(pa.months, lead).leads++;
        if (sale) {
          var ab = bucket(pa.months, sale);
          ab.count++;
          ab.amount += amount;
        }
      }
    });
  });

  var get = function (map, key) { return map[key] || emptyStats(); };
  var span = function (map, fromMonth, toMonth) {
    var s = emptyStats();
    for (var m = fromMonth; m <= toMonth; m = monthAdd(m, 1)) addStats(s, get(map, m));
    return s;
  };
  var lastMonth = monthAdd(month, -1);
  var sameLastYear = monthAdd(month, -12);
  var yearStart = month.slice(0, 4) + '-01';
  var lastYearStart = monthAdd(yearStart, -12);

  var series = [];
  for (var i = -23; i <= 0; i++) {
    var mk = monthAdd(month, i);
    series.push(Object.assign({ month: mk }, finishStats(get(byMonth, mk))));
  }

  var agents = null;
  if (!isAgent && !who) {
    agents = Object.keys(perAgent).map(function (e) {
      var a = perAgent[e];
      var u = users[e];
      return {
        email: u ? String(u.Email) : e, name: u ? String(u.Name) : a.name, active: u ? isActive(u.Active) : false,
        thisMonth: finishStats(get(a.months, month)), lastMonth: finishStats(get(a.months, lastMonth)),
        ytd: finishStats(span(a.months, yearStart, month)), ytdLastYear: finishStats(span(a.months, lastYearStart, sameLastYear))
      };
    }).filter(function (a) { return a.thisMonth.count || a.lastMonth.count || a.ytd.count || a.thisMonth.leads; });
    agents.sort(function (x, y) { return y.thisMonth.amount - x.thisMonth.amount || y.thisMonth.count - x.thisMonth.count; });
    agents.forEach(function (a, idx) { a.rank = idx + 1; });
  }

  var scopeUser = who ? users[who] : null;
  return {
    month: month,
    scope: who ? { type: 'agent', email: scopeUser ? String(scopeUser.Email) : who, name: scopeUser ? String(scopeUser.Name) : who } : { type: 'team' },
    canPickAgent: !isAgent,
    compare: {
      thisMonth: finishStats(get(byMonth, month)),
      lastMonth: finishStats(get(byMonth, lastMonth)),
      sameMonthLastYear: finishStats(get(byMonth, sameLastYear)),
      ytd: finishStats(span(byMonth, yearStart, month)),
      ytdLastYear: finishStats(span(byMonth, lastYearStart, sameLastYear))
    },
    series: series,
    modules: moduleIds().map(function (t) {
      return {
        id: t, label: SALE_TYPES[t],
        thisMonth: finishStats(get(perModule[month] || {}, t)),
        lastMonth: finishStats(get(perModule[lastMonth] || {}, t))
      };
    }),
    agents: agents
  };
}


// ---- Reminders.gs ----
// Reminders.gs — follow-up reminders on the Reminders page:
//   refill   Pharmacy medicines running out (below)
//   renewal  monthly Homekare packages ending (see Homekare.gs)
// Rows saved before Kind/SaleType/SaleID existed are Pharmacy refills
// (linked by PharmacySaleID).
//
// Each Pharmacy sale can carry multiple products (name, quantity, dosing
// frequency). From that we compute when each product runs out, and surface
// a reminder to the agent a few days before (or after, if overdue) so they
// can contact the customer about a refill. The reminder's *workflow state*
// (contacted / resolved / reassigned) lives in the Reminders sheet — the
// underlying countdown is always recomputed live from the sale's product
// data, never stored, so it's never stale.

var FREQUENCY_DOSES_PER_DAY = {
  'Once a day': 1,
  'Twice a day': 2,
  'Thrice a day': 3
};

var REMINDER_HEADERS = ['ID', 'PharmacySaleID', 'AgentEmail', 'AgentName', 'Reassigned', 'CustomerName', 'Contact',
  'Products', 'SaleDate', 'Status', 'ResolutionReason', 'AttemptCount', 'LastAttemptDate', 'CreatedAt', 'UpdatedAt',
  'Kind', 'SaleType', 'SaleID', 'PatientID', 'Detail', 'EndDate', 'DueDate'];

function getRemindersSheet() { return getOrCreateSheet('Reminders', REMINDER_HEADERS); }

// The record a reminder belongs to (old refill rows only have PharmacySaleID).
function reminderSaleId(r) { return String(r.SaleID || r.PharmacySaleID || ''); }
function reminderKind(r) { return r.Kind === 'renewal' ? 'renewal' : 'refill'; }

var REMINDER_ATTEMPT_ESCALATE_DAYS = 3; // flag for manager attention after this many days of failed contact attempts

function frequencyOptions() {
  return Object.keys(FREQUENCY_DOSES_PER_DAY);
}

// One product line: { name, quantity, frequency, unitsPerDose }. Returns
// the same shape plus computed daysSupply / expiryDate / daysRemaining /
// overdue. unitsPerDose is how many tablets/capsules are taken each time
// (e.g. "2 tablets twice a day"); products saved before this field existed
// count as 1 per dose, which is what the old calculation assumed.
//
// All date maths is on whole calendar days in India time (see dateKey /
// todayKey in Utils.gs), so the countdown never shifts by a day because of
// time zones.
function unitsPerDoseOf(product) {
  var n = Number(product.unitsPerDose);
  return n > 0 ? n : 1;
}

var MEDICINE_FORMS = ['tablet', 'syrup', 'inhaler', 'drops', 'cream', 'injection', 'sachet', 'course'];

// How many days one product line lasts. Mirrors getRefillDays() in the
// browser's SalesView so the form preview and the server agree.
function productDaysSupply(product) {
  var dosesPerDay = FREQUENCY_DOSES_PER_DAY[product.frequency] || 1;
  var qty = Number(product.quantity) || 0;
  var custom = Number(product.customDays) || 0;
  if (custom > 0) return Math.round(custom);
  var form = product.formType || 'tablet';
  var days;
  if (form === 'syrup') {
    var vol = (Number(product.bottleVolume) || qty || 100) * (Number(product.bottlesCount) || 1);
    var ml = Number(product.unitsPerDose) || 5;
    days = Math.floor(vol / (ml * dosesPerDay));
  } else if (form === 'inhaler') {
    var puffs = qty || 200;
    days = Math.floor(puffs / ((Number(product.unitsPerDose) || 2) * dosesPerDay));
  } else if (form === 'cream' || form === 'drops') {
    days = (qty || 1) * 15;
  } else if (form === 'injection') {
    days = Math.floor((qty || 300) / (Number(product.unitsPerDose) || 20));
  } else if (form === 'course') {
    days = qty || 7;
  } else {
    days = Math.floor(qty / (dosesPerDay * unitsPerDoseOf(product)));
  }
  return days > 0 ? days : 1;
}

function computeProductStatus(product, saleDateValue) {
  var daysSupply = productDaysSupply(product);

  var saleKey = dateKey(saleDateValue);
  if (!isDateKey(saleKey)) saleKey = todayKey(); // unreadable date: treat as sold today rather than crash
  var expiryDay = keyToDayNumber(saleKey) + daysSupply;
  var daysRemaining = expiryDay - keyToDayNumber(todayKey());

  var out = {};
  Object.keys(product).forEach(function (k) { out[k] = product[k]; });
  out.quantity = Number(product.quantity) || 0;
  out.unitsPerDose = unitsPerDoseOf(product);
  out.daysSupply = daysSupply;
  out.expiryDate = dayNumberToKey(expiryDay);
  out.daysRemaining = daysRemaining;
  out.overdue = daysRemaining < 1;
  return out;
}

// The reminder's headline urgency is driven by whichever product runs out
// soonest — that's the one that actually needs a call.
function computeReminderUrgency(products, saleDateStr) {
  var statuses = products.map(function (p) { return computeProductStatus(p, saleDateStr); });
  var soonest = statuses.reduce(function (min, s) {
    return (min === null || s.daysRemaining < min.daysRemaining) ? s : min;
  }, null);
  return {
    products: statuses,
    daysRemaining: soonest ? soonest.daysRemaining : null,
    overdue: soonest ? soonest.overdue : false
  };
}

function summarizeProducts(products) {
  return products.map(function (p) {
    if (p.customDays) return p.name + ' (' + p.customDays + '-day course)';
    if (p.formType === 'syrup') {
      var vol = (p.bottleVolume || p.quantity) * (p.bottlesCount || 1);
      return p.name + ' (' + vol + 'ml total, ' + p.unitsPerDose + 'ml ' + p.frequency + ')';
    }
    if (p.formType === 'inhaler') return p.name + ' (' + p.quantity + ' puffs, ' + p.unitsPerDose + ' puffs ' + p.frequency + ')';
    if (p.formType === 'cream' || p.formType === 'drops') return p.name + ' (' + p.quantity + ' ' + (p.unitName || 'unit') + ', ' + p.frequency + ')';
    var perDose = unitsPerDoseOf(p);
    return p.name + ' (x' + p.quantity + ', ' + (perDose !== 1 ? perDose + ' per dose, ' : '') + p.frequency + ')';
  }).join('; ');
}

function boundedNumber(value, min, max, label) {
  if (value === undefined || value === null || value === '') return undefined;
  var n = Number(value);
  if (isNaN(n) || n < min || n > max) throw new Error(label + ' must be a number between ' + min + ' and ' + max + '.');
  return n;
}

// allowEmpty: a Pending pharmacy lead may not know its medicines yet.
function validateProducts(products, allowEmpty) {
  if (allowEmpty && Array.isArray(products) && products.length === 0) return [];
  if (!Array.isArray(products) || products.length === 0) {
    throw new Error('At least one medicine is required.');
  }
  if (products.length > 30) throw new Error('A sale can have at most 30 product lines.');
  return products.map(function (p) {
    if (!p || typeof p !== 'object') throw new Error('Invalid product line.');
    var name = cleanText(p.name, 120);
    if (!name) throw new Error('Every product needs a name.');
    var qty = boundedNumber(p.quantity, 0.01, 100000, 'Quantity');
    if (qty === undefined) throw new Error('Every product needs a quantity greater than 0.');
    var frequency = p.frequency || 'Once a day';
    if (frequencyOptions().indexOf(frequency) === -1) throw new Error('Every product needs a valid frequency.');
    var formType = p.formType || 'tablet';
    requireOneOf(formType, MEDICINE_FORMS, 'Medicine form');
    var per = boundedNumber(p.unitsPerDose, 0.01, 500, 'Units per dose');
    var line = {
      name: name,
      quantity: qty,
      frequency: frequency,
      unitsPerDose: per === undefined ? 1 : per,
      formType: formType,
      unitName: cleanText(p.unitName || (formType === 'syrup' ? 'ml' : formType === 'inhaler' ? 'puffs' : 'tabs'), 20)
    };
    var bottleVolume = boundedNumber(p.bottleVolume, 1, 10000, 'Bottle volume');
    var bottlesCount = boundedNumber(p.bottlesCount, 1, 1000, 'Bottle count');
    var customDays = boundedNumber(p.customDays, 1, 3650, 'Course length (days)');
    if (bottleVolume !== undefined) line.bottleVolume = bottleVolume;
    if (bottlesCount !== undefined) line.bottlesCount = bottlesCount;
    if (customDays !== undefined) line.customDays = customDays;
    return line;
  });
}

// Called after a Pharmacy sale is saved. Creates or refreshes the reminder
// row for that sale, or removes it if the sale is no longer Completed.
function syncReminderForSale(sale) {
  var reminders = getRemindersSheet();
  var existing = sheetToObjects(reminders).find(function (r) { return reminderKind(r) === 'refill' && reminderSaleId(r) === String(sale.ID); });

  var products = [];
  try { products = JSON.parse(sale.Products || '[]'); } catch (e) { products = []; }

  var shouldExist = sale.Status === 'Completed' && products.length > 0;

  if (!shouldExist) {
    if (existing) {
      var rowIndex = findRowIndexById(reminders, existing.ID);
      if (rowIndex !== -1) reminders.deleteRow(rowIndex);
    }
    return;
  }

  if (existing) {
    // Keep workflow state (Status/AttemptCount/etc) — only refresh the data
    // that mirrors the sale, and only touch the assigned agent if a manager
    // hasn't manually reassigned this reminder.
    var patch = {
      CustomerName: sale.CustomerName,
      Contact: sale.Contact,
      Products: sale.Products,
      SaleDate: dateKey(sale.Date),
      UpdatedAt: nowIso()
    };
    if (!isActive(existing.Reassigned)) {
      patch.AgentEmail = sale.AgentEmail;
      patch.AgentName = sale.AgentName;
    }
    updateObjectById(reminders, existing.ID, patch);
  } else {
    appendObject(reminders, {
      ID: newId(),
      PharmacySaleID: sale.ID,
      Kind: 'refill',
      SaleType: 'pharmacy',
      SaleID: sale.ID,
      PatientID: sale.PatientID || '',
      AgentEmail: sale.AgentEmail,
      AgentName: sale.AgentName,
      Reassigned: false,
      CustomerName: sale.CustomerName,
      Contact: sale.Contact,
      Products: sale.Products,
      SaleDate: dateKey(sale.Date),
      Status: 'Active',
      ResolutionReason: '',
      AttemptCount: 0,
      LastAttemptDate: '',
      CreatedAt: nowIso(),
      UpdatedAt: nowIso()
    });
  }
}

function removeReminderForSale(saleId) {
  var reminders = getRemindersSheet();
  var existing = sheetToObjects(reminders).find(function (r) { return reminderKind(r) === 'refill' && reminderSaleId(r) === String(saleId); });
  if (!existing) return;
  var rowIndex = findRowIndexById(reminders, existing.ID);
  if (rowIndex !== -1) reminders.deleteRow(rowIndex);
}

function sanitizeReminder(r) {
  var kind = reminderKind(r);
  var urgency;
  if (kind === 'renewal') {
    // Countdown to the end of the monthly package.
    var end = dateKey(r.EndDate);
    var left = isDateKey(end) ? keyToDayNumber(end) - keyToDayNumber(todayKey()) : null;
    urgency = { products: [], daysRemaining: left, overdue: left !== null && left < 0 };
  } else {
    var products = [];
    try { products = JSON.parse(r.Products || '[]'); } catch (e) { products = []; }
    urgency = computeReminderUrgency(products, r.SaleDate);
  }

  return {
    ID: r.ID,
    Kind: kind,
    SaleType: String(r.SaleType || 'pharmacy'),
    SaleID: reminderSaleId(r),
    Detail: String(r.Detail || ''),
    EndDate: dateKey(r.EndDate),
    DueDate: dateKey(r.DueDate),
    IsDue: kind === 'renewal' ? !!dateKey(r.DueDate) && dateKey(r.DueDate) <= todayKey() : true,
    PharmacySaleID: r.PharmacySaleID,
    AgentEmail: r.AgentEmail,
    AgentName: r.AgentName,
    Reassigned: isActive(r.Reassigned),
    CustomerName: r.CustomerName,
    Contact: r.Contact,
    Products: urgency.products,
    DaysRemaining: urgency.daysRemaining,
    Overdue: urgency.overdue,
    Status: r.Status,
    ResolutionReason: r.ResolutionReason,
    AttemptCount: Number(r.AttemptCount) || 0,
    NeedsAttention: r.Status === 'Active' && (Number(r.AttemptCount) || 0) > 0 &&
      r.LastAttemptDate && (Date.now() - new Date(r.LastAttemptDate).getTime()) >= REMINDER_ATTEMPT_ESCALATE_DAYS * 24 * 60 * 60 * 1000,
    LastAttemptDate: isoString(r.LastAttemptDate),
    CreatedAt: isoString(r.CreatedAt),
    SaleDate: dateKey(r.SaleDate)
  };
}

function svc_listReminders(session, includeResolved) {
  var rows = sheetToObjects(getRemindersSheet());
  if (session.role === 'agent') {
    rows = rows.filter(function (r) { return String(r.AgentEmail).toLowerCase() === String(session.email).toLowerCase(); });
  }
  if (!includeResolved) {
    rows = rows.filter(function (r) { return r.Status === 'Active'; });
  }
  var sanitized = rows.map(sanitizeReminder);
  sanitized.sort(function (a, b) {
    if (a.Overdue !== b.Overdue) return a.Overdue ? -1 : 1;
    return a.DaysRemaining - b.DaysRemaining;
  });
  return sanitized;
}

function svc_markContacted(session, id, outcome) {
  var sheet = getRemindersSheet();
  var rows = sheetToObjects(sheet);
  var existing = rows.find(function (r) { return String(r.ID) === String(id); });
  if (!existing) throw new Error('Reminder not found.');

  var isOwner = String(existing.AgentEmail).toLowerCase() === String(session.email).toLowerCase();
  if (session.role === 'agent' && !isOwner) {
    throw new ForbiddenError('You can only update your own reminders.');
  }

  if (['not_interested', 'could_not_connect'].indexOf(outcome) === -1) {
    throw new Error('Invalid outcome.');
  }

  var patch = {
    AttemptCount: (Number(existing.AttemptCount) || 0) + 1,
    LastAttemptDate: nowIso(),
    UpdatedAt: nowIso()
  };
  if (outcome === 'not_interested') {
    patch.Status = 'Resolved';
    patch.ResolutionReason = 'NotInterested';
  } else {
    patch.ResolutionReason = 'CouldNotConnect';
  }

  var updated = updateObjectById(sheet, id, patch);
  audit(session, 'mark_contacted', 'Reminder', id, auditDiff(existing, patch));
  return sanitizeReminder(updated);
}

function svc_reassignReminder(session, id, agentEmail) {
  requireRole(session, TEAM_ROLES);
  var sheet = getRemindersSheet();

  var agent = sheetToObjects(getSheetByName('Users')).find(function (u) {
    return String(u.Email).toLowerCase() === cleanEmail(agentEmail) && u.Role === 'agent' && isActive(u.Active);
  });
  if (!agent) throw new Error('Target agent not found.');

  var existing = sheetToObjects(sheet).find(function (r) { return String(r.ID) === String(id); });
  if (!existing) throw new Error('Reminder not found.');
  var patch = {
    AgentEmail: agent.Email,
    AgentName: agent.Name,
    Reassigned: true,
    UpdatedAt: nowIso()
  };
  var updated = updateObjectById(sheet, id, patch);
  audit(session, 'reassign', 'Reminder', id, auditDiff(existing, patch));
  return sanitizeReminder(updated);
}


// ---- SalesService.gs ----
// SalesService.gs — Medpass & Pharmacy records, from first enquiry to sale.
//
// One row per customer enquiry. A row starts life as a Pending lead (with
// temperature, channel, follow-up date…), and becomes a sale when it's marked
// Completed with payment proof — or Cancelled with a lost reason. Both tabs
// share the same columns, so one set of functions serves both, keyed by
// type ('medpass' | 'pharmacy').
//
// Every rule lives here, not just in the browser:
//  - agents only ever see / touch rows where AgentEmail is their own;
//  - a Completed sale is locked for agents except its medicines and notes;
//  - Completed needs payment method, both screenshots, a UTR for UPI and an
//    amount above zero;
//  - one open (Pending) record per patient per module, and every record of a
//    patient goes to the patient's owner agent (see Patients.gs);
//  - only admins delete, and only with a reason.

// The modules themselves (and SALE_TYPES) are defined in Modules.gs.
var SALE_STATUSES = ['Pending', 'Completed', 'Cancelled'];
var PRICE_TYPES = ['Full Price', 'Discounted', 'Converted From OP'];
var PAYMENT_METHODS = ['UPI', 'Cash', 'Card', 'Net Banking'];
var ATTACHED = 'attached'; // what the browser sees instead of a Drive link

var SALE_HEADERS = ['ID', 'Date', 'AgentEmail', 'AgentName', 'CustomerName', 'Contact', 'ContactKey', 'Detail',
  'Products', 'Amount', 'Status', 'PriceType', 'PaymentMethod', 'UTR', 'BillScreenshotUrl', 'PaymentScreenshotUrl',
  'Notes', 'Temperature', 'Direction', 'Channel', 'HeardFrom', 'Consent', 'DoNotCall', 'LostReason', 'NextFollowUp',
  'CreatedAt', 'UpdatedAt', 'PatientID'];

function saleSheetName(type) {
  return getModule(type).label;
}

function getSaleSheet(type) {
  return getOrCreateSheet(saleSheetName(type), moduleHeaders(type));
}

function saleEntity(type) { return getModule(type).label + 'Sale'; }

// Agents can only see/touch their own rows.
function canAccessSale(session, sale) {
  if (session.role !== 'agent') return true;
  return String(sale.AgentEmail).toLowerCase() === String(session.email).toLowerCase();
}

function followUpStatusOf(row) {
  if (row.Status !== 'Pending') return '';
  var key = dateKey(row.NextFollowUp);
  if (!isDateKey(key)) return '';
  var diff = keyToDayNumber(key) - keyToDayNumber(todayKey());
  return diff < 0 ? 'overdue' : diff === 0 ? 'today' : 'upcoming';
}

// A sale row as the browser should see it. Drive links never leave the
// server — the browser gets "attached" and fetches images via getAttachment.
// `extras` (from recordExtras in Patients.gs) adds the patient fields.
function saleForClient(row, activities, extras, type) {
  if (!row) return row;
  var acts = activities || [];
  var ex = extras || { PatientID: String(row.PatientID || ''), AlsoIn: [], HouseholdSize: 1 };
  var own = type && moduleHook(type, 'clientFields');
  return Object.assign({
    PatientID: ex.PatientID,
    AlsoIn: ex.AlsoIn,
    HouseholdSize: ex.HouseholdSize,
    ID: String(row.ID),
    Date: dateKey(row.Date),
    AgentEmail: String(row.AgentEmail || ''),
    AgentName: String(row.AgentName || ''),
    CustomerName: String(row.CustomerName || ''),
    Contact: String(row.Contact || ''),
    ContactKey: String(row.ContactKey || phoneKey(row.Contact)),
    Detail: String(row.Detail || ''),
    Products: String(row.Products || ''),
    Amount: Number(row.Amount) || 0,
    Status: SALE_STATUSES.indexOf(row.Status) !== -1 ? row.Status : 'Pending',
    PriceType: String(row.PriceType || ''),
    PaymentMethod: String(row.PaymentMethod || ''),
    UTR: String(row.UTR || ''),
    BillScreenshotUrl: row.BillScreenshotUrl ? ATTACHED : '',
    PaymentScreenshotUrl: row.PaymentScreenshotUrl ? ATTACHED : '',
    Notes: String(row.Notes || ''),
    CreatedAt: isoString(row.CreatedAt),
    Temperature: LEAD_TEMPERATURES.indexOf(row.Temperature) !== -1 ? row.Temperature : 'Warm',
    Direction: LEAD_DIRECTIONS.indexOf(row.Direction) !== -1 ? row.Direction : 'Inbound',
    Channel: String(row.Channel || ''),
    HeardFrom: String(row.HeardFrom || ''),
    Consent: row.Consent === '' || row.Consent === undefined ? true : asBool(row.Consent),
    DoNotCall: asBool(row.DoNotCall),
    LostReason: String(row.LostReason || ''),
    NextFollowUp: dateKey(row.NextFollowUp),
    FollowUpStatus: followUpStatusOf(row),
    AttemptCount: acts.filter(function (a) { return a.Direction === 'Outgoing'; }).length
  }, own ? own(row) : {});
}

function findSaleRow(type, id) {
  return sheetToObjects(getSaleSheet(type)).find(function (r) { return String(r.ID) === String(id); }) || null;
}

function requireSale(session, type, id) {
  var row = findSaleRow(type, id);
  if (!row || !canAccessSale(session, row)) throw new Error('Record not found.');
  return row;
}

// ===== Reads =====
// A record with fresh activities and patient fields (used after every write).
function fullSaleForClient(type, row) {
  return saleForClient(row, activitiesForSale(row.ID), recordExtras(loadPatientWorld())(type, row), type);
}

function svc_listSales(session, type) {
  getModule(type);
  var world = loadPatientWorld();
  var extras = recordExtras(world);
  var rows = world.records.filter(function (x) { return x.type === type && canAccessSale(session, x.row); });
  var acts = activitiesBySale();
  var list = rows.map(function (x) { return saleForClient(x.row, acts[String(x.row.ID)], extras(type, x.row), type); });
  var rank = { overdue: 0, today: 1, upcoming: 2, '': 3 };
  list.sort(function (a, b) {
    if (a.Status === 'Pending' && b.Status === 'Pending' && rank[a.FollowUpStatus] !== rank[b.FollowUpStatus]) {
      return rank[a.FollowUpStatus] - rank[b.FollowUpStatus];
    }
    return new Date(b.CreatedAt) - new Date(a.CreatedAt);
  });
  return list;
}

function saleDetail(session, type, row) {
  var acts = activitiesForSale(row.ID);
  return {
    sale: saleForClient(row, acts, recordExtras(loadPatientWorld())(type, row), type),
    activities: acts.map(activityForClient),
    auditHistory: auditHistoryFor([row.ID])
  };
}

function svc_getSale(session, type, id) {
  return saleDetail(session, type, requireSale(session, type, id));
}

function svc_getAuditHistory(session, type, id) {
  var row = requireSale(session, type, id);
  return auditHistoryFor([row.ID]);
}

/// Used by the form as soon as a phone number is typed: who handles this
// number, who is already on it, and which modules have open records.
// Managers/admins and the owner see the people on the number; any other
// agent learns only that it is handled and by whom — never names or records.
function svc_checkContact(session, contact, exceptId) {
  var key = phoneKey(contact);
  if (!key) return { activeSales: [], pastCompletedCount: 0, owner: null, owners: [], people: [], othersCount: 0, conflict: false };
  var world = loadPatientWorld();
  ensureHousehold(world, key); // in memory only: a read never writes
  var except = String(exceptId || '');
  var active = [];
  var completed = 0;
  householdRecords(world, key).forEach(function (x) {
    var s = x.row;
    if (String(s.ID) === except) return;
    if (s.Status === 'Completed') completed++;
    if (s.Status === 'Pending') {
      var mine = canAccessSale(session, s);
      active.push({
        ID: mine ? String(s.ID) : '',
        CustomerName: mine ? String(s.CustomerName) : 'another customer record',
        AgentName: String(s.AgentName),
        Module: SALE_TYPES[x.type],
        Mine: mine
      });
    }
  });

  var me = lowerEmail(session.email);
  var privileged = session.role !== 'agent';
  var people = [];
  var others = 0;
  householdOf(world, key).forEach(function (p) {
    var o = ownerOfPatient(world, p);
    var mine = !!o && lowerEmail(o.email) === me;
    if (!privileged && !mine) { others++; return; }
    var open = {};
    patientRecords(world, p).forEach(function (x) {
      if (x.row.Status === 'Pending' && String(x.row.ID) !== except) open[x.type] = true;
    });
    people.push({
      // People found only from old rows aren't saved yet; the form then sends
      // the name, which matches them just the same.
      ID: world.added.indexOf(p) === -1 ? String(p.ID) : '',
      Name: String(p.Name),
      OwnerName: o ? o.name : '',
      OwnerEmail: o ? o.email : '',
      Mine: mine,
      Conflict: p.OwnerStatus === PATIENT_CONFLICT,
      OpenModules: moduleIds().filter(function (t) { return open[t]; }).map(function (t) { return SALE_TYPES[t]; })
    });
  });
  var owners = householdOwners(world, key);
  return {
    activeSales: active,
    pastCompletedCount: completed,
    owner: owners.length === 1 ? { name: owners[0].name, email: privileged ? owners[0].email : '', isMe: lowerEmail(owners[0].email) === me } : null,
    owners: privileged ? owners : [],
    people: people,
    othersCount: others,
    conflict: householdOf(world, key).some(function (p) { return p.OwnerStatus === PATIENT_CONFLICT; })
  };
}

// ===== Validation helpers =====
function validateCompletion(next, type) {
  if (next.Status !== 'Completed') return;
  var mod = getModule(type);
  if (mod.needsProducts) {
    var lines = [];
    try { lines = JSON.parse(next.Products || '[]'); } catch (e) { lines = []; }
    if (!lines.length) throw new Error('Add the medicines before marking this ' + mod.label + ' sale as Completed.');
  }
  if (!next.PaymentMethod) throw new Error('Payment method is required to mark this sale as Completed.');
  if (!next.hasBill) throw new Error('A bill screenshot is required to mark this sale as Completed.');
  if (!next.hasPayment) throw new Error('A payment screenshot is required to mark this sale as Completed.');
  if (next.PaymentMethod === 'UPI' && !next.UTR) throw new Error('UTR number is required for UPI payments.');
  // Module rules first: they explain what's missing (members, services…).
  var hook = moduleHook(type, 'validateCompletion');
  if (hook) hook(next);
  if (!(Number(next.Amount) > 0)) throw new Error('Enter the sale amount before marking it Completed.');
}

// Is a stored cell the same as a newly computed value? (Numbers come back
// from the sheet as numbers, blanks as '', booleans as booleans.)
function sameCellValue(before, after) {
  if (typeof after === 'number') return before !== '' && before !== null && before !== undefined && Number(before) === after;
  if (typeof after === 'boolean') return asBool(before) === after;
  if (Object.prototype.toString.call(before) === '[object Date]') return dateKey(before) === String(after);
  return String(before === undefined || before === null ? '' : before) === String(after);
}

function cleanAmount(value) {
  if (value === undefined || value === null || value === '') return 0;
  var n = Number(value);
  if (isNaN(n) || n < 0 || n > 1e8) throw new Error('Amount must be a number between 0 and 10,00,00,000.');
  return Math.round(n * 100) / 100;
}

function isDataUrl(v) { return typeof v === 'string' && v.indexOf('data:') === 0; }

// What the incoming screenshot field means for this save:
//   data:…            → a new upload
//   'attached' / same → keep what's there
//   ''                → remove it
function attachmentIntent(incoming, existingUrl) {
  if (incoming === undefined || incoming === null) return { kind: 'keep', present: !!existingUrl };
  if (isDataUrl(incoming)) return { kind: 'upload', present: true };
  if (incoming === ATTACHED || (existingUrl && incoming === existingUrl)) return { kind: 'keep', present: !!existingUrl };
  if (incoming === '') return { kind: existingUrl ? 'clear' : 'keep', present: false };
  throw new Error('Screenshots must be uploaded as image files.');
}

// Lead fields shared by create and update. Only keys present in `data` are
// returned (all of them on create).
function cleanLeadFields(data, isCreate) {
  var lists = getLists();
  var out = {};
  if (isCreate || data.temperature !== undefined) {
    out.Temperature = String(data.temperature || 'Warm');
    requireOneOf(out.Temperature, LEAD_TEMPERATURES, 'Temperature');
  }
  if (isCreate || data.direction !== undefined) {
    out.Direction = String(data.direction || 'Inbound');
    requireOneOf(out.Direction, LEAD_DIRECTIONS, 'Direction');
  }
  if (isCreate || data.channel !== undefined) {
    out.Channel = cleanText(data.channel || lists.channels[0], 50);
    requireOneOf(out.Channel, lists.channels, 'Channel');
  }
  if (isCreate || data.heardFrom !== undefined) {
    out.HeardFrom = cleanText(data.heardFrom, 50);
    if (out.HeardFrom) requireOneOf(out.HeardFrom, lists.heardFrom, 'How they heard about us');
  }
  if (isCreate || data.consent !== undefined) out.Consent = data.consent === undefined ? true : (data.consent === true || data.consent === 'true');
  if (isCreate || data.doNotCall !== undefined) out.DoNotCall = data.doNotCall === true || data.doNotCall === 'true';
  if (isCreate || data.nextFollowUp !== undefined) out.NextFollowUp = optionalDateKey(data.nextFollowUp, 'Next follow-up');
  return out;
}

var SALE_FIELD_LABELS = {
  Date: 'Date', CustomerName: 'Customer Name', Contact: 'Contact', Detail: 'Details', Amount: 'Amount',
  Status: 'Status', PriceType: 'Price Type', PaymentMethod: 'Payment Method', UTR: 'UTR', Notes: 'Notes',
  Temperature: 'Temperature', Direction: 'Direction', Channel: 'Channel', HeardFrom: 'Heard From',
  Consent: 'Consent', DoNotCall: 'Do Not Call', LostReason: 'Lost Reason', NextFollowUp: 'Next Follow-up',
  AgentName: 'Assigned Agent'
};

function displayValue(field, v) {
  if (v === undefined || v === null || v === '') return '—';
  if (field === 'Amount') return '₹' + Number(v).toLocaleString('en-IN');
  if (field === 'Consent' || field === 'DoNotCall') return asBool(v) ? 'Yes' : 'No';
  if (field === 'Date' || field === 'NextFollowUp') return dateKey(v) || '—';
  return String(v);
}

// Readable [{ field, from, to }] for the history panel.
function saleChanges(before, patch) {
  var out = [];
  Object.keys(SALE_FIELD_LABELS).forEach(function (k) {
    if (patch[k] === undefined) return;
    if (k === 'Detail' && patch.Products !== undefined) return; // shown as medications below
    var from = displayValue(k, before ? before[k] : '');
    var to = displayValue(k, patch[k]);
    if (from !== to) out.push({ field: SALE_FIELD_LABELS[k], from: from, to: to });
  });
  if (patch.Products !== undefined && (!before || String(before.Products || '') !== String(patch.Products))) {
    out.push({ field: 'Prescribed Medications', from: (before && before.Detail) || '—', to: patch.Detail || '—' });
  }
  if (patch.BillScreenshotUrl !== undefined && (!before || before.BillScreenshotUrl !== patch.BillScreenshotUrl)) {
    out.push({ field: 'Bill Proof', from: before && before.BillScreenshotUrl ? 'Attached' : 'None', to: patch.BillScreenshotUrl ? 'Updated' : 'Removed' });
  }
  if (patch.PaymentScreenshotUrl !== undefined && (!before || before.PaymentScreenshotUrl !== patch.PaymentScreenshotUrl)) {
    out.push({ field: 'Payment Proof', from: before && before.PaymentScreenshotUrl ? 'Attached' : 'None', to: patch.PaymentScreenshotUrl ? 'Updated' : 'Removed' });
  }
  return out;
}

function resolveAssignee(session, agentEmail) {
  if (!agentEmail || session.role === 'agent') return { email: session.email, name: session.name };
  var email = cleanEmail(agentEmail);
  if (email === String(session.email).toLowerCase()) return { email: session.email, name: session.name };
  var user = sheetToObjects(getSheetByName('Users')).find(function (u) {
    return String(u.Email).toLowerCase() === email && isActive(u.Active);
  });
  if (!user) throw new Error('Assigned agent not found or inactive.');
  return { email: user.Email, name: user.Name };
}

// ===== Create =====
function svc_createSale(session, type, data) {
  var mod = getModule(type);
  var sheet = getSaleSheet(type);
  var customerName = cleanText(data.customerName, 120);
  if (!customerName) throw new Error('Customer name is required.');
  var contact = cleanText(data.contact, 30);
  var contactKey = phoneKey(contact);
  if (!contactKey) throw new Error('A valid phone number is required.');

  var status = String(data.status || 'Pending');
  requireOneOf(status, SALE_STATUSES, 'Status');

  // Whose patient is this? A known patient (or a new person on a known
  // number) goes to the agent who already handles them.
  var world = loadPatientWorld();
  var link = resolvePatientOwner(world, {
    contactKey: contactKey, contact: contact, name: customerName,
    patientId: cleanText(data.patientId, 60), requested: resolveAssignee(session, data.agentEmail)
  });
  if (status === 'Pending') {
    var dup = findOpenRecordForPatient(world, type, link.patient);
    if (dup) throw new Error(openRecordMessage(session, type, dup, 'Open that record instead of creating a new one.'));
  }
  var date = data.date ? optionalDateKey(data.date, 'Date') : todayKey();
  var amount = cleanAmount(data.amount);
  var paymentMethod = cleanText(data.paymentMethod, 30);
  if (paymentMethod) requireOneOf(paymentMethod, PAYMENT_METHODS, 'Payment method');
  var utr = cleanText(data.utr, 40);
  var priceType = cleanText(data.priceType, 30);
  if (mod.priceTypes) requireOneOf(priceType, PRICE_TYPES, 'Price type');
  else priceType = '';

  var detail = cleanText(data.detail, MAX_LONG_TEXT);
  var products = [];
  if (mod.products) {
    products = validateProducts(data.products === undefined ? [] : data.products, status !== 'Completed');
    detail = summarizeProducts(products);
  }

  var lead = cleanLeadFields(data, true);
  if (lead.Direction === 'Outbound') lead.HeardFrom = '';
  var lostReason = '';
  if (status === 'Cancelled') {
    lostReason = cleanText(data.lostReason, 50);
    requireOneOf(lostReason, getLists().lostReasons, 'Lost reason');
    lead.NextFollowUp = '';
  }

  var bill = attachmentIntent(data.billScreenshot, '');
  var pay = attachmentIntent(data.paymentScreenshot, '');
  // Module rules, e.g. Medpass works out its own price from the members.
  var prep = moduleHook(type, 'prepareSave');
  var computed = prep ? prep(session, { isCreate: true, data: data, existing: null,
    next: { ID: '', Status: status, PriceType: priceType, Date: date, ContactKey: contactKey, CustomerName: customerName } }) : null;
  var computedFields = (computed && computed.fields) || {};
  if (computedFields.Amount !== undefined) amount = computedFields.Amount;
  validateCompletion(Object.assign({ Status: status, PaymentMethod: paymentMethod, UTR: utr, Amount: amount, hasBill: bill.present, hasPayment: pay.present,
    Products: JSON.stringify(products), PriceType: priceType }, computedFields), type);

  var owner = link.owner;
  var id = newId();
  var now = nowIso();
  var sale = {
    ID: id,
    Date: date,
    AgentEmail: owner.email,
    AgentName: owner.name,
    CustomerName: customerName,
    Contact: contact,
    ContactKey: contactKey,
    Detail: detail,
    Products: mod.products ? JSON.stringify(products) : '',
    Amount: amount,
    Status: status,
    PriceType: priceType,
    PaymentMethod: paymentMethod,
    UTR: utr,
    BillScreenshotUrl: bill.kind === 'upload' ? saveAttachmentFromDataUrl(data.billScreenshot, type + '_' + id + '_bill') : '',
    PaymentScreenshotUrl: pay.kind === 'upload' ? saveAttachmentFromDataUrl(data.paymentScreenshot, type + '_' + id + '_payment') : '',
    Notes: cleanText(data.notes, MAX_LONG_TEXT),
    Temperature: lead.Temperature,
    Direction: lead.Direction,
    Channel: lead.Channel,
    HeardFrom: lead.HeardFrom,
    Consent: lead.Consent,
    DoNotCall: lead.DoNotCall,
    LostReason: lostReason,
    NextFollowUp: lead.NextFollowUp,
    CreatedAt: now,
    UpdatedAt: now,
    PatientID: link.patient.ID
  };
  Object.keys(computedFields).forEach(function (k) { sale[k] = computedFields[k]; });
  savePatientChanges(world);
  appendObject(sheet, sale);
  afterSaleSaved(type, sale);
  audit(session, status === 'Completed' ? 'complete' : 'create', saleEntity(type), id, saleChanges(null, sale),
    'Created ' + SALE_TYPES[type] + ' record for ' + customerName + ' (' + status + ')' +
    (link.notice && !link.conflict ? '; assigned to ' + owner.name + ', who handles this patient' : ''));
  var notice = [link.notice].concat((computed && computed.warnings) || []).filter(Boolean).join(' ');
  return { sale: fullSaleForClient(type, sale), notice: notice };
}

// ===== Update =====
// Fields an agent may still change once their sale is Completed.
var AGENT_COMPLETED_EDITABLE = ['Products', 'Detail', 'Notes'];

function svc_updateSale(session, type, id, data) {
  var mod = getModule(type);
  var sheet = getSaleSheet(type);
  var existing = requireSale(session, type, id);
  var patch = {};

  if (data.customerName !== undefined) {
    patch.CustomerName = cleanText(data.customerName, 120);
    if (!patch.CustomerName) throw new Error('Customer name is required.');
  }
  if (data.contact !== undefined) {
    patch.Contact = cleanText(data.contact, 30);
    patch.ContactKey = phoneKey(patch.Contact);
    if (!patch.ContactKey) throw new Error('A valid phone number is required.');
  }
  if (data.date !== undefined) {
    patch.Date = optionalDateKey(data.date, 'Date');
    if (!patch.Date) throw new Error('Date is required.');
  }
  if (data.amount !== undefined) patch.Amount = cleanAmount(data.amount);
  if (data.status !== undefined) { patch.Status = String(data.status); requireOneOf(patch.Status, SALE_STATUSES, 'Status'); }
  if (data.paymentMethod !== undefined) {
    patch.PaymentMethod = cleanText(data.paymentMethod, 30);
    if (patch.PaymentMethod) requireOneOf(patch.PaymentMethod, PAYMENT_METHODS, 'Payment method');
  }
  if (data.utr !== undefined) patch.UTR = cleanText(data.utr, 40);
  if (data.notes !== undefined) patch.Notes = cleanText(data.notes, MAX_LONG_TEXT);
  if (mod.priceTypes && data.priceType !== undefined) {
    patch.PriceType = cleanText(data.priceType, 30);
    requireOneOf(patch.PriceType, PRICE_TYPES, 'Price type');
  }
  if (!mod.products && data.detail !== undefined) patch.Detail = cleanText(data.detail, MAX_LONG_TEXT);
  if (mod.products && data.products !== undefined) {
    var products = validateProducts(data.products, String(data.status || existing.Status) !== 'Completed');
    patch.Products = JSON.stringify(products);
    patch.Detail = summarizeProducts(products);
  }
  var lead = cleanLeadFields(data, false);
  Object.keys(lead).forEach(function (k) { patch[k] = lead[k]; });

  // Drop fields that aren't actually changing, so the agent lock and the
  // audit log only see real edits (the form sends every field on save).
  Object.keys(patch).forEach(function (k) {
    var before = existing[k];
    var same;
    if (k === 'Date' || k === 'NextFollowUp') same = dateKey(before) === patch[k];
    else if (k === 'Amount') same = Number(before || 0) === Number(patch[k]);
    else if (k === 'Consent') same = (before === '' || before === undefined ? true : asBool(before)) === patch[k];
    else if (k === 'DoNotCall') same = asBool(before) === patch[k];
    else same = String(before === undefined || before === null ? '' : before) === String(patch[k]);
    if (same) delete patch[k];
  });

  // Module rules, e.g. Medpass recomputes its price from members/discount.
  // Computed fields that end up the same as before are not changes.
  var warnings = [];
  var prep = moduleHook(type, 'prepareSave');
  if (prep) {
    var draft = {};
    moduleHeaders(type).forEach(function (h) { draft[h] = patch[h] !== undefined ? patch[h] : existing[h]; });
    var computed = prep(session, { isCreate: false, data: data, existing: existing, next: draft }) || {};
    Object.keys(computed.fields || {}).forEach(function (k) {
      if (sameCellValue(existing[k], computed.fields[k])) delete patch[k];
      else patch[k] = computed.fields[k];
    });
    warnings = computed.warnings || [];
  }

  var bill = attachmentIntent(data.billScreenshot, existing.BillScreenshotUrl);
  var pay = attachmentIntent(data.paymentScreenshot, existing.PaymentScreenshotUrl);

  if (existing.Status === 'Completed' && session.role === 'agent') {
    var editable = AGENT_COMPLETED_EDITABLE.concat(mod.agentEditableWhenCompleted || []);
    var blocked = Object.keys(patch).filter(function (k) { return editable.indexOf(k) === -1; });
    if (blocked.length || bill.kind !== 'keep' || pay.kind !== 'keep') {
      throw new ForbiddenError('This sale is Completed and locked. You can still update its medicines and notes; ask a manager for anything else.');
    }
  }

  var next = {};
  moduleHeaders(type).forEach(function (h) { next[h] = patch[h] !== undefined ? patch[h] : existing[h]; });
  if (next.Direction === 'Outbound' && next.HeardFrom) { patch.HeardFrom = ''; next.HeardFrom = ''; }

  // Status transitions.
  var action = 'update';
  var summary = '';
  if (patch.Status !== undefined) {
    if (existing.Status === 'Cancelled' && next.Status === 'Pending') {
      action = 'reopen';
      if (data.temperature === undefined || patch.Temperature === undefined) { patch.Temperature = 'Hot'; next.Temperature = 'Hot'; }
      summary = cleanText(data.reopenReason, 300) || 'Record reopened to Pending.';
    } else if (next.Status === 'Cancelled') {
      action = 'cancel';
      var reason = cleanText(data.lostReason !== undefined ? data.lostReason : existing.LostReason, 50);
      requireOneOf(reason, getLists().lostReasons, 'Lost reason');
      patch.LostReason = reason; next.LostReason = reason;
      patch.NextFollowUp = ''; next.NextFollowUp = '';
      summary = 'Marked Cancelled / Lost (reason: ' + reason + ')';
    } else if (next.Status === 'Completed') {
      action = 'complete';
      summary = 'Sale completed (' + next.PaymentMethod + ', ' + displayValue('Amount', next.Amount) + ')';
    } else {
      action = 'status_change';
      summary = 'Status changed to ' + next.Status;
    }
    if (next.Status !== 'Cancelled' && existing.LostReason) { patch.LostReason = ''; next.LostReason = ''; }
  } else if (next.Status === 'Cancelled' && data.lostReason !== undefined && cleanText(data.lostReason, 50) !== String(existing.LostReason || '')) {
    patch.LostReason = cleanText(data.lostReason, 50);
    requireOneOf(patch.LostReason, getLists().lostReasons, 'Lost reason');
    next.LostReason = patch.LostReason;
  }

  // Patient and owner. A new phone number or name may make this someone
  // else's patient; going back to Pending must follow the current owner; and
  // a patient has at most one open record per module.
  var world = null;
  var notice = '';
  var relink = patch.ContactKey !== undefined || patch.CustomerName !== undefined;
  var reopening = next.Status === 'Pending' && patch.Status !== undefined && existing.Status !== 'Pending';
  if (relink || reopening) {
    world = loadPatientWorld();
    var key = String(next.ContactKey || phoneKey(next.Contact));
    var patient = null;
    if (relink) {
      ensureHousehold(world, recordContactKey(existing));
      var current = recordPatient(world, existing);
      var shared = current && patientRecords(world, current).some(function (x) { return String(x.row.ID) !== String(existing.ID); });
      if (current && String(current.ContactKey) === key && !shared && !findPerson(world, key, next.CustomerName)) {
        // Only this record uses the patient: a spelling fix, not a new person.
        changePatient(world, current, { Name: cleanText(next.CustomerName, 120), NameKey: nameKey(next.CustomerName) });
        patient = current;
      } else {
        var link = resolvePatientOwner(world, {
          contactKey: key, contact: next.Contact, name: next.CustomerName,
          requested: { email: existing.AgentEmail, name: existing.AgentName }
        });
        patient = link.patient;
        if (!link.conflict && lowerEmail(link.owner.email) !== lowerEmail(existing.AgentEmail)) {
          if (session.role === 'agent') {
            throw new ForbiddenError('This number belongs to a patient handled by ' + link.owner.name + '. Ask a manager to move the record.');
          }
          if (next.Status === 'Pending') {
            patch.AgentEmail = link.owner.email; patch.AgentName = link.owner.name;
            next.AgentEmail = link.owner.email; next.AgentName = link.owner.name;
            notice = 'Moved to ' + link.owner.name + ', who handles this patient.';
          }
        }
      }
      if (String(existing.PatientID || '') !== String(patient.ID)) { patch.PatientID = patient.ID; next.PatientID = patient.ID; }
    } else {
      var own = reopenOwnership(session, world, type, existing);
      Object.keys(own).forEach(function (k) { patch[k] = own[k]; next[k] = own[k]; });
      if (own.AgentName) notice = 'Moved to ' + own.AgentName + ', who handles this patient now.';
    }
    if (relink && next.Status === 'Pending') {
      var dup = findOpenRecordForPatient(world, type, patient, existing.ID);
      if (dup) throw new Error(openRecordMessage(session, type, dup, 'Close that one first.'));
    }
  }

  next.hasBill = bill.present;
  next.hasPayment = pay.present;
  validateCompletion(next, type);

  // Validation passed — only now touch Drive.
  if (bill.kind === 'upload') patch.BillScreenshotUrl = saveAttachmentFromDataUrl(data.billScreenshot, type + '_' + existing.ID + '_bill');
  if (bill.kind === 'clear') patch.BillScreenshotUrl = '';
  if (pay.kind === 'upload') patch.PaymentScreenshotUrl = saveAttachmentFromDataUrl(data.paymentScreenshot, type + '_' + existing.ID + '_payment');
  if (pay.kind === 'clear') patch.PaymentScreenshotUrl = '';

  notice = [notice].concat(warnings).filter(Boolean).join(' ');
  if (Object.keys(patch).length === 0) return { sale: fullSaleForClient(type, existing), notice: notice };

  if (world) savePatientChanges(world);
  patch.UpdatedAt = nowIso();
  var updated = updateObjectById(sheet, existing.ID, patch);
  afterSaleSaved(type, updated);
  var changes = saleChanges(existing, patch);
  if (!summary) summary = 'Updated ' + (changes.map(function (c) { return c.field; }).join(', ') || 'details');
  if (notice) summary += ' ' + notice;
  audit(session, action, saleEntity(type), existing.ID, changes, summary);
  return { sale: fullSaleForClient(type, updated), notice: notice };
}

// Customer came back: Cancelled → Pending (Hot, follow up today). Reopening a
// Completed sale undoes revenue and incentives, so only a manager or admin
// may do that, and they must say why. The record follows the patient's
// current owner.
function svc_reopenSale(session, type, id, reason) {
  var sheet = getSaleSheet(type);
  var existing = requireSale(session, type, id);
  var why = cleanText(reason, 300);
  if (existing.Status === 'Pending') throw new Error('This record is already open.');
  if (existing.Status === 'Completed') {
    requireRole(session, TEAM_ROLES);
    if (why.length < 3) throw new Error('Give a reason for reopening a completed sale.');
  }
  var world = loadPatientWorld();
  var own = reopenOwnership(session, world, type, existing);

  var patch = { Status: 'Pending', LostReason: '', Temperature: 'Hot', NextFollowUp: todayKey(), UpdatedAt: nowIso() };
  Object.keys(own).forEach(function (k) { patch[k] = own[k]; });
  // A reopened pass is no longer valid (Medpass).
  if (moduleHeaders(type).indexOf('ValidUntil') !== -1) { patch.ValidFrom = ''; patch.ValidUntil = ''; }
  savePatientChanges(world);
  var updated = updateObjectById(sheet, existing.ID, patch);
  var summary = why || 'Customer came back and is interested. Reopened as a Hot lead.';
  if (own.AgentName) summary += ' Moved to ' + own.AgentName + ', who handles this patient now.';
  addActivity(session, type, existing.ID, { Type: 'Note', Notes: 'Reopened: ' + summary, NextFollowUp: todayKey() });
  afterSaleSaved(type, updated);
  audit(session, 'reopen', saleEntity(type), existing.ID, saleChanges(existing, patch), summary);
  return fullSaleForClient(type, updated);
}

// Reassigning a record reassigns its patient: by default the whole household
// (scope 'household'), or only this person (scope 'person', a split). All of
// their open records in every module move; closed ones keep their agent.
function svc_reassignSale(session, type, id, agentEmail, scope, reason) {
  var result = svc_reassignPatient(session, { type: type, id: id, agentEmail: agentEmail, scope: scope, reason: reason });
  var row = findSaleRow(type, id);
  return { sale: fullSaleForClient(type, row), moved: result.moved, reminders: result.reminders, patients: result.patients };
}

function svc_deleteSale(session, type, id, reason) {
  requireRole(session, ADMIN_ROLES); // hard delete: admins only
  var why = cleanText(reason, 300);
  if (why.length < 3) throw new Error('A reason (at least 3 characters) is required to delete a record.');
  var sheet = getSaleSheet(type);
  var existing = findSaleRow(type, id);
  if (!existing) throw new Error('Record not found.');
  var rowIndex = findRowIndexById(sheet, existing.ID);
  if (rowIndex === -1) throw new Error('Record not found.');
  sheet.deleteRow(rowIndex);
  afterSaleDeleted(type, existing.ID);
  var snapshot = auditDiff(existing, null);
  delete snapshot.BillScreenshotUrl;
  delete snapshot.PaymentScreenshotUrl;
  audit(session, 'delete', saleEntity(type), existing.ID, snapshot,
    'Deleted record for ' + existing.CustomerName + ' (' + existing.Status + '). Reason: ' + why);
  return { deleted: true };
}

// Streams a bill/payment screenshot back through the app after checking
// that the viewer may see this record (agents: only their own).
function svc_getAttachment(session, type, id, kind) {
  var sale = requireSale(session, type, id);
  var url = kind === 'bill' ? sale.BillScreenshotUrl : kind === 'payment' ? sale.PaymentScreenshotUrl : null;
  if (!url) throw new Error('No screenshot attached.');
  return readAttachmentAsDataUrl(url);
}

// ===== Dashboard =====
// Building the summary reads every sheet, so it's cached for two minutes.
// Every successful write through the app changes the "data version" (see
// Code.gs), which changes the cache key — so new sales show up immediately.
var DASHBOARD_CACHE_SECONDS = 120;
var DATA_VERSION_KEY = 'data_version';

function getDataVersion() {
  var cache = CacheService.getScriptCache();
  var v = cache.get(DATA_VERSION_KEY);
  if (!v) {
    v = Utilities.getUuid();
    cache.put(DATA_VERSION_KEY, v, 6 * 60 * 60);
  }
  return v;
}

function bumpDataVersion() {
  CacheService.getScriptCache().put(DATA_VERSION_KEY, Utilities.getUuid(), 6 * 60 * 60);
}

function svc_dashboardSummary(session) {
  var scope = session.role === 'agent' ? 'agent_' + String(session.email).toLowerCase() : 'team';
  var key = 'dash_' + getDataVersion() + '_' + todayKey() + '_' + scope;
  var cache = CacheService.getScriptCache();
  var hit = cache.get(key);
  if (hit) return JSON.parse(hit);

  var summary = computeDashboardSummary(session);
  try { cache.put(key, JSON.stringify(summary), DASHBOARD_CACHE_SECONDS); } catch (e) { /* >100KB: serve uncached */ }
  return summary;
}

// Only Completed sales count toward revenue and incentives; how each module
// pays is in its config (Modules.gs → incentiveForSale). Per-module figures
// are named <module>Count / <module>Amount (e.g. medpassCount).
function computeDashboardSummary(session) {
  var isAgent = session.role === 'agent';
  var all = [];
  moduleIds().forEach(function (type) {
    sheetToObjects(getSaleSheet(type)).forEach(function (r) {
      if (r.ID && canAccessSale(session, r)) all.push({ type: type, row: r });
    });
  });

  var ratesByEmail = {};
  sheetToObjects(getSheetByName('Users')).forEach(function (u) { ratesByEmail[String(u.Email).toLowerCase()] = u; });

  var totals = {};
  moduleIds().forEach(function (type) { totals[type + 'Count'] = 0; totals[type + 'Amount'] = 0; });
  var agents = {};
  function ensureAgent(key, name) {
    if (!agents[key]) {
      agents[key] = { agentName: String(name), agentEmail: key, incentive: 0 };
      moduleIds().forEach(function (type) { agents[key][type + 'Count'] = 0; agents[key][type + 'Amount'] = 0; });
    }
    return agents[key];
  }
  all.forEach(function (x) {
    if (x.row.Status !== 'Completed') return;
    var key = String(x.row.AgentEmail).toLowerCase();
    var amount = Number(x.row.Amount) || 0;
    var a = ensureAgent(key, x.row.AgentName);
    a[x.type + 'Count'] += 1;
    a[x.type + 'Amount'] += amount;
    a.incentive += incentiveForSale(getModule(x.type), x.row, ratesByEmail[key]);
    totals[x.type + 'Count'] += 1;
    totals[x.type + 'Amount'] += amount;
  });
  var agentsArray = Object.keys(agents).map(function (k) {
    var a = agents[k];
    a.incentive = Math.round(a.incentive * 100) / 100;
    if (isAgent) delete a.incentive; // incentive figures are manager/admin-only
    return a;
  });

  var counts = { Completed: 0, Pending: 0, Cancelled: 0 };
  all.forEach(function (x) { if (counts[x.row.Status] !== undefined) counts[x.row.Status]++; });
  var total = all.length;

  var medMap = {};
  all.forEach(function (x) {
    if (!getModule(x.type).products) return;
    var s = x.row;
    var prods = [];
    try { prods = JSON.parse(s.Products || '[]'); } catch (e) { prods = []; }
    prods.forEach(function (p) {
      var name = String(p.name || '').trim();
      if (!name) return;
      var k = name.toLowerCase();
      if (!medMap[k]) medMap[k] = { name: name, prescriptions: 0, totalUnits: 0 };
      medMap[k].prescriptions += 1;
      medMap[k].totalUnits += Number(p.quantity) || 0;
    });
  });
  var topMedications = Object.keys(medMap).map(function (k) { return medMap[k]; })
    .sort(function (a, b) { return b.prescriptions - a.prescriptions || b.totalUnits - a.totalUnits; }).slice(0, 6);

  var payMap = {};
  all.forEach(function (x) {
    if (x.row.Status !== 'Completed') return;
    var m = String(x.row.PaymentMethod || 'Other');
    if (!payMap[m]) payMap[m] = { method: m, count: 0, amount: 0 };
    payMap[m].count += 1;
    payMap[m].amount += Number(x.row.Amount) || 0;
  });
  var paymentBreakdown = Object.keys(payMap).map(function (k) { return payMap[k]; }).sort(function (a, b) { return b.count - a.count; });

  var urgentFollowUps = all.filter(function (x) { return x.row.Status === 'Pending' && isDateKey(dateKey(x.row.NextFollowUp)); })
    .map(function (x) {
      var s = x.row;
      return {
        id: String(s.ID), type: x.type, customerName: String(s.CustomerName), contact: String(s.Contact),
        detail: String(s.Detail || ''), temperature: String(s.Temperature || 'Warm'), amount: Number(s.Amount) || 0,
        agentName: String(s.AgentName), nextFollowUp: dateKey(s.NextFollowUp), followUpStatus: followUpStatusOf(s),
        notes: String(s.Notes || '').slice(0, 200)
      };
    })
    .sort(function (a, b) { return a.nextFollowUp < b.nextFollowUp ? -1 : a.nextFollowUp > b.nextFollowUp ? 1 : 0; })
    .slice(0, 5);

  // Recent activity and history: only for records this person can see.
  var visibleIds = {};
  all.forEach(function (x) { visibleIds[String(x.row.ID)] = true; });
  var recentActivities = sheetToObjects(getActivitiesSheet())
    .filter(function (a) { return visibleIds[String(a.SaleID)]; })
    .map(activityForClient)
    .sort(function (a, b) { return new Date(b.Date) - new Date(a.Date); })
    .slice(0, 8);
  var recentAudits = auditHistoryFor(Object.keys(visibleIds), 8);

  // Monthly target: this calendar month's completed revenue (India time).
  var monthPrefix = todayKey().slice(0, 7);
  var monthRevenue = 0;
  all.forEach(function (x) {
    if (x.row.Status === 'Completed' && dateKey(x.row.Date).slice(0, 7) === monthPrefix) monthRevenue += Number(x.row.Amount) || 0;
  });
  var target = getMonthlyTarget();

  // Widget data (Phase 4). Same visibility as everything above: agents only
  // ever get their own records and reminders; team-only parts are omitted.
  var temperature = { Hot: 0, Warm: 0, Cold: 0 };
  all.forEach(function (x) {
    if (x.row.Status !== 'Pending') return;
    var t = LEAD_TEMPERATURES.indexOf(x.row.Temperature) !== -1 ? x.row.Temperature : 'Warm';
    temperature[t]++;
  });
  var modulesList = moduleIds().map(function (t) {
    return { id: t, label: SALE_TYPES[t], count: totals[t + 'Count'] || 0, amount: totals[t + 'Amount'] || 0 };
  });
  var remindersDue = svc_listReminders(session, false).filter(function (r) { return r.IsDue; }).slice(0, 6).map(function (r) {
    return { id: String(r.ID), kind: r.Kind, customerName: String(r.CustomerName), detail: r.Kind === 'renewal' ? String(r.Detail) : (r.Products || []).map(function (p) { return p.name; }).join(', '),
      daysRemaining: r.DaysRemaining, overdue: !!r.Overdue, agentName: String(r.AgentName) };
  });
  var pendingDiscounts = isAgent ? null : svc_listPendingDiscounts(session).slice(0, 6);
  // An agent's own targets for this month (managers see the team target above).
  // This month vs last month (same visibility as everything above).
  var lastMonthPrefix = monthAdd(monthPrefix, -1);
  var comparison = { thisMonth: { count: 0, amount: 0 }, lastMonth: { count: 0, amount: 0 } };
  all.forEach(function (x) {
    if (x.row.Status !== 'Completed') return;
    var m = dateKey(x.row.Date).slice(0, 7);
    var slot = m === monthPrefix ? comparison.thisMonth : m === lastMonthPrefix ? comparison.lastMonth : null;
    if (slot) { slot.count++; slot.amount += Number(x.row.Amount) || 0; }
  });
  var myTargets = isAgent ? svc_getTargets(session, monthPrefix).rows.filter(function (r) { return r.target !== null; }) : null;

  return {
    totals: totals,
    temperature: temperature,
    modules: modulesList,
    remindersDue: remindersDue,
    pendingDiscounts: pendingDiscounts,
    myTargets: myTargets,
    comparison: comparison,
    agents: agentsArray,
    pipeline: {
      completed: counts.Completed, pending: counts.Pending, cancelled: counts.Cancelled, totalLeads: total,
      conversionRate: total > 0 ? Math.round((counts.Completed / total) * 100) : 0
    },
    topMedications: topMedications,
    paymentBreakdown: paymentBreakdown,
    recentAudits: recentAudits,
    recentActivities: recentActivities,
    urgentFollowUps: urgentFollowUps,
    monthlyTarget: {
      targetAmount: target,
      currentAmount: monthRevenue,
      percentage: Math.min(100, Math.round((monthRevenue / target) * 100)),
      month: monthPrefix
    }
  };
}


// ---- Setup.gs ----
// Setup.gs — one-time setup helpers. Run these from the Apps Script editor
// (select the function in the dropdown next to Run, then click Run), not
// from the web app.

// Creates every tab the CRM uses, or adds any missing columns to tabs that
// already exist. Safe to run any number of times; it never deletes data.
function setupSpreadsheet() {
  getUsersSheet();
  moduleIds().forEach(function (type) { getSaleSheet(type); });
  getPatientsSheet();
  getUserRequestsSheet();
  getUserLayoutsSheet();
  getTargetsSheet();
  getRemindersSheet();
  getActivitiesSheet();
  getListsSheet();
  getSettingsSheet();
  getAuditSheet(); // created protected so only the owner can edit it
  backfillContactKeys_();
  Logger.log('Sheets are ready. Next: set ADMIN_EMAIL / ADMIN_PASSWORD in Project Settings → Script properties, then run createFirstAdmin().');
}

// Rows saved before v2 have no ContactKey; fill it so duplicate-phone checks see them.
function backfillContactKeys_() {
  moduleIds().forEach(function (type) {
    var sheet = getSaleSheet(type);
    var headers = sheetHeaders(sheet);
    var keyCol = headers.indexOf('ContactKey');
    var contactCol = headers.indexOf('Contact');
    var lastRow = sheet.getLastRow();
    if (keyCol === -1 || contactCol === -1 || lastRow < 2) return;
    var contacts = sheet.getRange(2, contactCol + 1, lastRow - 1, 1).getValues();
    var keys = sheet.getRange(2, keyCol + 1, lastRow - 1, 1).getValues();
    var changed = false;
    for (var i = 0; i < contacts.length; i++) {
      if (!keys[i][0]) { keys[i][0] = phoneKey(contacts[i][0]); changed = true; }
    }
    if (changed) sheet.getRange(2, keyCol + 1, lastRow - 1, 1).setValues(keys);
  });
}

// Creates the first admin account WITHOUT putting a password in the code:
//  1. Project Settings (gear icon) → Script properties → add
//       ADMIN_EMAIL     your work email
//       ADMIN_PASSWORD  a temporary password (10+ chars, letters and numbers)
//  2. Run createFirstAdmin.
// The password property is deleted straight after, and the app makes you
// choose a new password on first login.
function createFirstAdmin() {
  var props = PropertiesService.getScriptProperties();
  var email = cleanEmail(props.getProperty('ADMIN_EMAIL'));
  var password = String(props.getProperty('ADMIN_PASSWORD') || '');
  var name = cleanText(props.getProperty('ADMIN_NAME') || 'Admin', 80);
  if (!email || !password) throw new Error('Set ADMIN_EMAIL and ADMIN_PASSWORD in Project Settings → Script properties first.');
  if (!isValidEmail(email)) throw new Error('ADMIN_EMAIL is not a valid email address.');
  validatePasswordStrength(password, email);

  var sheet = getUsersSheet();
  if (sheetToObjects(sheet).some(function (u) { return String(u.Email).toLowerCase() === email; })) {
    props.deleteProperty('ADMIN_PASSWORD');
    Logger.log('A user with that email already exists — nothing to do. (ADMIN_PASSWORD property removed.)');
    return;
  }

  var salt = generateSalt();
  var user = {
    ID: newId(),
    Name: name,
    Email: email,
    PasswordHash: hashPassword(password, salt),
    Salt: salt,
    Role: 'admin',
    MedpassFullRate: 0,
    MedpassDiscountRate: 0,
    PharmacyIncentivePercent: 0,
    Active: true,
    CreatedAt: nowIso(),
    MustChangePassword: true
  };
  appendObject(sheet, user);
  props.deleteProperty('ADMIN_PASSWORD');
  audit({ email: 'setup', name: 'Setup script', role: 'system' }, 'create', 'User', user.ID, null, 'First admin created: ' + email);
  Logger.log('Admin user created: ' + email + '. The temporary password was removed from Script properties.');
}

// ONE-TIME, after upgrading from a version that shared screenshots by link:
// makes every file in the attachments folder private. The app keeps showing
// them — it reads them through the backend. Safe to run more than once.
function lockDownExistingAttachments() {
  var files = getAttachmentsFolder().getFiles();
  var count = 0;
  while (files.hasNext()) {
    var file = files.next();
    if (file.getSharingAccess() !== DriveApp.Access.PRIVATE) {
      file.setSharing(DriveApp.Access.PRIVATE, DriveApp.Permission.NONE);
      count++;
    }
  }
  Logger.log('Made ' + count + ' attachment(s) private.');
}

// Rough timing check for PBKDF2_ITERATIONS. Run from the editor and look at
// the log: aim for well under 1 second per hash.
function timePasswordHash() {
  var start = Date.now();
  hashPassword('timing-test-password1', generateSalt());
  Logger.log('One password hash took ' + (Date.now() - start) + ' ms at ' + PBKDF2_ITERATIONS + ' iterations.');
}


// ---- SmokeTest.gs ----
// SmokeTest.gs — read-only health check for the v2 backend.
// Run smokeTestV2 from the editor after setup or a deploy and read the log.
// It saves nothing: the import is a dry run and the admin session it opens
// lives only in the cache and is logged out at the end.
function smokeTestV2() {
  var out = [];
  function call(action, token, payload) {
    var e = { parameter: { action: action }, postData: { length: 10 } };
    if (token) e.parameter.token = token;
    if (payload) e.parameter.payload = JSON.stringify(payload);
    return JSON.parse(doPost(e).getContent());
  }
  function check(name, ok, detail) { out.push((ok ? 'PASS ' : 'FAIL ') + name + (detail ? ' - ' + detail : '')); }
  var r = call('ping');
  check('ping returns v' + API_VERSION, r.version === API_VERSION, JSON.stringify(r));
  r = call('login', null, { email: 'nobody-' + Date.now() + '@example.com', password: 'Wrong-Pass-123' });
  check('login rejects unknown user', r.error === true && r.message === 'Invalid email or password.', r.message);
  r = call('listSales', 'bogus-token', { type: 'medpass' });
  check('bad token rejected', r.authError === true, r.message);
  r = JSON.parse(doGet().getContent());
  check('GET refused', r.error === true);
  moduleIds().forEach(function (t) {
    var n = SALE_TYPES[t];
    var h = sheetHeaders(getSheetByName(n));
    var miss = moduleHeaders(t).filter(function (x) { return h.indexOf(x) === -1; });
    check(n + ' has all its columns', miss.length === 0, miss.join(','));
  });
  ['SaleActivities', 'Settings', 'Lists', 'AuditLog', 'Reminders', 'Users', 'Patients', 'UserRequests', 'UserLayouts', 'Targets'].forEach(function (n) {
    check('tab ' + n + ' exists', !!getSpreadsheet().getSheetByName(n));
  });
  var admin = sheetToObjects(getSheetByName('Users')).filter(function (u) {
    return u.Role === 'admin' && isActive(u.Active) && !asBool(u.MustChangePassword);
  })[0];
  check('usable admin account exists', !!admin, admin ? admin.Email : 'none');
  if (admin) {
    var s = startSession(admin); // temporary session in the cache only; logged out below
    ['medpass', 'pharmacy'].forEach(function (t) {
      r = call('listSales', s.token, { type: t });
      check('listSales ' + t, !r.error, r.error ? r.message : r.sales.length + ' records');
    });
    r = call('dashboardSummary', s.token);
    check('dashboard', !r.error, r.error ? r.message : 'month revenue ' + r.summary.monthlyTarget.currentAmount + ' of ' + r.summary.monthlyTarget.targetAmount);
    r = call('listReminders', s.token, { includeResolved: true });
    check('reminders', !r.error, r.error ? r.message : r.reminders.length + ' reminders');
    r = call('listUsers', s.token);
    check('listUsers hides hashes', !r.error && r.users.every(function (u) { return u.PasswordHash === undefined && u.Salt === undefined; }), r.error ? r.message : r.users.length + ' users');
    r = call('getLists', s.token);
    check('dropdown lists', !r.error, r.error ? r.message : r.lists.channels.length + ' channels');
    r = call('importSales', s.token, { type: 'medpass', dryRun: true, rows: [{ customerName: 'Smoke Test', contact: '9000000000' }] });
    check('import preview (nothing saved)', !r.error && r.imported === 0, r.error ? r.message : r.valid + ' valid row');
    try { DriveApp.getFoldersByName(ATTACHMENTS_FOLDER_NAME).hasNext(); check('Drive access', true); } catch (e) { check('Drive access', false, e.message); }
    call('logout', s.token);
  }
  Logger.log(out.join('\n'));
  return out;
}


// ---- UserService.gs ----
// UserService.gs — user accounts (admins; senior managers for non-admin accounts) and incentive rates (managers+)

var USER_HEADERS = ['ID', 'Name', 'Email', 'PasswordHash', 'Salt', 'Role', 'MedpassFullRate', 'MedpassDiscountRate',
  'PharmacyIncentivePercent', 'Active', 'CreatedAt', 'MustChangePassword'];
var ROLES = ['admin', 'senior_manager', 'manager', 'agent'];

function getUsersSheet() { return getOrCreateSheet('Users', USER_HEADERS); }

// What the browser may see about a user — never the hash or salt.
function sanitizeUser(u) {
  return {
    ID: String(u.ID),
    Name: String(u.Name),
    Email: String(u.Email),
    Role: String(u.Role),
    MedpassFullRate: Number(u.MedpassFullRate) || 0,
    MedpassDiscountRate: Number(u.MedpassDiscountRate) || 0,
    PharmacyIncentivePercent: Number(u.PharmacyIncentivePercent) || 0,
    Active: isActive(u.Active),
    CreatedAt: isoString(u.CreatedAt),
    MustChangePassword: asBool(u.MustChangePassword)
  };
}

function svc_listUsers(session) {
  requireRole(session, TEAM_ROLES);
  return sheetToObjects(getUsersSheet()).filter(function (u) { return u.ID; }).map(sanitizeUser);
}

function svc_createUser(session, data) {
  requireRole(session, SENIOR_ROLES);

  var email = cleanEmail(data.email);
  var name = cleanText(data.name, 80);
  var role = String(data.role || '').trim();
  var password = String(data.password || '');

  if (!email || !name || !password) throw new Error('Name, email and password are required.');
  if (!isValidEmail(email)) throw new Error('Enter a valid email address.');
  requireOneOf(role, ROLES, 'Role');
  if (role === 'admin') requireRole(session, ADMIN_ROLES); // only admins create admins
  validatePasswordStrength(password, email);

  var sheet = getUsersSheet();
  if (sheetToObjects(sheet).some(function (u) { return String(u.Email).toLowerCase() === email; })) {
    throw new Error('A user with this email already exists.');
  }

  var salt = generateSalt();
  var user = {
    ID: newId(),
    Name: name,
    Email: email,
    PasswordHash: hashPassword(password, salt),
    Salt: salt,
    Role: role,
    MedpassFullRate: 0,
    MedpassDiscountRate: 0,
    PharmacyIncentivePercent: 0,
    Active: true,
    CreatedAt: nowIso(),
    MustChangePassword: true // the admin knows this password, so the user must pick their own
  };
  appendObject(sheet, user);
  audit(session, 'create', 'User', user.ID, auditDiff(null, user), 'Created ' + role + ' account for ' + email);
  return sanitizeUser(user);
}

function otherActiveAdmins(users, id) {
  return users.filter(function (u) {
    return String(u.ID) !== String(id) && u.Role === 'admin' && isActive(u.Active);
  });
}

function svc_updateUser(session, id, data) {
  requireRole(session, SENIOR_ROLES);
  var sheet = getUsersSheet();
  var users = sheetToObjects(sheet);
  var existing = users.find(function (u) { return String(u.ID) === String(id); });
  if (!existing) throw new Error('User not found.');
  // Admin accounts — and making someone an admin — are for admins only.
  if (existing.Role === 'admin' || data.role === 'admin') requireRole(session, ADMIN_ROLES);
  var patch = {};

  if (data.name !== undefined) {
    patch.Name = cleanText(data.name, 80);
    if (!patch.Name) throw new Error('Name is required.');
  }
  if (data.role !== undefined) {
    requireOneOf(String(data.role), ROLES, 'Role');
    patch.Role = String(data.role);
  }
  if (data.active !== undefined) patch.Active = data.active === true || data.active === 'true';
  if (data.password) {
    validatePasswordStrength(String(data.password), existing.Email);
    var salt = generateSalt();
    patch.Salt = salt; // new salt ends every session this user has open
    patch.PasswordHash = hashPassword(String(data.password), salt);
    patch.MustChangePassword = true;
  }

  // Never leave the CRM without an active admin — nobody could manage users.
  var losingAdmin = existing.Role === 'admin' && isActive(existing.Active) &&
    ((patch.Role !== undefined && patch.Role !== 'admin') || patch.Active === false);
  if (losingAdmin && otherActiveAdmins(users, id).length === 0) {
    throw new Error('This is the only active admin. Make someone else an admin first.');
  }

  // Someone who still handles patients can't simply be switched off: their
  // work goes to a successor first (see Handover.gs).
  if (patch.Active === false && isActive(existing.Active)) {
    var world = loadPatientWorld();
    var work = openWorkOf(world, existing.Email);
    if (hasOpenWork(work)) {
      if (!data.successorEmail) {
        throw new Error(existing.Name + ' still handles ' + work.patients.length + ' patient(s), ' + work.records.length +
          ' open record(s) and ' + work.reminders.length + ' reminder(s). Choose who takes over before deactivating.');
      }
      var successor = requireOwnerCandidate(world, data.successorEmail);
      if (lowerEmail(successor.email) === lowerEmail(existing.Email)) throw new Error('Choose someone else to take over.');
      handOverWork(session, world, existing, successor, 'Account of ' + existing.Name + ' deactivated by an admin.');
    }
  }

  var updated = updateObjectById(sheet, id, patch);
  if (!updated) throw new Error('User not found.');
  var changes = auditDiff(existing, patch);
  delete changes.MustChangePassword;
  if (patch.PasswordHash) changes.Password = { from: '', to: '(reset by admin)' };
  audit(session, 'update', 'User', id, changes, 'Updated account ' + existing.Email);
  return sanitizeUser(updated);
}

// Permanent removal is only allowed for accounts that never owned a record —
// otherwise their sales would lose their owner and incentive rates. Those
// accounts should be deactivated instead (they keep their history).
function svc_deleteUser(session, id, reason) {
  requireRole(session, ADMIN_ROLES); // hard delete: admins only
  var why = cleanText(reason, 300);
  if (why.length < 3) throw new Error('A reason is required to delete a user account.');
  if (String(id) === String(session.id)) throw new Error('You cannot delete your own account.');
  var sheet = getUsersSheet();
  var users = sheetToObjects(sheet);
  var existing = users.find(function (u) { return String(u.ID) === String(id); });
  if (!existing) throw new Error('User not found.');
  if (existing.Role === 'admin' && isActive(existing.Active) && otherActiveAdmins(users, id).length === 0) {
    throw new Error('Cannot delete the last active admin.');
  }
  var email = String(existing.Email).toLowerCase();
  var owns = Object.keys(SALE_TYPES).some(function (type) {
    return sheetToObjects(getSaleSheet(type)).some(function (s) { return String(s.AgentEmail).toLowerCase() === email; });
  });
  if (owns) throw new Error('This user has sales records. Deactivate the account instead so their history and incentives are kept.');

  var rowIndex = findRowIndexById(sheet, existing.ID);
  sheet.deleteRow(rowIndex);
  var snapshot = auditDiff(existing, null);
  audit(session, 'delete', 'User', existing.ID, snapshot, 'Deleted account ' + existing.Email + '. Reason: ' + why);
  return { deleted: true };
}

// Incentive rates are the one thing a manager (not just admin / senior manager) may edit.
// Medpass pays a flat ₹ rate per sale (Full Price vs Discounted); Pharmacy
// pays a percentage of the sale amount.
function svc_updateIncentives(session, id, data) {
  requireRole(session, TEAM_ROLES);
  var sheet = getUsersSheet();
  var patch = {};

  function rate(value, max, label) {
    var n = Number(value);
    if (value === '' || isNaN(n) || n < 0 || n > max) throw new Error(label + ' must be a number between 0 and ' + max + '.');
    return n;
  }
  if (data.medpassFullRate !== undefined && data.medpassFullRate !== '') patch.MedpassFullRate = rate(data.medpassFullRate, 1e6, 'Medpass Full Price rate');
  if (data.medpassDiscountRate !== undefined && data.medpassDiscountRate !== '') patch.MedpassDiscountRate = rate(data.medpassDiscountRate, 1e6, 'Medpass Discounted rate');
  if (data.pharmacyIncentivePercent !== undefined && data.pharmacyIncentivePercent !== '') patch.PharmacyIncentivePercent = rate(data.pharmacyIncentivePercent, 100, 'Pharmacy incentive percent');

  var existing = sheetToObjects(sheet).find(function (u) { return String(u.ID) === String(id); });
  if (!existing) throw new Error('User not found.');
  var updated = updateObjectById(sheet, id, patch);
  audit(session, 'update_incentives', 'User', id, auditDiff(existing, patch), 'Updated incentive rates for ' + existing.Email);
  return sanitizeUser(updated);
}


// ---- Utils.gs ----
// Utils.gs — generic helpers for reading/writing sheet rows as objects

// ===== Per-request read cache =====
// Every Sheets call is a round trip (100–200 ms). A list request used to read
// each tab several times (find it, check its columns, count rows, read the
// header, read the rows): ~50 calls. For read-only actions, Code.gs wraps the
// request in withReadCache(), and each tab is then looked up and read once.
// Writing actions never use it, and every write helper below clears it, so a
// read after a write always sees the sheet as it is now.
var readCache_ = null;

function withReadCache(fn) {
  readCache_ = { sheets: {}, values: [] };
  try { return fn(); } finally { readCache_ = null; }
}

function clearReadCache_() {
  if (readCache_) readCache_ = { sheets: {}, values: [] };
}

// The whole tab (header row included) as a 2-D array.
function sheetValues_(sheet) {
  if (readCache_) {
    for (var i = 0; i < readCache_.values.length; i++) {
      if (readCache_.values[i].sheet === sheet) return readCache_.values[i].values;
    }
  }
  var lastRow = sheet.getLastRow();
  var lastCol = sheet.getLastColumn();
  var values = lastRow && lastCol ? sheet.getRange(1, 1, lastRow, lastCol).getValues() : [];
  if (readCache_) readCache_.values.push({ sheet: sheet, values: values });
  return values;
}

function getSpreadsheet() {
  return SpreadsheetApp.getActiveSpreadsheet();
}

// Looked up once per request while the read cache is on.
function findSheet_(name) {
  if (readCache_ && readCache_.sheets.hasOwnProperty(name)) return readCache_.sheets[name];
  var sheet = getSpreadsheet().getSheetByName(name);
  if (readCache_ && sheet) readCache_.sheets[name] = sheet;
  return sheet;
}

function getSheetByName(name) {
  var sheet = findSheet_(name);
  if (!sheet) throw new Error('Sheet not found: ' + name + '. Run setupSpreadsheet() first.');
  return sheet;
}

// Returns the named tab, creating it (with a frozen header row) if it
// doesn't exist yet, and appending any missing header columns to the end if
// it does. Lets new features add tabs/columns without anyone hand-editing
// the spreadsheet after a deploy.
function getOrCreateSheet(name, headers) {
  var sheet = findSheet_(name);
  if (!sheet) {
    sheet = getSpreadsheet().insertSheet(name);
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
    sheet.setFrozenRows(1);
    clearReadCache_();
    return sheet;
  }
  ensureHeaders(sheet, headers);
  return sheet;
}

function ensureHeaders(sheet, headers) {
  var existing = sheetHeaders(sheet);
  var missing = headers.filter(function (h) { return existing.indexOf(h) === -1; });
  if (missing.length === 0) return;
  sheet.getRange(1, existing.length + 1, 1, missing.length).setValues([missing]);
  clearReadCache_();
}

function sheetHeaders(sheet) {
  if (readCache_) {
    var cached = sheetValues_(sheet);
    return cached.length ? cached[0] : [];
  }
  var lastCol = sheet.getLastColumn();
  if (lastCol === 0) return [];
  return sheet.getRange(1, 1, 1, lastCol).getValues()[0];
}

function sheetToObjects(sheet) {
  var headers, values;
  if (readCache_) {
    var all = sheetValues_(sheet);
    if (all.length < 2) return [];
    headers = all[0];
    values = all.slice(1);
  } else {
    var lastRow = sheet.getLastRow();
    var lastCol = sheet.getLastColumn();
    if (lastRow < 2 || lastCol === 0) return [];
    headers = sheetHeaders(sheet);
    values = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
  }
  var out = [];
  for (var r = 0; r < values.length; r++) {
    var obj = {};
    for (var c = 0; c < headers.length; c++) {
      obj[headers[c]] = values[r][c];
    }
    out.push(obj);
  }
  return out;
}

// Sheets treats any text starting with = + - @ as a formula, so a customer
// name like "=IMPORTXML(...)" would run instead of being stored. A leading
// apostrophe forces plain text; Sheets hides it and doesn't return it from
// getValues(), so the value reads back exactly as typed. (This also stops
// phone numbers like "+91 98480 12345" from being parsed as a formula.)
// Digit strings with a leading zero or more than 15 digits (phone numbers,
// UTRs) would be turned into numbers and lose digits, so keep them as text.
// Months like "2026-10" (targets) would become dates; keep those as text too.
function safeCellValue(v) {
  if (typeof v === 'string' && (/^[=+\-@\t\r]/.test(v) || /^0\d+$/.test(v) || /^\d{16,}$/.test(v) || /^\d{4}-\d{2}$/.test(v))) return "'" + v;
  return v;
}

function appendObject(sheet, obj) {
  var headers = sheetHeaders(sheet);
  var row = headers.map(function (h) { return safeCellValue((obj[h] !== undefined) ? obj[h] : ''); });
  sheet.appendRow(row);
  clearReadCache_();
  return obj;
}

function findRowIndexById(sheet, id) {
  var headers = sheetHeaders(sheet);
  var idCol = headers.indexOf('ID');
  if (idCol === -1) throw new Error('Sheet has no ID column');
  var lastRow = sheet.getLastRow();
  if (lastRow < 2) return -1;
  var ids = sheet.getRange(2, idCol + 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(id)) return i + 2;
  }
  return -1;
}

function updateObjectById(sheet, id, patch) {
  var rowIndex = findRowIndexById(sheet, id);
  if (rowIndex === -1) return null;
  var headers = sheetHeaders(sheet);
  var lastCol = sheet.getLastColumn();
  var currentValues = sheet.getRange(rowIndex, 1, 1, lastCol).getValues()[0];
  var current = {};
  headers.forEach(function (h, i) { current[h] = currentValues[i]; });
  var updated = Object.assign({}, current, patch);
  var newRow = headers.map(function (h) { return safeCellValue(updated[h] !== undefined ? updated[h] : ''); });
  sheet.getRange(rowIndex, 1, 1, lastCol).setValues([newRow]);
  clearReadCache_();
  return updated;
}

function newId() {
  return Utilities.getUuid();
}

function nowIso() {
  return new Date().toISOString();
}

// ===== Calendar dates =====
// Sale dates are calendar days ("2026-10-12"), not moments in time. They are
// always handled as 'yyyy-MM-dd' strings in India time, so a sale logged at
// 1 AM IST lands on the right day (new Date().toISOString() is UTC and would
// give yesterday's date until 5:30 AM).
var APP_TIMEZONE = 'Asia/Kolkata';
var DAY_MS = 24 * 60 * 60 * 1000;
var spreadsheetTimeZone_ = null;

function todayKey() {
  return Utilities.formatDate(new Date(), APP_TIMEZONE, 'yyyy-MM-dd');
}

// Sheets turns a typed "2026-10-12" into a Date cell (midnight in the
// spreadsheet's time zone). Reading it back gives a Date object, which
// JSON-encodes as UTC — e.g. "2026-10-11T18:30:00.000Z" — and shows up a day
// early in the edit form. This turns either shape back into 'yyyy-MM-dd'.
function dateKey(value) {
  if (Object.prototype.toString.call(value) === '[object Date]') {
    if (isNaN(value.getTime())) return '';
    if (!spreadsheetTimeZone_) spreadsheetTimeZone_ = getSpreadsheet().getSpreadsheetTimeZone() || APP_TIMEZONE;
    return Utilities.formatDate(value, spreadsheetTimeZone_, 'yyyy-MM-dd');
  }
  var s = String(value || '').trim();
  return /^\d{4}-\d{2}-\d{2}/.test(s) ? s.slice(0, 10) : s;
}

// Real calendar days only: "2026-02-31" is rejected (Date.UTC would roll it to March).
function isDateKey(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) return false;
  var n = keyToDayNumber(s);
  return !isNaN(n) && dayNumberToKey(n) === String(s);
}

// Whole days since 1970-01-01 for a 'yyyy-MM-dd' key — lets us add and
// subtract days without any time-zone or daylight-saving surprises.
function keyToDayNumber(key) {
  var p = String(key).split('-');
  return Date.UTC(Number(p[0]), Number(p[1]) - 1, Number(p[2])) / DAY_MS;
}

function dayNumberToKey(n) {
  return new Date(n * DAY_MS).toISOString().slice(0, 10);
}

// Runs fn while holding the script-wide lock, so read-modify-write sequences
// on the sheet (find row → change → write back, or delete a row) can't
// interleave between two requests and land on the wrong row.
function withScriptLock(fn) {
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) {
    throw new Error('The server is busy saving other changes. Please try again in a few seconds.');
  }
  try {
    return fn();
  } finally {
    SpreadsheetApp.flush();
    lock.releaseLock();
  }
}

// ===== Input hygiene =====
// Every free-text value from the browser goes through cleanText: control
// characters are stripped, it's trimmed, and it's cut to a sane length so
// nobody can stuff megabytes into a single cell.
var MAX_TEXT = 200;
var MAX_LONG_TEXT = 2000;

function cleanText(value, maxLen) {
  var s = String(value === undefined || value === null ? '' : value);
  s = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim();
  return s.slice(0, maxLen || MAX_TEXT);
}

function cleanEmail(value) {
  return cleanText(value, 254).toLowerCase();
}

function isValidEmail(s) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s));
}

function asBool(value) {
  return value === true || String(value).toUpperCase() === 'TRUE';
}

// Phone numbers are compared on their last 10 digits, so "+91 98480 12345",
// "098480-12345" and "9848012345" are all the same customer.
function phoneKey(value) {
  var digits = String(value || '').replace(/\D/g, '');
  if (digits.length < 6) return '';
  return digits.length > 10 ? digits.slice(-10) : digits;
}

function requireOneOf(value, allowed, label) {
  if (allowed.indexOf(value) === -1) throw new Error(label + ' must be one of: ' + allowed.join(', ') + '.');
}

function optionalDateKey(value, label) {
  var v = dateKey(value);
  if (!v) return '';
  if (!isDateKey(v)) throw new Error(label + ' must be a valid date (YYYY-MM-DD).');
  return v;
}

function isoString(value) {
  if (Object.prototype.toString.call(value) === '[object Date]') return isNaN(value.getTime()) ? '' : value.toISOString();
  return String(value || '');
}

// ===== Rate limiting =====
// A fixed one-minute window per key in CacheService. Stops a stolen or buggy
// session from hammering the sheet (Apps Script has daily quotas, and the
// script lock means one runaway client slows everybody down).
var RATE_LIMIT_PER_MINUTE = 120;

function checkRateLimit(key) {
  var cache = CacheService.getScriptCache();
  var bucket = 'rl_' + key + '_' + Math.floor(Date.now() / 60000);
  var n = Number(cache.get(bucket)) || 0;
  if (n >= RATE_LIMIT_PER_MINUTE) {
    throw new Error('Too many requests. Please wait a minute and try again.');
  }
  cache.put(bucket, String(n + 1), 120);
}

function jsonResponse(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}

  return { doPost, setupSpreadsheet, createFirstAdmin };
}
